INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C1','kor',4,2,'u1',2,'이 단원에서 배울 두 가지 — 작품 속 세계와 현실 세계를 비교하며 감상하기 · 서로 다른 글쓴이의 의견을 비교하며 읽기 — 둘 다 나란히 놓고 닮은 점과 다른 점을 따지는 일',ARRAY['[4국05-02][4국02-04]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C2','kor',4,2,'u1',2,'작품 속 세계와 현실 세계 — 작품에는 현실과 비슷한 부분과 상상해 꾸며 쓴 부분이 함께 있음 — 작품 속 세계는 현실과 똑같지도, 아주 동떨어지지도 않음',ARRAY['[4국05-02][4국05-05]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C3','kor',4,2,'u1',2,'꾸며 쓴 부분이 하는 일 — 꾸며 쓴 부분은 거짓말이 아니라 상상하는 재미를 주고 인물의 마음이나 글쓴이의 생각을 더 또렷하게 보여 주는 방법',ARRAY['[4국05-02][4국05-05]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C4','kor',4,2,'u1',2,'마음에 남는 장면은 사람마다 — 같은 작품을 읽어도 마음에 남는 장면과 생각은 사람마다 다를 수 있음 — 하나가 잘못 읽은 것이 아님',ARRAY['[4국05-02][4국05-05]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C5','kor',4,2,'u1',2,'인상 깊은 장면과 까닭 — 인상 깊은 장면을 말할 때는 작품 속 장면과 왜 그 장면인지 까닭을 함께 말함',ARRAY['[4국05-02][4국05-05]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C6','kor',4,2,'u1',2,'내 경험 떠올리기 — 내 경험을 떠올리며 읽으면 작품에서 현실과 닮은 부분과 다른 부분이 잘 보임',ARRAY['[4국05-02][4국05-05]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C7','kor',4,2,'u1',2,'작품과 현실 견주기 — 같은 대상(신호등·초록불·자동차)을 다룬 것끼리 작품에 나타난 모습과 현실의 모습을 나란히 놓고 견줌',ARRAY['[4국05-02][4국05-05]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C8','kor',4,2,'u1',2,'작품 전체가 글쓴이가 만든 세계 — 말하거나 움직이는 사물만 꾸민 것이 아니라, 현실과 닮은 부분도 글쓴이가 전하려는 모습을 그리려고 골라 엮은 것 — 그렇다고 견줄 필요가 없는 것도 아님',ARRAY['[4국05-02][4국05-05]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C9','kor',4,2,'u1',2,'말하는 이가 바라는 모습 — 「뛰지 않아도 되는 길」·「느긋한 우리 동네」처럼 시 속 말을 근거로 말하는 이가 현실에 바라는 모습을 찾음',ARRAY['[4국05-02][4국05-05]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C10','kor',4,2,'u1',2,'바꾸어 쓰기 — 현실과 비교한 것을 바탕으로 내가 바라는 모습을 상상해 작품의 한 부분을 바꾸어 쓰고 바꾼 까닭을 말함',ARRAY['[4국05-02][4국05-05]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C11','kor',4,2,'u1',2,'작품과 현실을 비교하면 좋은 점 — 현실의 모습을 되돌아볼 수 있고, 현실과 다른 세계를 상상해 볼 수 있고, 익숙한 모습을 새로운 눈으로 볼 수 있음',ARRAY['[4국05-02][4국05-05]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C12','kor',4,2,'u1',4,'「골목 끝 빨간 우체통」 내용 — 처음 — 이사 온 은호가 말을 걸지 못함 · 가운데 — 이름만 적은 편지에 이름 없는 답장이 옴 · 끝 — 은호가 해린이에게 먼저 말을 걸고 둘이 마지막 편지를 넣음',ARRAY['[4국05-02][4국05-05]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C13','kor',4,2,'u1',4,'인물의 마음을 담은 낱말 — 낯설다(겪어 보지 않아 익숙하지 않다) · 머뭇거리다(선뜻 하지 못하고 망설이다) · 서성이다(한곳에 머물지 않고 왔다 갔다 하다)',ARRAY['[4국05-02][4국05-05]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C14','kor',4,2,'u1',4,'말과 행동으로 성격 짐작하기 — 한 장면만이 아니라 처음과 끝의 말과 행동을 함께 보고 인물의 성격을 짐작함',ARRAY['[4국05-02][4국05-05]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C15','kor',4,2,'u1',4,'이야기를 나와 관련짓기 — 비슷한 경험을 떠올리고, 경험이 없으면 책이나 영상에서 본 일을 떠올려 인물과 견줌',ARRAY['[4국05-02][4국05-05]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C16','kor',4,2,'u1',4,'평범해 보이는 일도 현실과 다를 수 있음 — 움직이는 그림자처럼 눈에 띄는 것만 꾸민 부분이 아님 — 주소 없는 편지에 답장이 오는 일처럼 평범해 보여도 현실의 규칙과 견주면 일어날 수 없는 일이 있음',ARRAY['[4국05-02][4국05-05]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C17','kor',4,2,'u1',4,'닮은 부분과 꾸민 부분이 주는 것 — 현실과 닮은 부분은 읽는 사람이 공감하게 하고, 꾸며 쓴 부분은 재미와 감동, 깨달음을 줌',ARRAY['[4국05-02][4국05-05]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C18','kor',4,2,'u1',4,'글쓴이가 전하려는 생각 — 이야기 속 근거를 대어 찾음 — 근거가 서면 여러 갈래로 받아들일 수 있지만, 꾸민 장치를 그대로 믿는 생각이나 이야기와 거꾸로인 생각은 알맞지 않음',ARRAY['[4국05-02][4국05-05]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C19','kor',4,2,'u1',4,'세상과 연결하기 — 이야기를 읽고 내 주변에서 도움이 필요한 사람을 떠올려 현실에서 할 수 있는 도움 방법을 상상함',ARRAY['[4국05-02][4국05-05]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C20','kor',4,2,'u1',7,'같은 문제, 다른 의견 — 같은 일을 두고도 사람마다 의견과 그렇게 생각한 이유가 다를 수 있음',ARRAY['[4국02-04]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C21','kor',4,2,'u1',7,'두 글이 다루는 문제 — 두 글이 함께 다루는 문제(뒤뜰 화단에 무엇을 심을까)를 찾고, 생각이 같은 곳과 갈린 곳을 가름',ARRAY['[4국02-04]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C22','kor',4,2,'u1',7,'글쓴이마다 이유 가르기 — 각 글쓴이가 자기 의견을 받쳐 주려고 든 이유를 찾아, 다른 글쓴이의 이유와 섞지 않고 가름',ARRAY['[4국02-04]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C23','kor',4,2,'u1',7,'의견을 비교하며 읽으면 좋은 점 — 같은 문제에 대한 여러 생각을 알 수 있음 · 내 의견을 정하는 데 도움이 됨 · 어느 의견이 더 알맞은지 따져 볼 수 있음',ARRAY['[4국02-04]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C24','kor',4,2,'u1',7,'다른 의견은 틀린 의견이 아님 — 의견이 반대라고 하나가 틀린 것이 아니며, 다 맞으니 따질 필요가 없는 것도 아님 — 이유가 알맞은지 따져 봄',ARRAY['[4국02-04]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C25','kor',4,2,'u1',7,'새로운 의견 — 두 글쓴이의 의견 가운데 하나를 고르지 않고 새로운 의견을 내어도 됨',ARRAY['[4국02-04]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C26','kor',4,2,'u1',8,'의견과 이유 — 의견은 어떤 문제에 대해 글쓴이가 가진 생각, 이유는 그렇게 생각한 까닭 — 있었던 일(사실)과 다름',ARRAY['[4국02-04]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C27','kor',4,2,'u1',8,'제목은 실마리 — 제목으로 의견을 짐작할 수 있지만 물음으로 된 제목은 거꾸로 읽힐 수 있음 — 제목이 곧 의견도, 아예 안 볼 것도 아님',ARRAY['[4국02-04]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C28','kor',4,2,'u1',8,'의견을 파악하는 차례 — 제목으로 짐작 → 글 끝부분의 「그러므로·그래서 ~해야 합니다·제안합니다」에서 확인 → 의견을 받쳐 주는 이유 찾기',ARRAY['[4국02-04]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C29','kor',4,2,'u1',8,'같은 것을 다르게 보는 두 글 — 두 글쓴이는 같은 대상(칭찬 스티커판)을 보고도 좋은 점과 걱정되는 점을 다르게 봄 — 한쪽이 잘못 본 것이 아님',ARRAY['[4국02-04]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C30','kor',4,2,'u1',8,'생활 속 글의 의견 — 학교 누리집 글·학급 신문·어린이 기사에도 의견이 있으며, 여러 의견을 알면 문제를 푸는 더 나은 방법을 찾을 수 있음',ARRAY['[4국02-04]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C31','kor',4,2,'u1',10,'의견을 말할 때 쓰는 낱말 — 두루(빠짐없이 골고루) · 배려(남을 도우려고 마음을 씀) · 제안(생각이나 방법을 내놓음)',ARRAY['[4국02-04][4국01-06]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C32','kor',4,2,'u1',10,'의견을 평가하는 세 가지 기준 — 문제 상황에 알맞은 의견인가 · 의견을 받쳐 주는 이유가 믿을 만한가 · 그 의견대로 했을 때 다른 문제가 생기지 않는가',ARRAY['[4국02-04][4국01-06]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C33','kor',4,2,'u1',10,'믿기 어려운 이유 — 뒷받침할 경험이나 까닭 없이 「한 명도·모두·반드시」로 장담하는 이유는 믿기 어려움',ARRAY['[4국02-04][4국01-06]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C34','kor',4,2,'u1',10,'의견대로 했을 때 생길 문제 — 그 의견대로 했을 때 누가 어떤 어려움을 겪을지 살핌(다른 쪽 글이 걱정한 일이 실마리)',ARRAY['[4국02-04][4국01-06]']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C35','kor',4,2,'u1',10,'이유의 개수가 아니라 이유의 힘 — 이유가 많다고 더 알맞은 의견이 아니며, 이유와 상관없이 마음에 드는 쪽을 고르는 것도 평가가 아님',ARRAY['[4국02-04][4국01-06]']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C36','kor',4,2,'u1',10,'어느 의견이든 같은 기준으로 — 한쪽만 따지고 다른 쪽은 그냥 믿으면 공평한 평가가 아님 — 두 의견 모두 같은 세 가지 기준으로 따짐',ARRAY['[4국02-04][4국01-06]']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C37','kor',4,2,'u1',10,'내 의견 정하기 — 내 의견은 글쓴이와 같아도 달라도 됨 — 두 의견을 섞은 새 의견도 저절로 더 좋아지지 않으니 같은 기준으로 따짐',ARRAY['[4국02-04][4국01-06]']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C38','kor',4,2,'u1',10,'의견을 나타내는 글과 평가 — 「~해야 한다」·「~라고 생각한다」로 의견을 쓰고 이유를 구체적으로 씀 · 친구 글은 의견이 달라도 존중하며 이유를 중심으로 말해 줌',ARRAY['[4국02-04][4국01-06]']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C39','kor',4,2,'u1',12,'현실과 견주어 작품 소개하기 — 작품 제목 · 현실과 비슷한 점과 다른 점 · 꾸며 쓴 부분이 준 재미나 깨달음을 담음(줄거리 옮기기·「재미있었다」 한마디는 소개가 아님)',ARRAY['[4국05-02][4국02-04][4국01-06]']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C40','kor',4,2,'u1',12,'게시글과 댓글의 의견·이유 — 누가 한 말인지 먼저 가린 뒤 게시글과 댓글에서 각각 의견과 이유를 찾음',ARRAY['[4국05-02][4국02-04][4국01-06]']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C41','kor',4,2,'u1',12,'두 의견이 함께 걱정하는 것 — 맞선 두 의견도 같은 문제(안전)를 걱정할 수 있음 — 걱정하는 사람이 다를 뿐이며, 둘 다 직접 겪은 일을 이유로 듦',ARRAY['[4국05-02][4국02-04][4국01-06]']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C42','kor',4,2,'u1',12,'의견을 나누는 댓글 — 의견과 이유가 드러나고 다른 사람을 존중하는 말투로 씀(외치기만·「저도요」·깎아내리기는 알맞지 않음)',ARRAY['[4국05-02][4국02-04][4국01-06]']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C43','kor',4,2,'u1',12,'하려는 뜻의 「-려고」 — 받침 없는 말 + 려고(보려고) · 받침 있는 말 + 으려고(먹으려고) · 원래 ㄹ 받침인 말은 그대로(놀려고·만들려고) — 원래 없던 ㄹ을 덧붙이면 틀림(볼려고)',ARRAY['기초 다지기(문법·쓰기 — 성취기준 번호 확인 필요)']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C44','kor',4,2,'u1',12,'「-(으)ㅁ」을 붙여 바꾼 낱말 — 받침 없으면 ㅁ(그림) · 받침 있으면 음(믿음) · ㄹ 받침에 ㅁ이 붙으면 ㄻ(만듦·힘듦)',ARRAY['기초 다지기(문법·쓰기 — 성취기준 번호 확인 필요)']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C45','kor',4,2,'u1',12,'ㄲ·ㅆ 받침 글씨 — 닦다·묶다·샀다·왔다처럼 ㄲ·ㅆ 받침을 ㄱ·ㅅ으로 바꾸지 않고 바르게 씀',ARRAY['기초 다지기(문법·쓰기 — 성취기준 번호 확인 필요)']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X01','kor',4,'u1',ARRAY['K4-2-u1-C2','K4-2-u1-C8']::text[],'작품 속 세계를 현실과 똑같다고 여기거나 작품 속 일을 실제로 있었던 일이라고 믿는다','글쓴이가 만든 세계예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X02','kor',4,'u1',ARRAY['K4-2-u1-C3']::text[],'현실과 다르게 꾸며 쓴 부분을 거짓말이나 고쳐야 할 잘못으로 여긴다','꾸민 부분이 주는 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X03','kor',4,'u1',ARRAY['K4-2-u1-C4']::text[],'같은 작품을 읽고 마음에 남는 장면이 다르면 하나는 잘못 읽은 것이라고 여긴다','겪은 일이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X04','kor',4,'u1',ARRAY['K4-2-u1-C5']::text[],'인상 깊은 장면만 말하고 까닭은 말하지 않거나, 작품에 없는 장면을 든다','장면 + 왜 그 장면인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X05','kor',4,'u1',ARRAY['K4-2-u1-C8','K4-2-u1-C16']::text[],'꾸며 쓴 부분을 말하거나 움직이는 사물에서만 찾아, 그 밖의 부분은 모두 실제로 있었던 일이라고 여긴다','평범해 보여도 현실과 다를 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X06','kor',4,'u1',ARRAY['K4-2-u1-C8','K4-2-u1-C11']::text[],'작품은 다 꾸민 것이라 현실과 견주어 볼 필요가 없다고 여긴다','견주면 현실이 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X07','kor',4,'u1',ARRAY['K4-2-u1-C7']::text[],'작품과 현실을 견줄 때 서로 다른 대상끼리 잇거나 현실의 모습을 잘못 안다','같은 대상끼리 나란히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X08','kor',4,'u1',ARRAY['K4-2-u1-C9']::text[],'말하는 이가 바라는 모습을 시 속 말과 상관없이 짐작한다','시에 나온 말을 근거로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X09','kor',4,'u1',ARRAY['K4-2-u1-C10']::text[],'바꾸어 쓰기를 현실과 견주지 않고 아무 낱말이나 바꾸거나 외워 쓰는 일로 여긴다','내가 바라는 모습 + 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X10','kor',4,'u1',ARRAY['K4-2-u1-C11']::text[],'작품과 현실을 비교하는 까닭을 작품에서 틀린 곳을 찾아 알려 주는 것으로 여긴다','현실을 되돌아보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X11','kor',4,'u1',ARRAY['K4-2-u1-C12']::text[],'이야기에서 일어난 일의 내용이나 차례를 잘못 읽는다','그 줄을 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X12','kor',4,'u1',ARRAY['K4-2-u1-C13','K4-2-u1-C31']::text[],'낱말의 뜻을 엇갈리게 알거나 문장에 맞지 않는 낱말을 넣는다','낱말이 나온 문장을 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X13','kor',4,'u1',ARRAY['K4-2-u1-C14']::text[],'한 장면만 보거나 말과 행동과 상관없는 것을 보고 인물의 성격을 정한다','처음과 끝을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X14','kor',4,'u1',ARRAY['K4-2-u1-C15']::text[],'인물과 똑같은 일을 겪어야만 이야기를 나와 관련지을 수 있다고 여긴다','책·영상에서 본 일도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X15','kor',4,'u1',ARRAY['K4-2-u1-C17']::text[],'현실과 닮은 부분과 꾸며 쓴 부분이 하는 일을 엇갈리게 안다','공감 · 재미와 깨달음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X16','kor',4,'u1',ARRAY['K4-2-u1-C18']::text[],'꾸며 쓴 장치를 그대로 믿는 생각을 글쓴이가 전하려는 생각으로 고른다','장치가 아니라 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X17','kor',4,'u1',ARRAY['K4-2-u1-C18']::text[],'전하려는 생각은 하나뿐이라 다른 생각은 틀렸다고 여기거나, 이야기와 거꾸로이거나 근거 없는 생각을 고른다','이야기 속 근거가 서나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X18','kor',4,'u1',ARRAY['K4-2-u1-C21']::text[],'두 글이 다루는 같은 문제를 찾지 못하거나 생각이 같은 곳과 갈린 곳을 가르지 못한다','두 글이 똑같이 말하는 대상') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X19','kor',4,'u1',ARRAY['K4-2-u1-C22','K4-2-u1-C40']::text[],'두 글쓴이의 이유를 섞거나 의견과 상관없는 것을 이유로 고른다','누구의 의견을 받쳐 주나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X20','kor',4,'u1',ARRAY['K4-2-u1-C23']::text[],'의견을 비교하며 읽는 것을 더 긴 글 따르기나 나와 같은 의견만 골라 읽기로 여긴다','여러 생각 · 내 의견 · 따져 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X21','kor',4,'u1',ARRAY['K4-2-u1-C20','K4-2-u1-C24']::text[],'의견이 반대면 둘 가운데 하나는 틀렸다고 여기거나 먼저 쓴 쪽을 따른다','다른 것과 틀린 것은 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X22','kor',4,'u1',ARRAY['K4-2-u1-C24','K4-2-u1-C35']::text[],'의견은 다 맞으니 이유를 따져 볼 필요 없이 마음에 드는 쪽을 고르면 된다고 여긴다','이유를 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X23','kor',4,'u1',ARRAY['K4-2-u1-C25','K4-2-u1-C37']::text[],'두 글쓴이의 의견 가운데 하나를 반드시 골라야 하고 새로운 의견은 낼 수 없다고 여긴다','새 의견도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X24','kor',4,'u1',ARRAY['K4-2-u1-C26']::text[],'의견과 이유, 있었던 일(사실)을 가르지 못한다','생각 · 까닭 · 있었던 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X25','kor',4,'u1',ARRAY['K4-2-u1-C27']::text[],'제목만 보고 의견을 정한다(물음으로 된 제목도 그대로 또는 무조건 거꾸로 읽는다)','제목은 실마리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X26','kor',4,'u1',ARRAY['K4-2-u1-C27','K4-2-u1-C28']::text[],'제목은 믿을 수 없으니 아예 보지 않는다','짐작에는 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X27','kor',4,'u1',ARRAY['K4-2-u1-C28']::text[],'의견을 글 앞부분의 있었던 일이나 아무 문장에서 찾고 끝부분에서 확인하지 않는다','그러므로 · 그래서 ~') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X28','kor',4,'u1',ARRAY['K4-2-u1-C29','K4-2-u1-C41']::text[],'같은 대상을 두고 다르게 본 것을 한쪽이 잘못 보았거나 상대를 모르고 반대한 것으로 여긴다','무엇을 걱정했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X29','kor',4,'u1',ARRAY['K4-2-u1-C30']::text[],'의견을 찾아 읽는 일을 국어 시간 글에서만 하는 일로 여긴다','누리집 · 신문 · 기사') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X30','kor',4,'u1',ARRAY['K4-2-u1-C32']::text[],'의견을 평가하는 기준을 글의 길이·글씨·글쓴이가 누구인지로 잡는다','알맞은가 · 믿을 만한가 · 다른 문제는?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X31','kor',4,'u1',ARRAY['K4-2-u1-C33']::text[],'뒷받침할 까닭 없이 장담하는 이유(한 명도·모두·반드시)를 믿을 만한 이유로 여기거나, 경험이 받쳐 주는 이유를 믿기 어렵다고 여긴다','뒷받침할 경험이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X32','kor',4,'u1',ARRAY['K4-2-u1-C34']::text[],'의견대로 했을 때 생길 다른 문제를 살피지 않거나 의견과 상관없는 일을 든다','누가 어떤 어려움을?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X33','kor',4,'u1',ARRAY['K4-2-u1-C35']::text[],'이유가 많은 의견이 언제나 더 알맞다고 여기거나, 이유가 적으면 틀린 의견이라고 여긴다','개수 말고 힘') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X34','kor',4,'u1',ARRAY['K4-2-u1-C36']::text[],'한쪽 의견만 따지고 다른 쪽(내 의견과 같은 쪽·경험을 든 쪽)은 그냥 믿는다','같은 기준으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X35','kor',4,'u1',ARRAY['K4-2-u1-C37']::text[],'두 의견을 반씩 섞으면 저절로 가장 좋은 의견이 된다고 여긴다','섞은 의견도 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X36','kor',4,'u1',ARRAY['K4-2-u1-C38']::text[],'의견 글이나 평가에서 이유 없이 의견만 내세우거나 나와 다른 의견을 틀렸다고 말한다','이유 중심 · 존중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X37','kor',4,'u1',ARRAY['K4-2-u1-C39']::text[],'작품 소개를 줄거리 옮기기나 「재미있었다」 한마디, 상관없는 정보로 여긴다','현실과 견준 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X38','kor',4,'u1',ARRAY['K4-2-u1-C42']::text[],'댓글을 이유 없이 외치거나 「저도요」 한마디로 쓰거나 상대를 깎아내린다','의견 + 이유 + 존중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X39','kor',4,'u1',ARRAY['K4-2-u1-C43']::text[],'원래 없던 ㄹ을 덧붙여 「-ㄹ려고」로 쓴다(볼려고·쓸려고)','기본형에 ㄹ이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X40','kor',4,'u1',ARRAY['K4-2-u1-C43']::text[],'원래 ㄹ 받침이 있는 말에서 ㄹ을 빼거나 「-으려고」를 붙여 쓴다(노려고·만드려고)','놀다 → 놀려고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X41','kor',4,'u1',ARRAY['K4-2-u1-C44']::text[],'「-(으)ㅁ」을 붙일 때 받침에 따라 ㅁ·음·ㄻ을 엇갈리게 쓴다(만듬·그리음)','받침 없음 · 있음 · ㄹ') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X42','kor',4,'u1',ARRAY['K4-2-u1-C45']::text[],'ㄲ·ㅆ 받침을 ㄱ·ㅅ이나 다른 받침으로 쓴다(닥다·왓다)','쌍받침 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X43','kor',4,'u1',ARRAY['K4-2-u1-C24','K4-2-u1-C38']::text[],'다른 의견을 존중하라는 말을 다툼이 없게 무조건 친구 의견을 따르라는 것으로 여긴다','듣고 함께 따지기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X44','kor',4,'u1',ARRAY['K4-2-u1-C2','K4-2-u1-C16']::text[],'현실에서 흔히 볼 수 있는 일을 현실에서 일어나기 어려운 일로 잘못 고른다','우리 동네에서도 볼 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X45','kor',4,'u1',ARRAY['K4-2-u1-C19']::text[],'세상과 연결할 때 이야기 속 꾸민 장치를 현실에서 그대로 쓰려 한다','현실에서 할 수 있는 도움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X46','kor',4,'u1',ARRAY['K4-2-u1-C18','K4-2-u1-C17']::text[],'작품 속 세계와 현실 세계를 비교할 때 비슷한 점과 다른 점을 늘어놓는 데서 끝내고, 글쓴이가 꾸며 낸 세계로 무엇을 전하려는지(주제)는 생각하지 않는다','다르게 꾸며 쓴 부분으로 글쓴이는 무엇을 말하고 싶었을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X47','kor',4,'u1',ARRAY['K4-2-u1-C32','K4-2-u1-C34']::text[],'의견이 문제 상황(글이 다루는 주제)과 관련 있는지 따지지 않고, 그럴듯해 보이면 알맞은 의견이라고 여긴다','이 의견대로 하면 지금 문제가 풀리나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X48','kor',4,'u1',ARRAY['K4-2-u1-C15','K4-2-u1-C6']::text[],'인물과 비슷하게 겪은 일만 이야기와 관련된 경험이라고 여기고, 인물과 다르게 말하거나 행동했던 경험은 떠올리지 않는다','나는 그때 인물과 다르게 했던 적은 없나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X49','kor',4,'u1',ARRAY['K4-2-u1-C1','K4-2-u1-C11']::text[],'작품 속 세계와 현실 세계를 비교하는 방법(경험 떠올리기·인물·사건·배경 견주기)과 글쓴이의 의견을 비교·평가하는 방법(의견·이유 따지기)을 섞어 쓴다','지금 읽는 것은 작품인가, 의견이 담긴 글인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_basic#1','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C3',1,'mc','auto','『국어』 35쪽 「생각 열기」에서 「이야기에서 현실의 모습을 있는 그대로만 다루면 어떨까요?」라고 물었어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u1-X02','K4-2-u1-X01']::text[],false,'{"seq":1,"concept":"K4-2-u1-C3","difficulty":1,"kind":"mc","stem":"『국어』 35쪽 「생각 열기」에서 「이야기에서 현실의 모습을 있는 그대로만 다루면 어떨까요?」라고 물었어요. 알맞은 생각은 무엇인가요?","options":[{"t":"이야기의 재미가 줄고, 상상을 통해 다양한 이야기를 생각하기 어려워진다","correct":true},{"t":"이야기가 거짓말을 하지 않게 되어 더 좋아진다","mis":"K4-2-u1-X02"},{"t":"현실과 다른 부분은 모두 고쳐 써야 하니 그렇게 해야 한다","mis":"K4-2-u1-X02"},{"t":"이야기 속 일을 모두 실제로 믿을 수 있게 된다","mis":"K4-2-u1-X01"}],"explanation":["심청이 연꽃에서 다시 살아 나오는 장면은 현실에서 일어날 수 없는 일이라 신기해요.","현실을 있는 그대로만 쓰면 이런 재미와 상상이 사라져요.","꾸며 쓴 부분은 거짓말이 아니라 이야기를 즐겁게 하는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_basic#2','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C2',1,'mc','auto','수아와 민균이의 대화에서 『심청전』 가운데 현실에서는 일어나기 어려운 일을 나타낸 장면으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X44']::text[],false,'{"seq":2,"concept":"K4-2-u1-C2","difficulty":1,"kind":"mc","stem":"수아와 민균이의 대화에서 『심청전』 가운데 현실에서는 일어나기 어려운 일을 나타낸 장면으로 알맞은 것은 무엇인가요?","options":[{"t":"앞을 못 보던 아버지가 다시 살아난 심청을 만나 눈을 번쩍 뜨는 장면","correct":true},{"t":"심청이 아버지를 위해 공양미를 마련하려고 애쓰는 장면","mis":"K4-2-u1-X44"},{"t":"아버지가 딸을 몹시 그리워하는 장면","mis":"K4-2-u1-X44"},{"t":"딸이 앞을 못 보는 아버지를 보살피는 장면","mis":"K4-2-u1-X44"}],"explanation":["『국어』 36쪽 1번 (1)번이에요.","죽었던 사람이 연꽃에서 살아 나오거나 단번에 눈을 뜨는 일은 현실에서 일어나기 어려워요.","가족을 아끼고 그리워하는 마음은 현실에서도 흔히 볼 수 있어요."],"asset":{"type":"speech","turns":[{"who":"수아","text":"민균아, 『심청전』 읽어 봤어? 효녀 심청에 대한 이야기야."},{"who":"민균","text":"그럼, 읽어 봤지! 심청이 아버지의 눈을 뜨게 하려고 바다에 빠져서 안타까웠어."},{"who":"수아","text":"심청이 연꽃에서 다시 살아 나오는 장면은 신기했어."},{"who":"민균","text":"나는 앞을 못 보던 아버지가 다시 살아난 심청을 만나서 눈을 번쩍 뜨는 장면이 정말 감동적이었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_basic#3','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C1',1,'mc','auto','수아와 민균이는 심청의 선택을 두고 효도에 대한 생각이 달라요. 수아의 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X02']::text[],false,'{"seq":3,"concept":"K4-2-u1-C1","difficulty":1,"kind":"mc","stem":"수아와 민균이는 심청의 선택을 두고 효도에 대한 생각이 달라요. 수아의 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"곁에서 아버지를 보살펴 드리는 것이 효도이다","correct":true},{"t":"아버지께 꼭 필요한 일을 하는 것도 효도이다","mis":"K4-2-u1-X19"},{"t":"공양미 삼백 석을 마련하는 것만 효도이다","mis":"K4-2-u1-X19"},{"t":"심청의 선택은 틀렸으니 이야기를 고쳐 써야 한다","mis":"K4-2-u1-X02"}],"explanation":["『국어』 36쪽 1번 (2)번이에요.","수아는 「곁에서 아버지를 보살펴 드리는 것이 좋지 않았을까?」라고 했어요.","같은 책을 읽고도 생각이 다를 수 있다는 것을 이 단원 뒷부분에서 더 배워요."],"asset":{"type":"speech","turns":[{"who":"수아","text":"그런데 심청의 선택을 효도라고 할 수 있을까?"},{"who":"민균","text":"공양미 삼백 석을 마련하려고 그런 거잖아. 그래야 아버지가 눈을 뜰 수 있고!"},{"who":"수아","text":"곁에서 아버지를 보살펴 드리는 것이 좋지 않았을까?"},{"who":"민균","text":"하지만 아버지께 꼭 필요한 일을 하는 것도 효도라고 생각해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_basic#4','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C2',1,'ox','auto','『국어』 37쪽에서 친구가 말한 「의좋은 형제」는 형과 사이가 좋은 내 주변 친구처럼 현실의 모습을 비슷하게 나타낸 이야기예요.',ARRAY['K4-2-u1-X06']::text[],false,'{"seq":4,"concept":"K4-2-u1-C2","difficulty":1,"kind":"ox","stem":"『국어』 37쪽에서 친구가 말한 「의좋은 형제」는 형과 사이가 좋은 내 주변 친구처럼 현실의 모습을 비슷하게 나타낸 이야기예요.","answer":"O","reason_options":[{"t":"형제가 서로 아끼는 모습은 현실에서도 볼 수 있기 때문에","correct":true},{"t":"옛이야기는 모두 현실과 동떨어지게 꾸민 것이라 견줄 수 없기 때문에","mis":"K4-2-u1-X06"}],"mis":"K4-2-u1-X06","explanation":["친구는 「내 주변에도 형과 사이가 좋은 친구가 있는데」라고 했어요.","이야기 속 인물의 모습이 현실과 비슷하면 공감하며 읽을 수 있어요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"내 주변에도 형과 사이가 좋은 친구가 있는데 그런 모습이 「의좋은 형제」에 잘 나타나 있어."},{"who":"친구 2","text":"「소가 된 게으름뱅이」는 게으른 농부가 소가 된다고 상상해서 지어낸 이야기야."},{"who":"친구 3","text":"「소금을 만드는 맷돌」은 맷돌이 바다에 빠져 바닷물이 짜졌다고 꾸며 쓴 이야기야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_basic#5','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C2',2,'match','auto','『국어』 37쪽 2번에서 친구들이 소개한 이야기와 그 이야기가 현실을 나타낸 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u1-C2","difficulty":2,"kind":"match","stem":"『국어』 37쪽 2번에서 친구들이 소개한 이야기와 그 이야기가 현실을 나타낸 방법을 알맞게 이으세요.","pairs":[{"l":"「의좋은 형제」","r":"현실의 모습을 비슷하게 나타냄"},{"l":"「소가 된 게으름뱅이」","r":"사람이 소가 된다고 상상해서 지어냄"},{"l":"「소금을 만드는 맷돌」","r":"맷돌 때문에 바닷물이 짜졌다고 꾸며 씀"}],"mis":"K4-2-u1-X07","explanation":["형제가 사이좋게 지내는 모습은 현실에도 있어요.","사람이 소로 바뀌는 일은 현실에서 일어날 수 없어요.","바닷물이 짠 까닭을 맷돌 이야기로 꾸며 썼어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"내 주변에도 형과 사이가 좋은 친구가 있는데 그런 모습이 「의좋은 형제」에 잘 나타나 있어."},{"who":"친구 2","text":"「소가 된 게으름뱅이」는 게으른 농부가 소가 된다고 상상해서 지어낸 이야기야."},{"who":"친구 3","text":"「소금을 만드는 맷돌」은 맷돌이 바다에 빠져 바닷물이 짜졌다고 꾸며 쓴 이야기야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_basic#6','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C5',2,'mc','auto','「스펀지 교실」에서 「속상한 일이 있을 때 스펀지 벽에 점프하는 장면」이 인상 깊다고 한 친구가 든 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X04','K4-2-u1-X03']::text[],false,'{"seq":6,"concept":"K4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「스펀지 교실」에서 「속상한 일이 있을 때 스펀지 벽에 점프하는 장면」이 인상 깊다고 한 친구가 든 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"스펀지 벽에 점프하면 속상한 마음이 풀릴 것 같기 때문입니다.","correct":true},{"t":"그 장면이 시의 맨 끝에 나오기 때문입니다.","mis":"K4-2-u1-X04"},{"t":"친구들도 모두 그 장면을 골랐기 때문입니다.","mis":"K4-2-u1-X03"},{"t":"스펀지 교실에는 칠판이 없기 때문입니다.","mis":"K4-2-u1-X04"}],"explanation":["『국어』 40쪽 3번 표의 첫째 줄이에요.","인상 깊은 장면은 장면과 그 까닭을 함께 말해요.","까닭은 그 장면이 내 마음에 왜 남았는지예요."],"asset":{"type":"passage","lines":["속상한 일 있을 땐","그냥 스펀지 벽에 점프만 하면 돼","[간추림] 서로의 눈빛만으로 웃음이 터지는 마법 같은 교실이다.","스펀지 책상의 둥근 모서리처럼","우리도 점점 둥글어지고 있어"],"title":"「스펀지 교실」(권기덕) 뒷부분 — 『국어』 39쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_basic#7','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C7',2,'mc','auto','「스펀지 교실」에 나타난 모습과 현실의 모습을 비교했어요. 비슷한 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X01','K4-2-u1-X07']::text[],false,'{"seq":7,"concept":"K4-2-u1-C7","difficulty":2,"kind":"mc","stem":"「스펀지 교실」에 나타난 모습과 현실의 모습을 비교했어요. 비슷한 점으로 알맞은 것은 무엇인가요?","options":[{"t":"교실에서 친구들과 함께 공부한다","correct":true},{"t":"복도를 뛰어다녀도 다칠 일이 없다","mis":"K4-2-u1-X01"},{"t":"교실 바닥이 폭신폭신하다","mis":"K4-2-u1-X01"},{"t":"현실의 교실 벽도 스펀지로 만들어 푹신하다","mis":"K4-2-u1-X07"}],"explanation":["『국어』 41쪽 4번 (2)번 표예요.","친구들과 함께 공부하는 모습은 우리 교실과 같아요.","실제 교실은 딱딱한 콘크리트나 나무로 만들어져 넘어지면 다칠 수 있어요."],"asset":{"type":"passage","lines":["혹시 스펀지 교실에서 공부해 본 적 있니?","[간추림] 스펀지 창문 밖 나무들은 통통하게 웃고, 새들은 스펀지 날개를 매단 듯 여유롭다.","[간추림] 새들 보금자리처럼 우리 교실도 폭신폭신하다.","우당탕탕 복도를 뛰어다녀도","딱딱한 바닥에 무릎 다칠 일 없는"],"title":"「스펀지 교실」(권기덕) 앞부분 — 『국어』 38쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_basic#8','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C9',2,'mc','auto','시 속 말을 근거로 「스펀지 교실」에서 말하는 이가 바라는 교실의 모습을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u1-X08']::text[],false,'{"seq":8,"concept":"K4-2-u1-C9","difficulty":2,"kind":"mc","stem":"시 속 말을 근거로 「스펀지 교실」에서 말하는 이가 바라는 교실의 모습을 바르게 쓴 것은 무엇인가요?","options":[{"t":"서로의 눈빛만 봐도 웃음이 나오는 마법 같은 교실","correct":true},{"t":"시험을 자주 보는 조용한 교실","mis":"K4-2-u1-X08"},{"t":"친구와 마주치지 않는 혼자만의 교실","mis":"K4-2-u1-X08"},{"t":"책상이 높고 모서리가 뾰족한 교실","mis":"K4-2-u1-X08"}],"explanation":["『국어』 43쪽 6번 (1)번이에요.","「서로의 눈빛만으로 웃음 터지는」 같은 시 속 말이 근거예요.","근거 없이 내 마음대로 짐작하지 않아요."],"asset":{"type":"passage","lines":["속상한 일 있을 땐","그냥 스펀지 벽에 점프만 하면 돼","[간추림] 서로의 눈빛만으로 웃음이 터지는 마법 같은 교실이다.","스펀지 책상의 둥근 모서리처럼","우리도 점점 둥글어지고 있어"],"title":"「스펀지 교실」(권기덕) 뒷부분 — 『국어』 39쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_basic#9','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C11',2,'blank','auto','『국어활동』 6쪽 1번이에요. 「작품 속 세계와 우리가 살아가는 현실 세계를 비교하며 작품을 (    ) 이해할 수 있다.」의 빈칸에 들어갈 말은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":9,"concept":"K4-2-u1-C11","difficulty":2,"kind":"blank","stem":"『국어활동』 6쪽 1번이에요. 「작품 속 세계와 우리가 살아가는 현실 세계를 비교하며 작품을 (    ) 이해할 수 있다.」의 빈칸에 들어갈 말은 무엇인가요?","options":[{"t":"깊이 있게","correct":true},{"t":"꾸며 쓴","mis":"K4-2-u1-X12"},{"t":"비슷한","mis":"K4-2-u1-X12"}],"explanation":["보기의 낱말은 「깊이 있게」, 「비슷한」, 「꾸며 쓴」이에요.","「비슷한」은 현실과 비슷한 모습, 「꾸며 쓴」은 다르게 꾸며 쓴 부분에 들어가요.","비교하며 읽으면 작품을 깊이 있게 이해할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_basic#10','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C10',3,'error','auto','「속상한 일 있을 땐 / 그냥 스펀지 벽에 점프만 하면 돼」를 친구들이 바꾸어 썼어요. 작품 속 세계와 현실 세계를 비교하지 않고 낱말만 아무렇게나 바꾼 것은 무엇인가요?',ARRAY['K4-2-u1-X09']::text[],false,'{"seq":10,"concept":"K4-2-u1-C10","difficulty":3,"kind":"error","stem":"「속상한 일 있을 땐 / 그냥 스펀지 벽에 점프만 하면 돼」를 친구들이 바꾸어 썼어요. 작품 속 세계와 현실 세계를 비교하지 않고 낱말만 아무렇게나 바꾼 것은 무엇인가요?","options":[{"t":"친구 다 — 「속상한 일 있을 땐 / 그냥 스펀지 연필에 점프만 하면 돼」","correct":true,"mis_target":"K4-2-u1-X09"},{"t":"친구 가 — 「힘든 일 있을 땐 / 스펀지 의자에 풀썩 앉기만 하면 돼」","mis":"K4-2-u1-X09"},{"t":"친구 나 — 「다툰 일 있을 땐 / 스펀지 베개를 꼭 안기만 하면 돼」","mis":"K4-2-u1-X09"}],"explanation":["『국어』 42쪽 5번 (1)번은 작품 속 세계와 현실 세계를 비교하며 바꾸어 써요.","힘든 날 앉을 의자, 다툰 날 안을 베개처럼 현실에서 바라는 모습이 담겨야 해요.","연필에 점프하는 것은 뜻이 이어지지 않으니 친구 다가 잘못 바꾸었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_challenge#1','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C4',2,'mc','auto','같은 『심청전』을 읽고 수아는 연꽃 장면이 신기했다고 하고, 민균이는 아버지가 눈을 뜨는 장면이 감동적이었다고 했어요. 이것으로 알 수 있는 것은 무엇인가요?',ARRAY['K4-2-u1-X03','K4-2-u1-X04']::text[],false,'{"seq":1,"concept":"K4-2-u1-C4","difficulty":2,"kind":"mc","stem":"같은 『심청전』을 읽고 수아는 연꽃 장면이 신기했다고 하고, 민균이는 아버지가 눈을 뜨는 장면이 감동적이었다고 했어요. 이것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"같은 책을 읽어도 사람마다 마음에 남는 장면과 반응이 다를 수 있다","correct":true},{"t":"둘 가운데 한 사람은 책을 잘못 읽었다","mis":"K4-2-u1-X03"},{"t":"더 감동적인 장면 하나를 정답으로 정해야 한다","mis":"K4-2-u1-X03"},{"t":"책에 없는 장면을 말한 사람이 있다","mis":"K4-2-u1-X04"}],"explanation":["두 사람이 고른 장면은 모두 『심청전』에 나와요.","사람마다 경험과 생각이 달라 마음에 남는 장면도 달라요.","반응이 다르면 그 까닭을 서로 물어보면 돼요."],"asset":{"type":"speech","turns":[{"who":"수아","text":"민균아, 『심청전』 읽어 봤어? 효녀 심청에 대한 이야기야."},{"who":"민균","text":"그럼, 읽어 봤지! 심청이 아버지의 눈을 뜨게 하려고 바다에 빠져서 안타까웠어."},{"who":"수아","text":"심청이 연꽃에서 다시 살아 나오는 장면은 신기했어."},{"who":"민균","text":"나는 앞을 못 보던 아버지가 다시 살아난 심청을 만나서 눈을 번쩍 뜨는 장면이 정말 감동적이었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_challenge#2','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C6',2,'mc','auto','「스펀지 교실」을 읽고 한 친구가 「친구와 눈이 마주쳤는데 어색했던 기억이 떠올라.」라고 말했어요. 이 친구는 시의 어느 장면에서 경험을 떠올렸을까요?',ARRAY['K4-2-u1-X07']::text[],false,'{"seq":2,"concept":"K4-2-u1-C6","difficulty":2,"kind":"mc","stem":"「스펀지 교실」을 읽고 한 친구가 「친구와 눈이 마주쳤는데 어색했던 기억이 떠올라.」라고 말했어요. 이 친구는 시의 어느 장면에서 경험을 떠올렸을까요?","options":[{"t":"서로의 눈빛만으로 웃음이 터지는 장면","correct":true},{"t":"나무들이 통통하게 웃는 장면","mis":"K4-2-u1-X07"},{"t":"복도를 우당탕탕 뛰어다니는 장면","mis":"K4-2-u1-X07"},{"t":"새들이 스펀지 날개를 매단 듯 나는 장면","mis":"K4-2-u1-X07"}],"explanation":["『국어』 41쪽 4번 (1)번의 예시예요.","시에서는 눈빛만 마주쳐도 웃음이 터지는데, 친구의 경험에서는 어색했어요.","같은 상황(눈이 마주침)을 견주며 경험을 떠올린 거예요."],"asset":{"type":"passage","lines":["속상한 일 있을 땐","그냥 스펀지 벽에 점프만 하면 돼","[간추림] 서로의 눈빛만으로 웃음이 터지는 마법 같은 교실이다.","스펀지 책상의 둥근 모서리처럼","우리도 점점 둥글어지고 있어"],"title":"「스펀지 교실」(권기덕) 뒷부분 — 『국어』 39쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_challenge#3','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C8',3,'mc','auto','「스펀지 교실」에는 교실·친구·복도처럼 현실과 비슷한 모습도 나와요. 이 부분에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X05','K4-2-u1-X06','K4-2-u1-X01']::text[],false,'{"seq":3,"concept":"K4-2-u1-C8","difficulty":3,"kind":"mc","stem":"「스펀지 교실」에는 교실·친구·복도처럼 현실과 비슷한 모습도 나와요. 이 부분에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"현실과 닮은 부분도 글쓴이가 바라는 교실을 그리려고 골라 쓴 것이다","correct":true},{"t":"스펀지로 된 것만 꾸민 것이고 나머지는 실제로 있었던 일이다","mis":"K4-2-u1-X05"},{"t":"모두 꾸민 것이니 우리 교실과 견주어 볼 필요가 없다","mis":"K4-2-u1-X06"},{"t":"현실과 닮은 부분이 있으니 시 전체가 실제 이야기이다","mis":"K4-2-u1-X01"}],"explanation":["작품 속 세계는 현실과 닮았지만 글쓴이가 상상하여 창조한 세계예요.","스펀지만 꾸민 것이 아니라 시 전체가 글쓴이가 만든 세계예요.","그래도 현실과 견주어 보면 시를 더 깊이 이해할 수 있어요."],"asset":{"type":"passage","lines":["혹시 스펀지 교실에서 공부해 본 적 있니?","[간추림] 스펀지 창문 밖 나무들은 통통하게 웃고, 새들은 스펀지 날개를 매단 듯 여유롭다.","[간추림] 새들 보금자리처럼 우리 교실도 폭신폭신하다.","우당탕탕 복도를 뛰어다녀도","딱딱한 바닥에 무릎 다칠 일 없는"],"title":"「스펀지 교실」(권기덕) 앞부분 — 『국어』 38쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_challenge#4','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C11',3,'mc','auto','『국어활동』 7쪽 3번에서 작품 속 세계와 현실 세계를 비교하며 읽으면 좋은 점을 색칠해요. 색칠하면 안 되는 것은 무엇인가요?',ARRAY['K4-2-u1-X06','K4-2-u1-X10']::text[],false,'{"seq":4,"concept":"K4-2-u1-C11","difficulty":3,"kind":"mc","stem":"『국어활동』 7쪽 3번에서 작품 속 세계와 현실 세계를 비교하며 읽으면 좋은 점을 색칠해요. 색칠하면 안 되는 것은 무엇인가요?","options":[{"t":"중심 문장과 뒷받침 문장을 찾을 수 있다","correct":true},{"t":"현실의 모습을 되돌아볼 수 있다","mis":"K4-2-u1-X06"},{"t":"현실과 다른 세계의 모습을 상상해 볼 수 있다","mis":"K4-2-u1-X06"},{"t":"현실의 모습을 새로운 눈으로 폭넓게 이해할 수 있다","mis":"K4-2-u1-X10"}],"explanation":["나머지 셋은 『국어』 43쪽 7번에서 친구들이 말한 좋은 점이에요.","중심 문장과 뒷받침 문장 찾기는 이 활동과 상관없어요.","좋은 점을 모두 색칠하면 「비교해요」라는 낱말이 완성돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_challenge#5','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C7',3,'mc','auto','『국어활동』 6쪽 2번이에요. 작품 속 세계와 현실 세계를 비교하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X49','K4-2-u1-X10','K4-2-u1-X02']::text[],false,'{"seq":5,"concept":"K4-2-u1-C7","difficulty":3,"kind":"mc","stem":"『국어활동』 6쪽 2번이에요. 작품 속 세계와 현실 세계를 비교하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"작품 속 인물, 일어난 일, 배경 등을 현실 세계와 비교한다","correct":true},{"t":"글쓴이의 의견과 이유가 알맞은지 살펴본다","mis":"K4-2-u1-X49"},{"t":"작품에서 현실과 다른 곳을 찾아 틀렸다고 고친다","mis":"K4-2-u1-X10"},{"t":"현실과 다른 부분을 거짓말이라고 표시한다","mis":"K4-2-u1-X02"}],"explanation":["작품을 읽고 내 경험을 떠올려, 경험한 일과 작품에서 일어난 일을 비교해요.","인물·일어난 일·배경을 현실과 견주어요.","의견과 이유 살피기는 의견이 담긴 글을 읽을 때 쓰는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_challenge#6','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C9',3,'mc','auto','「스펀지 교실」과 현실의 교실을 견주어 볼 때, 말하는 이가 현실의 학생들에게 바라는 모습으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X45','K4-2-u1-X16','K4-2-u1-X08']::text[],false,'{"seq":6,"concept":"K4-2-u1-C9","difficulty":3,"kind":"mc","stem":"「스펀지 교실」과 현실의 교실을 견주어 볼 때, 말하는 이가 현실의 학생들에게 바라는 모습으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"속상한 일이 있어도 마음을 풀고 좋은 기분으로 생활하는 모습","correct":true},{"t":"교실 벽을 모두 스펀지로 바꾸어 다는 모습","mis":"K4-2-u1-X45"},{"t":"복도에서 마음껏 부딪혀도 괜찮다고 여기는 모습","mis":"K4-2-u1-X16"},{"t":"말없이 혼자 공부하는 모습","mis":"K4-2-u1-X08"}],"explanation":["현실의 학생들은 속상한 일이 있어도 말하기 어려울 때가 있어요.","시 속 학생들은 스펀지 벽에 점프하며 마음을 풀어요.","말하는 이는 현실의 학생들도 좋은 기분으로 지내기를 바라요."],"asset":{"type":"passage","lines":["속상한 일 있을 땐","그냥 스펀지 벽에 점프만 하면 돼","[간추림] 서로의 눈빛만으로 웃음이 터지는 마법 같은 교실이다.","스펀지 책상의 둥근 모서리처럼","우리도 점점 둥글어지고 있어"],"title":"「스펀지 교실」(권기덕) 뒷부분 — 『국어』 39쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_challenge#7','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C2',3,'ox','auto','동화뿐만 아니라 시, 극본, 만화, 드라마, 영화에서도 현실의 모습을 비슷하게 또는 다르게 나타낼 수 있어요.',ARRAY['K4-2-u1-X06']::text[],false,'{"seq":7,"concept":"K4-2-u1-C2","difficulty":3,"kind":"ox","stem":"동화뿐만 아니라 시, 극본, 만화, 드라마, 영화에서도 현실의 모습을 비슷하게 또는 다르게 나타낼 수 있어요.","answer":"O","reason_options":[{"t":"어떤 갈래의 작품이든 현실을 바탕으로 상상해 만들기 때문에","correct":true},{"t":"현실과 견주어 볼 수 있는 작품은 동화뿐이기 때문에","mis":"K4-2-u1-X06"}],"mis":"K4-2-u1-X06","explanation":["「스펀지 교실」은 시인데도 현실의 교실과 견주어 볼 수 있었어요.","만화나 영화에도 현실과 비슷한 장면과 다르게 꾸민 장면이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_challenge#8','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C10',4,'essay','teacher','「스펀지 책상의 둥근 모서리처럼 / 우리도 점점 둥글어지고 있어」를 내가 바라는 교실의 모습으로 바꾸어 쓰고, 그렇게 바꾼 까닭을 우리 교실(현실)의 모습과 견주어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u1-C10","difficulty":4,"kind":"essay","stem":"「스펀지 책상의 둥근 모서리처럼 / 우리도 점점 둥글어지고 있어」를 내가 바라는 교실의 모습으로 바꾸어 쓰고, 그렇게 바꾼 까닭을 우리 교실(현실)의 모습과 견주어 쓰세요.","answer_guide":{"answer":"예: 스펀지 칠판의 넓은 면처럼 / 우리 마음도 점점 넓어지고 있어. 까닭 — 우리 교실 칠판은 딱딱하지만 넓어서 모두의 생각을 적을 수 있다. 친구의 말을 넓게 받아 주는 마음이 우리 반에 생기면 좋겠다고 생각해서 이렇게 바꾸었다.","scoring_points":["원래 시의 짜임(「~처럼 / 우리 ~도 점점 ~고 있어」)을 살려 바꾸었는가","현실의 교실 모습과 견주어 까닭을 썼는가","내가 바라는 모습이 드러나는가"]},"explanation":["『국어』 42쪽 5번 (1)번의 둘째 예시예요.","현실과 비교한 것을 바탕으로 상상력을 발휘해 바꾸어 써요.","바꾼 뒤에는 생각이나 느낌을 친구들과 나누어요."],"asset":{"type":"passage","lines":["속상한 일 있을 땐","그냥 스펀지 벽에 점프만 하면 돼","[간추림] 서로의 눈빛만으로 웃음이 터지는 마법 같은 교실이다.","스펀지 책상의 둥근 모서리처럼","우리도 점점 둥글어지고 있어"],"title":"「스펀지 교실」(권기덕) 뒷부분 — 『국어』 39쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_challenge#9','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C7',4,'essay','teacher','「스펀지 교실」에 나타난 모습과 현실의 모습을 비교해 다른 점을 두 가지 쓰고, 그 가운데 하나와 이어지는 내 경험을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C7","difficulty":4,"kind":"essay","stem":"「스펀지 교실」에 나타난 모습과 현실의 모습을 비교해 다른 점을 두 가지 쓰고, 그 가운데 하나와 이어지는 내 경험을 쓰세요.","answer_guide":{"answer":"예: 다른 점 ① 시에서는 복도를 뛰어다녀도 다칠 일이 없지만, 현실에서는 넘어져 다칠 수 있다. ② 시에서는 속상할 때 스펀지 벽에 점프하지만, 현실의 벽은 딱딱해서 점프할 수 없다. 경험 — 2학년 때 복도에서 뛰다가 넘어져 무릎을 다친 적이 있다. 그때 바닥이 폭신했으면 좋겠다고 생각했다.","scoring_points":["시에 나타난 모습과 현실의 모습을 짝지어 다른 점 두 가지를 썼는가","같은 대상끼리 견주었는가","다른 점과 이어지는 내 경험을 썼는가"]},"explanation":["『국어』 41쪽 4번 (1)·(2)번을 이어 한 활동이에요.","자신의 경험을 바탕으로 사실인 부분과 꾸며 쓴 부분을 구별해요.","같은 대상(복도·벽)끼리 나란히 놓고 견주어요."],"asset":{"type":"passage","lines":["[표] 「스펀지 교실」에 나타난 모습과 현실의 모습","비슷한 점 — 교실에서 친구들과 함께 공부한다.","다른 점 ① 시 — 복도를 뛰어다녀도 다칠 일이 없다.","다른 점 ① 현실 — 복도를 뛰어다니다가 넘어져 다칠 수도 있다.","다른 점 ② 시 — 속상한 일이 있을 땐 스펀지 벽에 점프할 수 있다.","다른 점 ② 현실 — 딱딱한 벽에는 점프할 수 없다."],"title":"4번 (2) 예시 — 『국어』 41쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L02_challenge#10','kor',4,2,'u1','L02','tb_g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C11',4,'essay','teacher','작품 속 세계와 현실 세계를 비교하면 좋은 점 가운데 하나를 골라 쓰고, 「스펀지 교실」을 읽은 경험을 예로 들어 그 좋은 점을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u1-C11","difficulty":4,"kind":"essay","stem":"작품 속 세계와 현실 세계를 비교하면 좋은 점 가운데 하나를 골라 쓰고, 「스펀지 교실」을 읽은 경험을 예로 들어 그 좋은 점을 설명하세요.","answer_guide":{"answer":"예: 현실의 모습을 되돌아볼 수 있다. 「스펀지 교실」을 읽고 우리 교실과 견주어 보니, 우리 반 친구들이 속상한 일이 있어도 말하지 못하고 지낸 적이 많았다는 것을 깨달았다. 그래서 서로의 기분을 더 살펴 주는 교실을 만들고 싶어졌다.","scoring_points":["좋은 점 하나를 바르게 썼는가","「스펀지 교실」과 현실을 견준 내용을 예로 들었는가","좋은 점과 예가 서로 이어지는가"]},"explanation":["『국어』 43쪽 7번 활동이에요.","좋은 점에는 되돌아보기·상상하기·새로운 눈으로 보기·글쓴이가 창조한 세계임을 알기가 있어요.","내가 읽은 경험으로 설명하면 더 또렷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_basic#1','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C12',1,'blank','auto','『국어』 58쪽 「내용 알기」 (1)번이에요. 부엌 친구들이 최고의 고양이빵을 만들려는 까닭은 「가게의 (    )이 달려 있기 때문」이에요. 빈칸에 들어갈 말은 무엇인가요?',ARRAY['K4-2-u1-X11']::text[],false,'{"seq":1,"concept":"K4-2-u1-C12","difficulty":1,"kind":"blank","stem":"『국어』 58쪽 「내용 알기」 (1)번이에요. 부엌 친구들이 최고의 고양이빵을 만들려는 까닭은 「가게의 (    )이 달려 있기 때문」이에요. 빈칸에 들어갈 말은 무엇인가요?","options":[{"t":"운명","correct":true},{"t":"간판","mis":"K4-2-u1-X11"},{"t":"빵값","mis":"K4-2-u1-X11"},{"t":"이름","mis":"K4-2-u1-X11"}],"explanation":["팥냥이는 「이 가게의 운명이 너희 손에 달려 있으니까.」라고 했어요.","다정 죽집은 문을 닫을 위기에 놓여 있었어요.","부엌 친구들은 가게를 지키려고 최고의 고양이빵을 만들었어요."],"asset":{"type":"passage","lines":["[간추림] 할머니와 할아버지는 오랫동안 팥죽 가게 ‘다정 죽집’을 꾸려 왔다.","[간추림] 할아버지가 돌아가신 뒤, 죽집은 문을 닫을 위기에 놓였다.","[간추림] 고양이 팥냥이가 꾹꾹이를 해 주자 부엌 친구들이 말하고 움직이게 되었다.","“아무튼 오늘 최고의 고양이빵을 만들어야 해.","이 가게의 운명이 너희 손에 달려 있으니까.”","[간추림] 가마솥인 ‘나’는 팥을 끓이고, 홍두깨·인두·주걱·사발도 저마다 일을 맡았다.","[간추림] 부엌 친구들은 고양이빵 다섯 개를 만들어 상자에 담아 몰래 숨겨 두었다."],"title":"「언제나 다정 죽집」(우신영 글) 앞부분 — 『국어』 44~47쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_basic#2','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C13',1,'match','auto','『국어』 58쪽 「낱말 알기」예요. 밑줄 그은 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K4-2-u1-C13","difficulty":1,"kind":"match","stem":"『국어』 58쪽 「낱말 알기」예요. 밑줄 그은 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"막연했던 추측","r":"뚜렷하지 못하고 어렴풋하다"},{"l":"가게 인수하실 분","r":"물건이나 권리를 건네받다"},{"l":"모양새가 되어 민망합니다","r":"얼굴을 들고 대하기가 부끄럽다"},{"l":"분위기를 감지한","r":"느껴서 알다"}],"mis":"K4-2-u1-X12","explanation":["선으로 잇기 전에 문장과 낱말의 뜻을 보고 의미를 짐작해요.","키다리 아저씨는 가게를 인수할 사람이라 할머니를 밀어내는 것 같아 민망했어요.","앞뒤 문맥을 보면 낱말의 뜻을 짐작할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_basic#3','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C12',1,'mc','auto','『국어』 59쪽 (1)번에서 「언제나 다정 죽집」에서 일어난 일을 차례대로 정리해요. 맨 처음 일어난 일은 무엇인가요?',ARRAY['K4-2-u1-X11']::text[],false,'{"seq":3,"concept":"K4-2-u1-C12","difficulty":1,"kind":"mc","stem":"『국어』 59쪽 (1)번에서 「언제나 다정 죽집」에서 일어난 일을 차례대로 정리해요. 맨 처음 일어난 일은 무엇인가요?","options":[{"t":"부엌 친구들이 서로 도와 고양이빵 다섯 개를 만들었다","correct":true},{"t":"할머니가 과일 가게 아저씨에게 고양이빵을 건넸다","mis":"K4-2-u1-X11"},{"t":"베레모 아저씨와 키다리 아저씨가 팥죽 맛에 감동했다","mis":"K4-2-u1-X11"},{"t":"할머니가 동짓날 팥죽을 정성스럽게 끓였다","mis":"K4-2-u1-X11"}],"explanation":["새벽에 부엌 친구들이 먼저 고양이빵을 만들어 숨겨 두었어요.","아침에 할머니가 팥죽을 끓였어요.","그다음 과일 가게 아저씨, 마지막에 두 아저씨가 왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_basic#4','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C17',1,'ox','auto','「언제나 다정 죽집」에서 고양이가 앞발로 꾹꾹 누르는 꾹꾹이를 하는 것은 현실에서도 볼 수 있는 모습이에요.',ARRAY['K4-2-u1-X44']::text[],false,'{"seq":4,"concept":"K4-2-u1-C17","difficulty":1,"kind":"ox","stem":"「언제나 다정 죽집」에서 고양이가 앞발로 꾹꾹 누르는 꾹꾹이를 하는 것은 현실에서도 볼 수 있는 모습이에요.","answer":"O","reason_options":[{"t":"실제 고양이도 앞발로 꾹꾹이를 하기 때문에","correct":true},{"t":"말하는 고양이가 나오는 이야기의 일은 모두 현실과 다르기 때문에","mis":"K4-2-u1-X44"}],"mis":"K4-2-u1-X44","explanation":["『국어』 61쪽 (1)번 예시의 비슷한 점이에요.","고양이가 꾹꾹이를 하는 것은 현실과 같아요.","다만 꾹꾹이로 부엌 도구가 살아나는 것은 꾸며 쓴 부분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_basic#5','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C14',2,'mc','auto','할머니가 「하지만 몸을 추스르자고 먹는 죽에다가 차마 그런 것들을 들이부을 수야 없지.」라고 한 말에서 짐작할 수 있는 할머니의 성격은 무엇인가요?',ARRAY['K4-2-u1-X13']::text[],false,'{"seq":5,"concept":"K4-2-u1-C14","difficulty":2,"kind":"mc","stem":"할머니가 「하지만 몸을 추스르자고 먹는 죽에다가 차마 그런 것들을 들이부을 수야 없지.」라고 한 말에서 짐작할 수 있는 할머니의 성격은 무엇인가요?","options":[{"t":"정직하고 성실하다","correct":true},{"t":"욕심이 많고 게으르다","mis":"K4-2-u1-X13"},{"t":"겁이 많고 소심하다","mis":"K4-2-u1-X13"},{"t":"장난스럽고 엉뚱하다","mis":"K4-2-u1-X13"}],"explanation":["『국어』 59쪽 (2)번 표의 첫째 줄이에요.","손님 입맛보다 몸을 돌보는 죽의 본래 뜻을 지키려 했어요.","할아버지 때부터 해 오던 방식을 바꾸지 않은 성실함도 보여요."],"asset":{"type":"passage","lines":["[간추림] 마지막 장삿날 아침, 할머니는 동지 팥죽을 준비했다.","[간추림] 첫 물을 버리고, 앙금을 가라앉힌 맑은 윗물만 떠서 쌀을 익혔다.","[간추림] 설탕도 소금도 넣지 않은 소박한 팥죽이었다.","“하지만 몸을 추스르자고 먹는 죽에다가","차마 그런 것들을 들이부을 수야 없지.”"],"title":"「언제나 다정 죽집」 가운데 ① — 『국어』 47~50쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_basic#6','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C12',2,'sa','auto','『국어』 58쪽 (2)번이에요. 키다리 아저씨는 죽집 이름이 팥죽 맛의 비밀이라고 했어요. 맛의 비밀이 된 할머니의 마음을 죽집 이름에서 찾아 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u1-C12","difficulty":2,"kind":"sa","stem":"『국어』 58쪽 (2)번이에요. 키다리 아저씨는 죽집 이름이 팥죽 맛의 비밀이라고 했어요. 맛의 비밀이 된 할머니의 마음을 죽집 이름에서 찾아 두 글자로 쓰세요.","answer":["다정","다정함"],"explanation":["죽집 이름은 ‘다정 죽집’이에요.","알아주지 않아도 누군가의 몸과 마음을 돌보려는 할머니의 다정함이 비밀이었어요.","설탕을 넣거나 꾸민 장치를 쓴 것이 아니에요."],"asset":{"type":"passage","lines":["[간추림] 건물 주인 베레모 아저씨가 가게를 넘겨받을 키다리 아저씨와 함께 왔다.","[간추림] 할머니는 넉넉한 대접에 팥죽을 그득 담아 두 사람에게 내었다.","“비결이랄 게 있나요. 그저 팥죽을 팥죽답게 끓였을 뿐이지요.”","[간추림] 좋은 재료를 고집하고 얕은수는 쓰지 않았으며, 늘 넉넉하게 나눴다고 했다.","“이 죽집 이름이 맛의 비밀이었어요.”"],"title":"「언제나 다정 죽집」 뒷부분 — 『국어』 54~57쪽"},"mis":"K4-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_basic#7','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C15',2,'mc','auto','『국어』 60쪽 「자신과 관련짓기」처럼 「언제나 다정 죽집」을 읽고 떠올린 경험으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X14']::text[],false,'{"seq":7,"concept":"K4-2-u1-C15","difficulty":2,"kind":"mc","stem":"『국어』 60쪽 「자신과 관련짓기」처럼 「언제나 다정 죽집」을 읽고 떠올린 경험으로 알맞은 것은 무엇인가요?","options":[{"t":"다른 사람이 보지 않아도 열심히 청소하는 친구를 보고 감동한 일","correct":true},{"t":"고양이 그림을 그려 본 일","mis":"K4-2-u1-X14"},{"t":"죽집 간판을 본 일","mis":"K4-2-u1-X14"},{"t":"팥죽을 싫어하는 일","mis":"K4-2-u1-X14"}],"explanation":["고양이·죽집처럼 겉에 나온 낱말이 같다고 이어지는 경험이 아니에요.","알아주지 않아도 정성을 다하는 할머니의 모습과 이어지는 경험을 떠올려요.","비슷한 경험이 없으면 책이나 동영상에서 본 일도 떠올릴 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_basic#8','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C17',2,'mc','auto','『국어』 61쪽 (1)번이에요. 이야기에 나타난 모습과 현실의 모습의 다른 점을 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u1-X44','K4-2-u1-X07']::text[],false,'{"seq":8,"concept":"K4-2-u1-C17","difficulty":2,"kind":"mc","stem":"『국어』 61쪽 (1)번이에요. 이야기에 나타난 모습과 현실의 모습의 다른 점을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"이야기 — 고양이가 사람처럼 말을 한다 / 현실 — 고양이는 고양이 울음소리를 낸다","correct":true},{"t":"이야기 — 할머니가 팥죽을 끓인다 / 현실 — 할머니는 팥죽을 끓일 수 없다","mis":"K4-2-u1-X44"},{"t":"이야기 — 부엌 도구들이 스스로 움직인다 / 현실 — 고양이는 꾹꾹이를 한다","mis":"K4-2-u1-X07"},{"t":"이야기 — 고양이가 꾹꾹이를 한다 / 현실 — 고양이는 꾹꾹이를 하지 않는다","mis":"K4-2-u1-X07"}],"explanation":["다른 점은 같은 대상끼리 견주어요.","고양이가 말을 하는 것은 현실과 달라요.","할머니가 팥죽을 끓이는 일, 고양이의 꾹꾹이는 현실과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_basic#9','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C19',2,'mc','auto','『국어』 61쪽 「세상과 연결하기」에서 도움이 필요한 사람을 도와줄 방법을 상상했어요. 『국어』의 예시로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X45','K4-2-u1-X16']::text[],false,'{"seq":9,"concept":"K4-2-u1-C19","difficulty":2,"kind":"mc","stem":"『국어』 61쪽 「세상과 연결하기」에서 도움이 필요한 사람을 도와줄 방법을 상상했어요. 『국어』의 예시로 알맞은 것은 무엇인가요?","options":[{"t":"로봇 의자를 만들어서 바르게 앉는 것을 힘들어하는 모둠 친구의 자세를 잡아 준다","correct":true},{"t":"팥냥이처럼 꾹꾹이를 해서 물건이 저절로 움직이게 한다","mis":"K4-2-u1-X45"},{"t":"할머니처럼 죽집을 차려 돈을 많이 번다","mis":"K4-2-u1-X16"},{"t":"도움이 필요한 사람보다 내가 받고 싶은 선물을 떠올린다","mis":"K4-2-u1-X45"}],"explanation":["또 다른 예시는 투명 인간이 되어 달리기를 어려워하는 동생의 손을 잡고 달리는 것이에요.","작품 속 세계, 현실 세계, 자기 세계를 이어 생각해요.","이야기 속 꾸민 장치를 현실에서 그대로 쓰려는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_basic#10','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C16',3,'mc','auto','할머니는 아침마다 가게에 갓 구운 빵이 놓여 있는 것을 ‘빵 요정의 마법’이라고 했어요. 이 일에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X05','K4-2-u1-X01']::text[],false,'{"seq":10,"concept":"K4-2-u1-C16","difficulty":3,"kind":"mc","stem":"할머니는 아침마다 가게에 갓 구운 빵이 놓여 있는 것을 ‘빵 요정의 마법’이라고 했어요. 이 일에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"누가 빵을 갖다 놓은 평범한 일처럼 보이지만, 부엌 도구들이 몰래 만든 빵이어서 현실과 다르다","correct":true},{"t":"빵이 놓여 있는 것은 흔한 일이니 현실과 똑같다","mis":"K4-2-u1-X05"},{"t":"말하는 고양이만 꾸민 것이고 빵 이야기는 실제로 있었던 일이다","mis":"K4-2-u1-X05"},{"t":"빵 요정이 정말로 있다는 것을 알려 주는 장면이다","mis":"K4-2-u1-X01"}],"explanation":["눈에 띄게 말하는 고양이만 꾸민 부분이 아니에요.","평범해 보이는 빵 이야기도 부엌 도구들이 만든 것이니 현실과 달라요.","현실의 규칙과 견주어 보면 꾸민 부분이 보여요."],"asset":{"type":"passage","lines":["[간추림] 할머니는 이 주째 아침마다 놓여 있던 빵을 ‘빵 요정의 마법’이라고 여겼다.","[간추림] 과일 가게 아저씨가 와서 며칠 전 받은 고양이 발 모양 빵을 구할 수 있는지 물었다.","[간추림] 입덧으로 밥을 못 먹던 아내가 그 빵만은 먹고 또 찾는다고 했다.","[간추림] 눈치 빠른 인두가 고양이빵 상자를 할머니 눈에 띄는 탁자에 몰래 놓았다.","[간추림] 할머니는 팥죽값만 받고 팥죽 두 그릇에 고양이빵 두 개를 함께 건넸다.","“식구가 셋인데 하나 가지곤 안 되죠."],"title":"「언제나 다정 죽집」 가운데 ② — 『국어』 51~53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_challenge#1','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C12',2,'mc','auto','『국어』 58쪽 (3)번이에요. 팥죽을 먹으며 나누는 베레모 아저씨와 키다리 아저씨의 대화를 듣고 할머니는 어떤 기분이 들었을까요?',ARRAY['K4-2-u1-X11']::text[],false,'{"seq":1,"concept":"K4-2-u1-C12","difficulty":2,"kind":"mc","stem":"『국어』 58쪽 (3)번이에요. 팥죽을 먹으며 나누는 베레모 아저씨와 키다리 아저씨의 대화를 듣고 할머니는 어떤 기분이 들었을까요?","options":[{"t":"자신의 마음을 알아주어서 고맙고 감동을 받았을 것이다","correct":true},{"t":"가게를 빼앗겨 화가 났을 것이다","mis":"K4-2-u1-X11"},{"t":"팥죽이 맛없다는 말에 속상했을 것이다","mis":"K4-2-u1-X11"},{"t":"비결을 들켜서 걱정되었을 것이다","mis":"K4-2-u1-X11"}],"explanation":["키다리 아저씨는 「이런 팥죽은 처음 먹어 봅니다.」라며 감탄했어요.","할머니의 다정함이 맛의 비밀이라는 것을 알아주었어요.","그래서 고맙고 감동을 받았을 거예요."],"asset":{"type":"passage","lines":["[간추림] 건물 주인 베레모 아저씨가 가게를 넘겨받을 키다리 아저씨와 함께 왔다.","[간추림] 할머니는 넉넉한 대접에 팥죽을 그득 담아 두 사람에게 내었다.","“비결이랄 게 있나요. 그저 팥죽을 팥죽답게 끓였을 뿐이지요.”","[간추림] 좋은 재료를 고집하고 얕은수는 쓰지 않았으며, 늘 넉넉하게 나눴다고 했다.","“이 죽집 이름이 맛의 비밀이었어요.”"],"title":"「언제나 다정 죽집」 뒷부분 — 『국어』 54~57쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_challenge#2','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C14',2,'mc','auto','부엌 친구들이 「맞아. 결과가 어떻게 될지 모르지만, 일단 우리가 할 수 있는 한 최선을 다해 보자.」라고 한 말에서 짐작할 수 있는 성격은 무엇인가요?',ARRAY['K4-2-u1-X13']::text[],false,'{"seq":2,"concept":"K4-2-u1-C14","difficulty":2,"kind":"mc","stem":"부엌 친구들이 「맞아. 결과가 어떻게 될지 모르지만, 일단 우리가 할 수 있는 한 최선을 다해 보자.」라고 한 말에서 짐작할 수 있는 성격은 무엇인가요?","options":[{"t":"긍정적이고 밝다","correct":true},{"t":"쉽게 포기하고 겁이 많다","mis":"K4-2-u1-X13"},{"t":"남의 탓을 잘한다","mis":"K4-2-u1-X13"},{"t":"게으르고 느긋하다","mis":"K4-2-u1-X13"}],"explanation":["『국어』 59쪽 (2)번 표의 마지막 줄이에요.","결과를 몰라도 최선을 다하자고 했어요.","인물의 말을 근거로 성격을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_challenge#3','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C15',3,'ox','auto','「언제나 다정 죽집」과 관련된 경험은 할머니처럼 남을 도왔던 경험이어야 하고, 할머니와 다르게 행동했던 경험은 떠올릴 필요가 없어요.',ARRAY['K4-2-u1-X48']::text[],false,'{"seq":3,"concept":"K4-2-u1-C15","difficulty":3,"kind":"ox","stem":"「언제나 다정 죽집」과 관련된 경험은 할머니처럼 남을 도왔던 경험이어야 하고, 할머니와 다르게 행동했던 경험은 떠올릴 필요가 없어요.","answer":"X","reason_options":[{"t":"등장인물과 다르게 말하거나 행동했던 경험도 이야기를 나와 관련짓게 해 주기 때문에","correct":true},{"t":"인물과 똑같이 행동한 경험만 이야기와 관련 있기 때문에","mis":"K4-2-u1-X48"}],"mis":"K4-2-u1-X48","explanation":["비슷한 경험뿐만 아니라 주요 상황에서 인물과 다르게 했던 경험도 떠올려요.","예를 들어 귀찮아서 대충 했던 일을 떠올리면 할머니의 정성이 더 크게 느껴져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_challenge#4','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C14',3,'mc','auto','할머니가 과일 가게 아저씨에게 팥죽값만 받고 고양이빵 두 개를 함께 건넨 일에서 짐작할 수 있는 성격과 그 근거를 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u1-X13']::text[],false,'{"seq":4,"concept":"K4-2-u1-C14","difficulty":3,"kind":"mc","stem":"할머니가 과일 가게 아저씨에게 팥죽값만 받고 고양이빵 두 개를 함께 건넨 일에서 짐작할 수 있는 성격과 그 근거를 바르게 말한 것은 무엇인가요?","options":[{"t":"다정하고 자상하다 — 「식구가 셋인데 하나 가지곤 안 되죠.」라며 뱃속 아기 몫까지 챙겼다","correct":true},{"t":"인색하다 — 빵값을 받지 않았다","mis":"K4-2-u1-X13"},{"t":"다정하다 — 전날 밤 앞치마를 인두로 다려 두었다","mis":"K4-2-u1-X13"},{"t":"욕심이 많다 — 팥죽값은 받았다","mis":"K4-2-u1-X13"}],"explanation":["성격은 그 장면의 말이나 행동을 근거로 짐작해요.","할머니는 자기 빵이 아니라며 빵값을 받지 않고, 아기 몫까지 넉넉히 주었어요.","앞치마를 다린 일은 이 성격의 근거가 되기 어려워요."],"asset":{"type":"passage","lines":["[간추림] 할머니는 이 주째 아침마다 놓여 있던 빵을 ‘빵 요정의 마법’이라고 여겼다.","[간추림] 과일 가게 아저씨가 와서 며칠 전 받은 고양이 발 모양 빵을 구할 수 있는지 물었다.","[간추림] 입덧으로 밥을 못 먹던 아내가 그 빵만은 먹고 또 찾는다고 했다.","[간추림] 눈치 빠른 인두가 고양이빵 상자를 할머니 눈에 띄는 탁자에 몰래 놓았다.","[간추림] 할머니는 팥죽값만 받고 팥죽 두 그릇에 고양이빵 두 개를 함께 건넸다.","“식구가 셋인데 하나 가지곤 안 되죠."],"title":"「언제나 다정 죽집」 가운데 ② — 『국어』 51~53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_challenge#5','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C18',3,'mc','auto','『국어』 61쪽 (2)번이에요. 글쓴이가 「언제나 다정 죽집」을 통해 전하고자 하는 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X16','K4-2-u1-X17','K4-2-u1-X46']::text[],false,'{"seq":5,"concept":"K4-2-u1-C18","difficulty":3,"kind":"mc","stem":"『국어』 61쪽 (2)번이에요. 글쓴이가 「언제나 다정 죽집」을 통해 전하고자 하는 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"결과와 상관없이 최선을 다하는 마음과 사람을 진심으로 대하는 마음이 중요하다","correct":true},{"t":"고양이가 꾹꾹이를 하면 부엌 도구가 살아 움직인다","mis":"K4-2-u1-X16"},{"t":"오래된 가게는 빨리 문을 닫는 것이 좋다","mis":"K4-2-u1-X17"},{"t":"이야기에서는 고양이가 말을 하고 현실에서는 울음소리를 낸다","mis":"K4-2-u1-X46"}],"explanation":["주제는 이야기 속 근거를 대어 찾아요.","할머니와 부엌 친구들은 마지막 날까지 정성과 최선을 다했어요.","현실과의 다른 점을 말하는 데서 멈추지 않고 그 까닭을 생각해야 주제가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_challenge#6','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C18',3,'ox','auto','「언제나 다정 죽집」의 주제를 친구는 「성실하게 살면 복을 받는다」로, 나는 「서로 힘을 합치면 어려운 일도 잘해 낼 수 있다」로 말했다면 둘 가운데 하나는 틀린 거예요.',ARRAY['K4-2-u1-X17']::text[],false,'{"seq":6,"concept":"K4-2-u1-C18","difficulty":3,"kind":"ox","stem":"「언제나 다정 죽집」의 주제를 친구는 「성실하게 살면 복을 받는다」로, 나는 「서로 힘을 합치면 어려운 일도 잘해 낼 수 있다」로 말했다면 둘 가운데 하나는 틀린 거예요.","answer":"X","reason_options":[{"t":"이야기 속 근거를 대면 주제를 여러 갈래로 받아들일 수 있기 때문에","correct":true},{"t":"글쓴이가 전하려는 생각은 하나뿐이기 때문에","mis":"K4-2-u1-X17"}],"mis":"K4-2-u1-X17","explanation":["두 친구의 생각은 모두 『국어』 61쪽의 예시에 있어요.","할머니의 성실함, 부엌 친구들의 협동이 각각 근거가 돼요.","근거가 서면 주제는 여러 갈래일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_challenge#7','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C17',3,'mc','auto','「언제나 다정 죽집」에서 현실과 닮은 부분과 꾸며 쓴 부분이 하는 일을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u1-X15','K4-2-u1-X02']::text[],false,'{"seq":7,"concept":"K4-2-u1-C17","difficulty":3,"kind":"mc","stem":"「언제나 다정 죽집」에서 현실과 닮은 부분과 꾸며 쓴 부분이 하는 일을 바르게 말한 것은 무엇인가요?","options":[{"t":"할머니가 정성껏 팥죽을 끓이는 모습은 공감을 주고, 말하는 부엌 친구들은 재미와 감동을 준다","correct":true},{"t":"말하는 부엌 친구들은 공감을 주고, 할머니가 팥죽을 끓이는 모습은 재미만 준다","mis":"K4-2-u1-X15"},{"t":"꾸며 쓴 부분은 거짓말이라 이야기를 망친다","mis":"K4-2-u1-X02"},{"t":"현실과 닮은 부분은 아무 일도 하지 않는다","mis":"K4-2-u1-X15"}],"explanation":["작품 속 세계가 현실을 비슷하게 반영하면 읽는 사람이 공감해요.","현실을 허구적으로 꾸며 쓰면 재미나 감동, 깨달음을 줘요.","그래서 글쓴이는 두 가지를 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_challenge#8','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C17',4,'essay','teacher','「언제나 다정 죽집」에 나타난 모습과 현실의 모습을 비교해 비슷한 점과 다른 점을 하나씩 쓰고, 글쓴이가 현실과 다르게 꾸며 쓴 까닭을 짐작해 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u1-C17","difficulty":4,"kind":"essay","stem":"「언제나 다정 죽집」에 나타난 모습과 현실의 모습을 비교해 비슷한 점과 다른 점을 하나씩 쓰고, 글쓴이가 현실과 다르게 꾸며 쓴 까닭을 짐작해 쓰세요.","answer_guide":{"answer":"예: 비슷한 점 — 음식을 만들 때 가마솥, 주걱 같은 부엌 도구를 사용한다. 다른 점 — 이야기에서는 꾹꾹이를 받은 부엌 도구들이 말하고 스스로 움직이지만, 현실의 부엌 도구는 말하거나 움직일 수 없다. 까닭 — 늘 할머니 곁에 있던 부엌 도구의 눈으로 할머니의 다정함을 보여 주어 재미와 감동을 더 크게 주려고 꾸며 쓴 것 같다.","scoring_points":["같은 대상끼리 견주어 비슷한 점을 썼는가","같은 대상끼리 견주어 다른 점을 썼는가","꾸며 쓴 까닭을 재미·감동·깨달음이나 주제와 이어 썼는가"]},"explanation":["『국어』 61쪽 (1)번과 (2)번을 이은 활동이에요.","비교한 결과만 쓰지 말고 다르게 꾸며 쓴 까닭까지 생각해요.","그 까닭이 글쓴이가 전하려는 주제와 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_challenge#9','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C15',4,'essay','teacher','할머니처럼 남이 알아주지 않아도 누군가를 도왔던 경험, 또는 반대로 할머니와 다르게 행동했던 경험을 하나 쓰고, 그 경험에 비추어 할머니에게 하고 싶은 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C15","difficulty":4,"kind":"essay","stem":"할머니처럼 남이 알아주지 않아도 누군가를 도왔던 경험, 또는 반대로 할머니와 다르게 행동했던 경험을 하나 쓰고, 그 경험에 비추어 할머니에게 하고 싶은 말을 쓰세요.","answer_guide":{"answer":"예: 경험 — 모둠 청소 때 아무도 안 볼 것 같아서 사물함 뒤는 대충 닦고 끝낸 적이 있다. 하고 싶은 말 — 할머니, 손님이 투덜대도 설탕 하나 넣지 않고 몸에 좋은 팥죽을 끝까지 지키셨지요? 저는 보는 사람이 없으면 대충 했는데, 할머니를 보고 부끄러웠어요. 저도 다음에는 끝까지 정성을 다할게요.","scoring_points":["비슷한 경험이나 다르게 행동한 경험을 썼는가","경험이 할머니의 말이나 행동과 이어지는가","할머니의 행동을 짚어 하고 싶은 말을 썼는가"]},"explanation":["『국어』 60쪽 「자신과 관련짓기」 활동이에요.","인물과 다르게 행동했던 경험도 이야기를 깊이 이해하게 해 줘요.","경험이 없다면 책이나 동영상에서 본 일을 떠올려도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L04_challenge#10','kor',4,2,'u1','L04','tb_g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C19',4,'essay','teacher','「언제나 다정 죽집」의 할머니처럼 주변에서 도움이 필요한 사람을 떠올려 도와줄 방법을 상상해 쓰고, 그 방법이 현실에서 그 사람에게 어떤 도움이 될지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u1-C19","difficulty":4,"kind":"essay","stem":"「언제나 다정 죽집」의 할머니처럼 주변에서 도움이 필요한 사람을 떠올려 도와줄 방법을 상상해 쓰고, 그 방법이 현실에서 그 사람에게 어떤 도움이 될지 쓰세요.","answer_guide":{"answer":"예: 도움이 필요한 사람 — 무거운 장바구니를 들고 계단을 오르시는 옆집 할머니. 방법 — 날개 달린 바구니를 만들어 장바구니가 저절로 떠서 계단을 올라가게 하고 싶다. 현실에서는 — 할머니가 장을 보고 오시는 시간에 맞춰 내가 짐을 함께 들어 드릴 수 있다. 그러면 할머니의 허리와 무릎이 덜 아프실 것이다.","scoring_points":["도움이 필요한 사람을 구체적으로 떠올렸는가","도와줄 방법을 상상해 썼는가","현실에서 줄 수 있는 도움과 이어 썼는가"]},"explanation":["『국어』 61쪽 「세상과 연결하기」 활동이에요.","작품 속 세계, 현실 세계, 자기 세계를 연결해 생각해요.","상상한 방법이 현실에서 어떤 도움이 될지까지 생각하면 더 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_basic#1','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C21',1,'mc','auto','『국어』 62~63쪽에서 학교 누리집에 올라온 글 ㉮와 글 ㉯는 무엇에 대해 쓴 글인가요?',ARRAY['K4-2-u1-X18']::text[],false,'{"seq":1,"concept":"K4-2-u1-C21","difficulty":1,"kind":"mc","stem":"『국어』 62~63쪽에서 학교 누리집에 올라온 글 ㉮와 글 ㉯는 무엇에 대해 쓴 글인가요?","options":[{"t":"점심시간에 운동장에서 축구를 하는 것","correct":true},{"t":"1학년 동생의 하교 시간","mis":"K4-2-u1-X18"},{"t":"학교 누리집을 만드는 방법","mis":"K4-2-u1-X18"},{"t":"급식을 먹는 차례","mis":"K4-2-u1-X18"}],"explanation":["두 글의 제목에 모두 「점심시간」과 「축구」가 나와요.","두 글은 같은 문제를 다뤄요.","같은 문제를 두고 의견이 서로 달라요."],"asset":{"type":"passage","lines":["㉮ [간추림] 축구를 할 수 있는 시간은 점심시간뿐이고, 즐겁고 건강에도 좋다.","㉮ [간추림] 운동장은 모두의 공간이고, 위험하면 그물망·안전 수칙으로 막으면 된다.","㉮ [간추림] 그래서 점심시간에 운동장에서 축구를 하는 것에 찬성한다.","㉯ [간추림] 쉬는 시간인 것은 맞지만, 고학년 점심시간은 저학년 하교 시간이다.","㉯ [간추림] 지난봄 1학년 동생이 공에 맞아 다쳤고, 축구하는 사람도 다칠 수 있다.","㉯ [간추림] 그래서 점심시간에 운동장에서 축구를 하는 것에 반대한다."],"title":"학교 누리집에 올라온 두 글 — 『국어』 62~63쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_basic#2','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C20',1,'mc','auto','『국어』 63쪽 1번 (1)번이에요. 글 ㉮에 나타난 글쓴이의 의견은 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X24']::text[],false,'{"seq":2,"concept":"K4-2-u1-C20","difficulty":1,"kind":"mc","stem":"『국어』 63쪽 1번 (1)번이에요. 글 ㉮에 나타난 글쓴이의 의견은 무엇인가요?","options":[{"t":"점심시간에 운동장에서 축구를 하는 것에 찬성한다","correct":true},{"t":"점심시간에 운동장에서 축구를 하는 것에 반대한다","mis":"K4-2-u1-X19"},{"t":"운동장은 우리 학교 학생 모두의 공간이다","mis":"K4-2-u1-X24"},{"t":"높은 그물망은 필요 없다","mis":"K4-2-u1-X19"}],"explanation":["글 ㉮의 끝 문장이 「따라서 저는 … 찬성해요.」예요.","「운동장은 모두의 공간이다」는 의견을 받쳐 주는 이유예요.","의견은 문제에 대한 글쓴이의 생각이에요."],"asset":{"type":"passage","lines":["우리가 친구들과 모여 축구를 할 수 있는 시간은 점심시간뿐이에요.","[간추림] 점심시간에 축구를 하면 즐거울 뿐만 아니라 건강에도 도움이 된다.","[간추림] 운동장은 우리 학교 학생 모두의 공간이다.","[간추림] 위험이 걱정된다면 높은 그물망을 설치하거나 안전 수칙을 정하면 된다.","따라서 저는 점심시간에 운동장에서 축구를 하는 것에 찬성해요."],"title":"「점심시간에 친구들과 축구를 하고 싶어요」(글 ㉮) — 『국어』 62쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_basic#3','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C20',1,'sa','auto','글 ㉯의 글쓴이는 점심시간에 운동장에서 축구를 하는 것에 찬성하나요, 반대하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u1-C20","difficulty":1,"kind":"sa","stem":"글 ㉯의 글쓴이는 점심시간에 운동장에서 축구를 하는 것에 찬성하나요, 반대하나요? 두 글자로 쓰세요.","answer":["반대","반대해요","반대한다"],"explanation":["글 ㉯의 제목은 「점심시간에 운동장에서 축구를 하는 것은 위험해요」예요.","끝부분에서 모두의 안전을 위해 반대한다고 했어요.","글 ㉮와 의견이 서로 달라요."],"asset":{"type":"passage","lines":["[간추림] 점심시간이 급식을 먹은 뒤 자유롭게 쉬는 시간인 것은 맞다.","그런데 우리 학교 고학년의 점심시간은 저학년의 하교 시간이기도 해요.","지난봄에 하교하던 1학년 동생이 축구공에 맞아서 다친 적이 있어요.","[간추림] 축구를 하는 사람도 크게 다칠 위험이 있다.","[간추림] 그래서 모두의 안전을 위해 점심시간 운동장 축구에 반대한다."],"title":"「점심시간에 운동장에서 축구를 하는 것은 위험해요」(글 ㉯) — 『국어』 63쪽"},"mis":"K4-2-u1-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_basic#4','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C24',1,'ox','auto','글 ㉮와 글 ㉯처럼 같은 문제에 대해 의견이 서로 반대이면 둘 가운데 하나는 틀린 의견이에요.',ARRAY['K4-2-u1-X21']::text[],false,'{"seq":4,"concept":"K4-2-u1-C24","difficulty":1,"kind":"ox","stem":"글 ㉮와 글 ㉯처럼 같은 문제에 대해 의견이 서로 반대이면 둘 가운데 하나는 틀린 의견이에요.","answer":"X","reason_options":[{"t":"사람마다 경험과 생각이 달라 의견이 다를 수 있고, 이유가 알맞은지 따져 보아야 하기 때문에","correct":true},{"t":"같은 문제에 대한 맞는 의견은 하나뿐이기 때문에","mis":"K4-2-u1-X21"}],"mis":"K4-2-u1-X21","explanation":["글 ㉮는 축구 시간이 점심시간뿐이라는 경험을, 글 ㉯는 동생이 다친 경험을 들었어요.","의견이 다르다고 틀린 것은 아니에요.","어느 의견이 더 적절한지는 이유를 따져서 판단해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_basic#5','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C22',2,'match','auto','두 글에 나온 내용과 그 내용을 쓴 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u1-C22","difficulty":2,"kind":"match","stem":"두 글에 나온 내용과 그 내용을 쓴 곳을 알맞게 이으세요.","pairs":[{"l":"축구를 하면 즐겁고 건강에도 도움이 된다","r":"글 ㉮의 이유"},{"l":"고학년 점심시간은 저학년 하교 시간이다","r":"글 ㉯의 이유"},{"l":"점심시간은 자유롭게 지내는 시간이다","r":"두 글이 함께 인정한 것"}],"mis":"K4-2-u1-X19","explanation":["글쓴이마다 자기 의견을 받쳐 주는 이유가 달라요.","글 ㉯도 「점심시간이 … 자유롭게 쉬는 시간인 것은 맞아요.」라고 인정했어요.","이유를 섞지 않고 글쓴이별로 가르면 비교하기 쉬워요."],"asset":{"type":"passage","lines":["㉮ [간추림] 축구를 할 수 있는 시간은 점심시간뿐이고, 즐겁고 건강에도 좋다.","㉮ [간추림] 운동장은 모두의 공간이고, 위험하면 그물망·안전 수칙으로 막으면 된다.","㉮ [간추림] 그래서 점심시간에 운동장에서 축구를 하는 것에 찬성한다.","㉯ [간추림] 쉬는 시간인 것은 맞지만, 고학년 점심시간은 저학년 하교 시간이다.","㉯ [간추림] 지난봄 1학년 동생이 공에 맞아 다쳤고, 축구하는 사람도 다칠 수 있다.","㉯ [간추림] 그래서 점심시간에 운동장에서 축구를 하는 것에 반대한다."],"title":"학교 누리집에 올라온 두 글 — 『국어』 62~63쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_basic#6','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C23',2,'mc','auto','『국어』 63쪽 2번이에요. 다른 의견이 담긴 글을 비교하며 읽으면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X20','K4-2-u1-X21']::text[],false,'{"seq":6,"concept":"K4-2-u1-C23","difficulty":2,"kind":"mc","stem":"『국어』 63쪽 2번이에요. 다른 의견이 담긴 글을 비교하며 읽으면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"같은 문제에 대한 다양한 생각을 알 수 있다","correct":true},{"t":"더 긴 글의 의견을 따르면 된다는 것을 알 수 있다","mis":"K4-2-u1-X20"},{"t":"나와 같은 의견의 글만 골라 읽게 된다","mis":"K4-2-u1-X20"},{"t":"어느 글이 틀렸는지 바로 알 수 있다","mis":"K4-2-u1-X21"}],"explanation":["2번의 예시는 세 가지예요.","다양한 생각을 알 수 있고, 내 의견을 생각하는 데 도움이 돼요.","또 더 적절한 의견이 무엇인지 비교하고 평가할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_basic#7','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C22',2,'mc','auto','글 ㉯의 글쓴이가 반대 의견을 받쳐 주려고 든 이유로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X19']::text[],false,'{"seq":7,"concept":"K4-2-u1-C22","difficulty":2,"kind":"mc","stem":"글 ㉯의 글쓴이가 반대 의견을 받쳐 주려고 든 이유로 알맞은 것은 무엇인가요?","options":[{"t":"축구를 하는 사람도 크게 다칠 위험이 있다","correct":true},{"t":"축구를 하면 건강에 도움이 된다","mis":"K4-2-u1-X19"},{"t":"높은 그물망을 설치하면 된다","mis":"K4-2-u1-X19"},{"t":"운동장은 학생 모두의 공간이다","mis":"K4-2-u1-X19"}],"explanation":["글 ㉯는 저학년의 하교 시간, 동생이 다친 일, 축구하는 사람의 위험을 들었어요.","나머지는 글 ㉮의 이유예요.","두 글쓴이의 이유를 섞지 않아요."],"asset":{"type":"passage","lines":["[간추림] 점심시간이 급식을 먹은 뒤 자유롭게 쉬는 시간인 것은 맞다.","그런데 우리 학교 고학년의 점심시간은 저학년의 하교 시간이기도 해요.","지난봄에 하교하던 1학년 동생이 축구공에 맞아서 다친 적이 있어요.","[간추림] 축구를 하는 사람도 크게 다칠 위험이 있다.","[간추림] 그래서 모두의 안전을 위해 점심시간 운동장 축구에 반대한다."],"title":"「점심시간에 운동장에서 축구를 하는 것은 위험해요」(글 ㉯) — 『국어』 63쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_basic#8','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C25',2,'mc','auto','점심시간 운동장 사용에 대해 글 ㉮·㉯와 다른 새로운 의견으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X23','K4-2-u1-X21','K4-2-u1-X22']::text[],false,'{"seq":8,"concept":"K4-2-u1-C25","difficulty":2,"kind":"mc","stem":"점심시간 운동장 사용에 대해 글 ㉮·㉯와 다른 새로운 의견으로 알맞은 것은 무엇인가요?","options":[{"t":"저학년이 하교를 마친 뒤부터 운동장 한쪽에서 축구를 하자","correct":true},{"t":"두 의견 가운데 하나만 골라야 하니 새 의견은 낼 수 없다","mis":"K4-2-u1-X23"},{"t":"글 ㉮가 먼저 실렸으니 글 ㉮를 따르자","mis":"K4-2-u1-X21"},{"t":"의견은 다 맞으니 아무렇게나 하자","mis":"K4-2-u1-X22"}],"explanation":["점심시간 운동장 사용에 대한 또 다른 의견을 고민해 볼 수 있어요.","두 글쓴이의 의견 가운데 하나를 꼭 고를 필요는 없어요.","새 의견도 두 글의 걱정을 살피면 더 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_basic#9','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C20',2,'mc','auto','「아씨방 일곱 동무」에서 자 부인, 가위 색시, 바늘 각시가 서로 다르게 말한 것은 무엇에 대한 의견인가요?',ARRAY['K4-2-u1-X18','K4-2-u1-X24']::text[],false,'{"seq":9,"concept":"K4-2-u1-C20","difficulty":2,"kind":"mc","stem":"「아씨방 일곱 동무」에서 자 부인, 가위 색시, 바늘 각시가 서로 다르게 말한 것은 무엇에 대한 의견인가요?","options":[{"t":"바느질 동무 가운데 누가 가장 중요한가","correct":true},{"t":"아씨가 언제 낮잠을 자는가","mis":"K4-2-u1-X18"},{"t":"옷감을 어디에서 사는가","mis":"K4-2-u1-X18"},{"t":"구슬이 모두 몇 말인가","mis":"K4-2-u1-X24"}],"explanation":["세 동무는 저마다 자기가 가장 중요하다고 했어요.","같은 문제를 두고 의견이 서로 달라요.","모두 자기 일을 이유로 들었어요."],"asset":{"type":"passage","lines":["[간추림] 아씨가 낮잠이 든 사이, 바느질 동무들이 누가 가장 중요한지 다투었다.","[간추림] 자 부인 — 길고 짧음은 내가 아니면 알 수 없으니 내가 가장 중요하다.","[간추림] 가위 색시 — 옷감을 잘 재어도 자르지 않으면 소용없으니 내가 잘라야 한다.","“구슬이 서 말이라도 꿰어야 보배이지요.","[간추림] 바늘 각시 — 솔기를 꿰매야 입을 옷이 되니 내가 없으면 바느질을 못 한다."],"title":"「아씨방 일곱 동무」(이영경) 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_basic#10','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C21',3,'mc','auto','글 ㉮와 글 ㉯의 글쓴이가 생각이 같은 곳과 갈린 곳을 바르게 가른 것은 무엇인가요?',ARRAY['K4-2-u1-X18']::text[],false,'{"seq":10,"concept":"K4-2-u1-C21","difficulty":3,"kind":"mc","stem":"글 ㉮와 글 ㉯의 글쓴이가 생각이 같은 곳과 갈린 곳을 바르게 가른 것은 무엇인가요?","options":[{"t":"같은 곳 — 점심시간은 자유롭게 지내는 시간이다 / 갈린 곳 — 그 시간에 운동장에서 축구를 해도 되는가","correct":true},{"t":"같은 곳 — 축구는 위험하다 / 갈린 곳 — 점심시간이 있는가","mis":"K4-2-u1-X18"},{"t":"같은 곳 — 축구를 해도 된다 / 갈린 곳 — 운동장이 학교에 있는가","mis":"K4-2-u1-X18"},{"t":"같은 곳 — 없다 / 갈린 곳 — 모든 문장","mis":"K4-2-u1-X18"}],"explanation":["글 ㉯도 점심시간이 자유롭게 쉬는 시간인 것은 맞다고 했어요.","두 글이 갈린 곳은 운동장에서 축구를 해도 되는지예요.","같은 곳과 갈린 곳을 가르면 문제가 또렷해져요."],"asset":{"type":"passage","lines":["㉮ [간추림] 축구를 할 수 있는 시간은 점심시간뿐이고, 즐겁고 건강에도 좋다.","㉮ [간추림] 운동장은 모두의 공간이고, 위험하면 그물망·안전 수칙으로 막으면 된다.","㉮ [간추림] 그래서 점심시간에 운동장에서 축구를 하는 것에 찬성한다.","㉯ [간추림] 쉬는 시간인 것은 맞지만, 고학년 점심시간은 저학년 하교 시간이다.","㉯ [간추림] 지난봄 1학년 동생이 공에 맞아 다쳤고, 축구하는 사람도 다칠 수 있다.","㉯ [간추림] 그래서 점심시간에 운동장에서 축구를 하는 것에 반대한다."],"title":"학교 누리집에 올라온 두 글 — 『국어』 62~63쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_challenge#1','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C22',2,'mc','auto','「아씨방 일곱 동무」에서 가위 색시가 자기가 가장 중요하다는 의견을 받쳐 주려고 든 이유는 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X24']::text[],false,'{"seq":1,"concept":"K4-2-u1-C22","difficulty":2,"kind":"mc","stem":"「아씨방 일곱 동무」에서 가위 색시가 자기가 가장 중요하다는 의견을 받쳐 주려고 든 이유는 무엇인가요?","options":[{"t":"옷감을 잘 재어도 자르지 않으면 소용없으니 자기가 잘라야 일이 된다","correct":true},{"t":"길고 짧음은 자기가 아니면 알 수 없다","mis":"K4-2-u1-X19"},{"t":"솔기를 꿰매야 입을 옷이 된다","mis":"K4-2-u1-X19"},{"t":"자기 키가 가장 크다","mis":"K4-2-u1-X24"}],"explanation":["자 부인은 길이를 재는 일을, 바늘 각시는 꿰매는 일을 이유로 들었어요.","가위 색시는 자르는 일을 이유로 들었어요.","인물마다 이유를 섞지 않고 가려요."],"asset":{"type":"passage","lines":["[간추림] 아씨가 낮잠이 든 사이, 바느질 동무들이 누가 가장 중요한지 다투었다.","[간추림] 자 부인 — 길고 짧음은 내가 아니면 알 수 없으니 내가 가장 중요하다.","[간추림] 가위 색시 — 옷감을 잘 재어도 자르지 않으면 소용없으니 내가 잘라야 한다.","“구슬이 서 말이라도 꿰어야 보배이지요.","[간추림] 바늘 각시 — 솔기를 꿰매야 입을 옷이 되니 내가 없으면 바느질을 못 한다."],"title":"「아씨방 일곱 동무」(이영경) 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_challenge#2','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C23',2,'mc','auto','글 ㉮와 글 ㉯를 비교하며 읽은 친구가 「누구의 의견이 더 적절할까?」라고 말했어요. 이 물음과 이어지는 좋은 점은 무엇인가요?',ARRAY['K4-2-u1-X20']::text[],false,'{"seq":2,"concept":"K4-2-u1-C23","difficulty":2,"kind":"mc","stem":"글 ㉮와 글 ㉯를 비교하며 읽은 친구가 「누구의 의견이 더 적절할까?」라고 말했어요. 이 물음과 이어지는 좋은 점은 무엇인가요?","options":[{"t":"더 적절한 의견이 무엇인지 비교하고 평가할 수 있다","correct":true},{"t":"글쓴이의 이름을 외울 수 있다","mis":"K4-2-u1-X20"},{"t":"글자 수가 많은 글을 고를 수 있다","mis":"K4-2-u1-X20"},{"t":"내 생각은 하지 않아도 된다","mis":"K4-2-u1-X20"}],"explanation":["두 글을 나란히 놓으면 어느 의견이 더 알맞은지 따져 볼 수 있어요.","이것이 비교하며 읽으면 좋은 점 가운데 하나예요.","그러려면 의견을 받쳐 주는 이유를 살펴야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_challenge#3','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C24',3,'mc','auto','『국어』 63쪽 1번 (2)번에서 글 ㉯의 의견이 더 적절하다고 생각한 친구의 말 가운데 알맞게 판단한 것은 무엇인가요?',ARRAY['K4-2-u1-X30','K4-2-u1-X21','K4-2-u1-X22']::text[],false,'{"seq":3,"concept":"K4-2-u1-C24","difficulty":3,"kind":"mc","stem":"『국어』 63쪽 1번 (2)번에서 글 ㉯의 의견이 더 적절하다고 생각한 친구의 말 가운데 알맞게 판단한 것은 무엇인가요?","options":[{"t":"「하굣길에 축구공에 맞을까 봐 걱정했던 경험이 있어서 글 ㉯의 의견이 더 적절하다고 생각합니다.」","correct":true},{"t":"「글 ㉯가 더 뒤에 실려 있으니 더 적절합니다.」","mis":"K4-2-u1-X30"},{"t":"「글 ㉮는 축구를 좋아하는 사람이 썼으니 틀렸습니다.」","mis":"K4-2-u1-X21"},{"t":"「둘 다 맞으니 이유는 말하지 않겠습니다.」","mis":"K4-2-u1-X22"}],"explanation":["더 적절한 의견을 고를 때는 이유를 함께 말해요.","내 경험은 의견을 판단하는 좋은 이유가 돼요.","실린 차례나 글쓴이를 깎아내리는 것은 이유가 될 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_challenge#4','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C25',3,'ox','auto','글 ㉮와 글 ㉯를 읽고 내 의견을 정할 때는 반드시 두 글쓴이의 의견 가운데 하나를 골라야 해요.',ARRAY['K4-2-u1-X23']::text[],false,'{"seq":4,"concept":"K4-2-u1-C25","difficulty":3,"kind":"ox","stem":"글 ㉮와 글 ㉯를 읽고 내 의견을 정할 때는 반드시 두 글쓴이의 의견 가운데 하나를 골라야 해요.","answer":"X","reason_options":[{"t":"두 글을 비교한 뒤 새로운 의견을 낼 수도 있기 때문에","correct":true},{"t":"글에 나온 의견만 의견이 될 수 있기 때문에","mis":"K4-2-u1-X23"}],"mis":"K4-2-u1-X23","explanation":["점심시간 운동장 사용에 대한 또 다른 의견도 낼 수 있어요.","두 글을 비교하면 내 의견을 생각하는 데 도움이 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_challenge#5','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C20',3,'mc','auto','「아씨방 일곱 동무」의 세 동무처럼 같은 일을 두고 의견이 서로 다른 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X21','K4-2-u1-X22']::text[],false,'{"seq":5,"concept":"K4-2-u1-C20","difficulty":3,"kind":"mc","stem":"「아씨방 일곱 동무」의 세 동무처럼 같은 일을 두고 의견이 서로 다른 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"저마다 맡은 일이 달라서 자기 일이 가장 중요하다고 보기 때문이다","correct":true},{"t":"셋 가운데 둘은 바느질을 모르기 때문이다","mis":"K4-2-u1-X21"},{"t":"먼저 말한 자 부인의 말이 정답이기 때문이다","mis":"K4-2-u1-X21"},{"t":"의견은 다 맞으니 까닭을 따질 필요가 없기 때문이다","mis":"K4-2-u1-X22"}],"explanation":["자는 재고, 가위는 자르고, 바늘은 꿰매요.","맡은 일과 경험이 다르니 생각도 달라요.","그래서 서로의 이유를 견주어 볼 필요가 있어요."],"asset":{"type":"passage","lines":["[간추림] 아씨가 낮잠이 든 사이, 바느질 동무들이 누가 가장 중요한지 다투었다.","[간추림] 자 부인 — 길고 짧음은 내가 아니면 알 수 없으니 내가 가장 중요하다.","[간추림] 가위 색시 — 옷감을 잘 재어도 자르지 않으면 소용없으니 내가 잘라야 한다.","“구슬이 서 말이라도 꿰어야 보배이지요.","[간추림] 바늘 각시 — 솔기를 꿰매야 입을 옷이 되니 내가 없으면 바느질을 못 한다."],"title":"「아씨방 일곱 동무」(이영경) 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_challenge#6','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C22',3,'error','auto','글 ㉮의 의견과 이유를 정리했어요. 잘못 정리한 것은 무엇인가요?',ARRAY['K4-2-u1-X19']::text[],false,'{"seq":6,"concept":"K4-2-u1-C22","difficulty":3,"kind":"error","stem":"글 ㉮의 의견과 이유를 정리했어요. 잘못 정리한 것은 무엇인가요?","options":[{"t":"이유 — 지난봄에 하교하던 1학년 동생이 축구공에 맞아 다쳤다","correct":true,"mis_target":"K4-2-u1-X19"},{"t":"의견 — 점심시간에 운동장에서 축구를 하는 것에 찬성한다","mis":"K4-2-u1-X19"},{"t":"이유 — 축구할 수 있는 시간은 점심시간뿐이고, 즐겁고 건강해진다","mis":"K4-2-u1-X19"}],"explanation":["동생이 다친 일은 글 ㉯가 반대 이유로 든 경험이에요.","글 ㉮의 이유는 즐거움·건강, 모두의 공간, 그물망과 안전 수칙이에요.","글쓴이마다 이유를 섞지 않고 정리해요."],"asset":{"type":"passage","lines":["우리가 친구들과 모여 축구를 할 수 있는 시간은 점심시간뿐이에요.","[간추림] 점심시간에 축구를 하면 즐거울 뿐만 아니라 건강에도 도움이 된다.","[간추림] 운동장은 우리 학교 학생 모두의 공간이다.","[간추림] 위험이 걱정된다면 높은 그물망을 설치하거나 안전 수칙을 정하면 된다.","따라서 저는 점심시간에 운동장에서 축구를 하는 것에 찬성해요."],"title":"「점심시간에 친구들과 축구를 하고 싶어요」(글 ㉮) — 『국어』 62쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_challenge#7','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C21',3,'mc','auto','글 ㉮의 글쓴이는 축구가 위험하다는 걱정에 어떻게 답했나요?',ARRAY['K4-2-u1-X31','K4-2-u1-X19','K4-2-u1-X21']::text[],false,'{"seq":7,"concept":"K4-2-u1-C21","difficulty":3,"kind":"mc","stem":"글 ㉮의 글쓴이는 축구가 위험하다는 걱정에 어떻게 답했나요?","options":[{"t":"높은 그물망을 설치하거나 안전 수칙을 정하면 된다고 했다","correct":true},{"t":"위험한 일은 한 번도 일어나지 않는다고 장담했다","mis":"K4-2-u1-X31"},{"t":"저학년은 운동장에 나오지 말라고 했다","mis":"K4-2-u1-X19"},{"t":"걱정하는 사람의 의견은 틀렸다고 했다","mis":"K4-2-u1-X21"}],"explanation":["글 ㉮도 위험에 대한 걱정이 있다는 것을 알고 있어요.","그래서 그물망과 안전 수칙이라는 방법을 내놓았어요.","두 글이 무엇을 함께 걱정하는지 찾으면 비교가 쉬워요."],"asset":{"type":"passage","lines":["우리가 친구들과 모여 축구를 할 수 있는 시간은 점심시간뿐이에요.","[간추림] 점심시간에 축구를 하면 즐거울 뿐만 아니라 건강에도 도움이 된다.","[간추림] 운동장은 우리 학교 학생 모두의 공간이다.","[간추림] 위험이 걱정된다면 높은 그물망을 설치하거나 안전 수칙을 정하면 된다.","따라서 저는 점심시간에 운동장에서 축구를 하는 것에 찬성해요."],"title":"「점심시간에 친구들과 축구를 하고 싶어요」(글 ㉮) — 『국어』 62쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_challenge#8','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C24',4,'essay','teacher','글 ㉮와 글 ㉯ 가운데 어떤 의견이 더 적절하다고 생각하는지 쓰고, 그 까닭을 내 경험이나 글의 이유를 들어 쓰세요. 생각이 다른 친구에게 해 줄 말도 한 문장 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u1-C24","difficulty":4,"kind":"essay","stem":"글 ㉮와 글 ㉯ 가운데 어떤 의견이 더 적절하다고 생각하는지 쓰고, 그 까닭을 내 경험이나 글의 이유를 들어 쓰세요. 생각이 다른 친구에게 해 줄 말도 한 문장 쓰세요.","answer_guide":{"answer":"예: 저는 글 ㉯의 의견이 더 적절하다고 생각합니다. 저도 하굣길에 운동장을 지나다가 공이 날아와 깜짝 놀란 적이 있기 때문입니다. 저학년 동생들이 하교하는 시간에는 안전이 더 중요하다고 생각합니다. 친구에게 — 축구를 하고 싶은 마음도 이해해. 동생들이 다치지 않을 방법을 함께 찾아보자.","scoring_points":["더 적절하다고 생각하는 의견을 밝혔는가","경험이나 글의 이유를 근거로 들었는가","생각이 다른 친구를 존중하는 말을 썼는가"]},"explanation":["『국어』 63쪽 1번 (2)번을 넓힌 활동이에요.","더 적절한 의견은 이유를 들어 판단해요.","나와 생각이 달라도 틀린 것이 아니니 존중하며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_challenge#9','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C23',4,'essay','teacher','다른 의견이 담긴 글을 비교하며 읽으면 좋은 점 세 가지를 쓰고, 그 가운데 하나를 글 ㉮와 글 ㉯를 읽은 경험과 이어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C23","difficulty":4,"kind":"essay","stem":"다른 의견이 담긴 글을 비교하며 읽으면 좋은 점 세 가지를 쓰고, 그 가운데 하나를 글 ㉮와 글 ㉯를 읽은 경험과 이어 설명하세요.","answer_guide":{"answer":"예: 좋은 점 — ① 같은 문제에 대한 다양한 생각을 알 수 있다. ② 문제에 대한 내 의견을 생각하는 데 도움이 된다. ③ 더 적절한 의견이 무엇인지 비교하고 평가할 수 있다. 설명 — 글 ㉮만 읽었을 때는 축구가 좋다고만 생각했는데, 글 ㉯를 함께 읽으니 동생들의 하교 시간이 걱정되었다. 두 글을 견주어 보며 내 의견을 다시 생각하게 되었다.","scoring_points":["좋은 점 세 가지를 바르게 썼는가","좋은 점 하나를 두 글을 읽은 경험과 이었는가","설명이 좋은 점과 들어맞는가"]},"explanation":["『국어』 63쪽 2번 활동이에요.","세 가지 좋은 점을 기억해요.","내가 읽은 경험으로 설명하면 좋은 점이 더 또렷해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L07_challenge#10','kor',4,2,'u1','L07','tb_g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C25',4,'essay','teacher','점심시간 운동장 사용에 대해 글 ㉮·㉯와 다른 새로운 의견을 하나 쓰고, 그 의견이 두 글쓴이의 걱정을 어떻게 함께 살피는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u1-C25","difficulty":4,"kind":"essay","stem":"점심시간 운동장 사용에 대해 글 ㉮·㉯와 다른 새로운 의견을 하나 쓰고, 그 의견이 두 글쓴이의 걱정을 어떻게 함께 살피는지 쓰세요.","answer_guide":{"answer":"예: 의견 — 저학년이 하교하는 동안에는 운동장 한쪽을 비워 두고, 하교가 끝난 뒤부터 축구를 하자. 살피는 걱정 — 글 ㉮가 바란 점심시간 축구를 할 수 있고, 글 ㉯가 걱정한 동생들의 안전도 지킬 수 있다.","scoring_points":["두 글과 다른 새로운 의견을 썼는가","글 ㉮의 바람을 살폈는가","글 ㉯의 걱정을 살폈는가"]},"explanation":["점심시간 운동장 사용에 대한 또 다른 의견을 직접 말해 보는 활동이에요.","새 의견도 이유가 있어야 해요.","두 글의 걱정을 함께 살피면 더 많은 사람이 받아들일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_basic#1','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C26',1,'mc','auto','친구가 가을에 대한 생각을 「가을은 단풍이 드는 계절이라서 아름답다.」라고 한 문장으로 표현했어요. 생각(의견)과 그렇게 생각한 이유를 바르게 나눈 것은 무엇인가요?',ARRAY['K4-2-u1-X24']::text[],false,'{"seq":1,"concept":"K4-2-u1-C26","difficulty":1,"kind":"mc","stem":"친구가 가을에 대한 생각을 「가을은 단풍이 드는 계절이라서 아름답다.」라고 한 문장으로 표현했어요. 생각(의견)과 그렇게 생각한 이유를 바르게 나눈 것은 무엇인가요?","options":[{"t":"생각 — 가을은 아름답다 / 이유 — 단풍이 드는 계절이라서","correct":true},{"t":"생각 — 단풍이 드는 계절이라서 / 이유 — 가을은 아름답다","mis":"K4-2-u1-X24"},{"t":"생각 — 단풍 / 이유 — 계절","mis":"K4-2-u1-X24"},{"t":"생각 — 가을 / 이유 — 아름답다","mis":"K4-2-u1-X24"}],"explanation":["의견은 어떤 것에 대한 나의 생각이에요.","이유는 그렇게 생각한 까닭이에요.","「~라서」, 「~때문에」 앞에 이유가 와요."],"asset":{"type":"speech","turns":[{"who":"하은","text":"가을은 단풍이 드는 계절이라서 아름답다."},{"who":"도현","text":"가을에는 시원한 바람이 불어 기분이 좋다."},{"who":"지아","text":"가을에는 맛있는 과일을 많이 먹을 수 있다."},{"who":"서준","text":"가을에는 학교 운동회를 해서 기대된다."},{"who":"유나","text":"가을마다 우리 가족은 등산을 해서 즐겁다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_basic#2','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C27',1,'mc','auto','『국어』 64쪽 2번이에요. 글 ㉮의 제목 「우리 전통 한복의 가치를 지켜 주세요」를 보고 짐작할 수 있는 글쓴이의 의견은 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X25','K4-2-u1-X26']::text[],false,'{"seq":2,"concept":"K4-2-u1-C27","difficulty":1,"kind":"mc","stem":"『국어』 64쪽 2번이에요. 글 ㉮의 제목 「우리 전통 한복의 가치를 지켜 주세요」를 보고 짐작할 수 있는 글쓴이의 의견은 무엇인가요?","options":[{"t":"전통 한복의 아름다움과 가치를 지키자","correct":true},{"t":"변형 한복도 새로운 아름다움으로 인정하자","mis":"K4-2-u1-X19"},{"t":"한복을 입지 말자","mis":"K4-2-u1-X25"},{"t":"제목은 믿을 수 없으니 짐작하지 않는다","mis":"K4-2-u1-X26"}],"explanation":["제목에 「지켜 주세요」라는 바람이 드러나 있어요.","제목을 보고 의견을 짐작할 수 있어요.","짐작한 의견은 글을 읽으며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_basic#3','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C28',1,'blank','auto','『국어』 64쪽 날개예요. 「(    )을 주의 깊게 살펴보거나 글쓴이가 글을 쓴 목적을 짐작해 보면 글쓴이의 의견을 파악할 수 있어요.」의 빈칸에 들어갈 말은 무엇인가요?',ARRAY['K4-2-u1-X30','K4-2-u1-X26']::text[],false,'{"seq":3,"concept":"K4-2-u1-C28","difficulty":1,"kind":"blank","stem":"『국어』 64쪽 날개예요. 「(    )을 주의 깊게 살펴보거나 글쓴이가 글을 쓴 목적을 짐작해 보면 글쓴이의 의견을 파악할 수 있어요.」의 빈칸에 들어갈 말은 무엇인가요?","options":[{"t":"제목","correct":true},{"t":"글자 수","mis":"K4-2-u1-X30"},{"t":"그림 색깔","mis":"K4-2-u1-X26"}],"explanation":["제목은 글쓴이의 의견을 짐작하게 해 주는 실마리예요.","글을 쓴 목적을 짐작하는 것도 도움이 돼요.","그다음 글을 읽으며 의견을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_basic#4','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C30',1,'ox','auto','글쓴이의 의견을 찾아 읽는 일은 『국어』에 실린 글에서만 해요.',ARRAY['K4-2-u1-X29']::text[],false,'{"seq":4,"concept":"K4-2-u1-C30","difficulty":1,"kind":"ox","stem":"글쓴이의 의견을 찾아 읽는 일은 『국어』에 실린 글에서만 해요.","answer":"X","reason_options":[{"t":"누리집 글, 신문, 광고처럼 생활에서 읽는 여러 글에도 글쓴이의 의견이 있기 때문에","correct":true},{"t":"생활 속 글에는 의견이 담기지 않기 때문에","mis":"K4-2-u1-X29"}],"mis":"K4-2-u1-X29","explanation":["이 소단원은 일상생활에서 읽는 다양한 글로 이어져요.","학교 누리집 글이나 신문 기사에도 의견이 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_basic#5','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C26',2,'mc','auto','『국어』 67쪽 4번 (1)번이에요. 국가유산청이 ‘한복 생활’을 무형유산으로 지정한 까닭은 무엇인가요?',ARRAY['K4-2-u1-X19']::text[],false,'{"seq":5,"concept":"K4-2-u1-C26","difficulty":2,"kind":"mc","stem":"『국어』 67쪽 4번 (1)번이에요. 국가유산청이 ‘한복 생활’을 무형유산으로 지정한 까닭은 무엇인가요?","options":[{"t":"한복을 우리나라의 소중하고 가치 있는 문화로 여기기 때문에","correct":true},{"t":"변형 한복이 인기를 얻었기 때문에","mis":"K4-2-u1-X19"},{"t":"외국인 관광객이 늘었기 때문에","mis":"K4-2-u1-X19"},{"t":"한복이 입고 벗기 편하기 때문에","mis":"K4-2-u1-X19"}],"explanation":["글 ㉮에 나온 내용이에요.","한복을 단순한 옷이 아니라 소중하고 가치 있는 문화로 여겼어요.","글 ㉮의 글쓴이는 이 사실을 의견의 바탕으로 썼어요."],"asset":{"type":"passage","lines":["한복은 예로부터 전해 내려오는 우리나라의 고유한 옷입니다.","[간추림] 국가유산청은 2022년에 한복을 입는 문화인 ‘한복 생활’을 무형유산으로 지정했다.","[간추림] 한복을 단순한 옷이 아니라 소중하고 가치 있는 문화로 여겼기 때문이다.","그러나 요즘에는 한복을 지나치게 변형하여 입는 사람들이 늘고 있습니다.","[간추림] 전문가들은 지나치게 변형된 한복을 외국인이 오해할 수 있다고 걱정한다.","전통이 사라지는 것은 짧은 시간이지만","사라진 전통을 회복하는 데에는 오랜 시간이 걸리기 때문입니다.","[간추림] 그러니 자긍심을 가지고 전통 한복의 아름다움과 가치를 지켜야 한다."],"title":"「우리 전통 한복의 가치를 지켜 주세요」(글 ㉮) — 『국어』 65쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_basic#6','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C29',2,'mc','auto','『국어』 67쪽 4번 (2)번이에요. 글 ㉯에 나온 변형 한복의 특징으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X11','K4-2-u1-X19']::text[],false,'{"seq":6,"concept":"K4-2-u1-C29","difficulty":2,"kind":"mc","stem":"『국어』 67쪽 4번 (2)번이에요. 글 ㉯에 나온 변형 한복의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"반짝이는 금박과 은박이 붙어 있고, 쉽게 입고 벗을 수 있다","correct":true},{"t":"치마가 땅바닥에 길게 끌린다","mis":"K4-2-u1-X11"},{"t":"전통 한복과 모양과 입는 방법이 똑같다","mis":"K4-2-u1-X11"},{"t":"오랜 역사와 전통 속에서 그대로 내려왔다","mis":"K4-2-u1-X19"}],"explanation":["변형 한복은 금박·은박이 붙고, 치마가 드레스처럼 풍성하지만 땅에 거의 끌리지 않아요.","전통 한복보다 쉽게 입고 벗을 수 있어 불편함이 적어요.","두 글쓴이는 이 같은 한복을 서로 다르게 보았어요."],"asset":{"type":"passage","lines":["[간추림] 우리 문화가 인기를 얻으며 고궁 같은 관광지에서 한복을 입는 사람이 늘었다.","[간추림] 이 한복은 전통 한복과 모양이나 입는 방법이 다르다.","[간추림] 금박·은박이 붙고, 드레스처럼 풍성하지만 땅에 거의 끌리지 않으며, 쉽게 입고 벗는다.","이러한 변형 한복은 전통 한복과 다르지만","한복을 입고 즐기는 사람들이 늘어난다는 점에서 그 의미가 큽니다.","[간추림] 우리 한복도 시대의 흐름에 맞게 변화하고 세계화해야 한다.","따라서 우리는 전통 한복의 아름다움만 고집할 것이 아니라","다양하고 새로운 아름다움을 존중해야 합니다."],"title":"「틀린 것이 아니라 새로운 아름다움으로 봐 주세요」(글 ㉯) — 『국어』 66쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_basic#7','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C28',2,'mc','auto','글 ㉯에서 글쓴이의 의견이 가장 잘 드러난 곳은 어디인가요?',ARRAY['K4-2-u1-X27','K4-2-u1-X24']::text[],false,'{"seq":7,"concept":"K4-2-u1-C28","difficulty":2,"kind":"mc","stem":"글 ㉯에서 글쓴이의 의견이 가장 잘 드러난 곳은 어디인가요?","options":[{"t":"전통 한복의 아름다움만 고집하지 말고 다양하고 새로운 아름다움을 존중해야 한다는 끝부분","correct":true},{"t":"우리나라 문화가 세계적으로 인기를 얻고 있다는 첫 부분","mis":"K4-2-u1-X27"},{"t":"변형 한복에 금박과 은박이 붙어 있다는 부분","mis":"K4-2-u1-X24"},{"t":"관광지에서 한복을 입는 사람이 많아졌다는 부분","mis":"K4-2-u1-X27"}],"explanation":["글쓴이의 의견은 대개 글의 끝부분에서 「따라서 ~해야 합니다」로 드러나요.","앞부분의 사실들은 의견을 받쳐 주는 바탕이에요.","제목으로 짐작한 의견을 끝부분에서 확인해요."],"asset":{"type":"passage","lines":["[간추림] 우리 문화가 인기를 얻으며 고궁 같은 관광지에서 한복을 입는 사람이 늘었다.","[간추림] 이 한복은 전통 한복과 모양이나 입는 방법이 다르다.","[간추림] 금박·은박이 붙고, 드레스처럼 풍성하지만 땅에 거의 끌리지 않으며, 쉽게 입고 벗는다.","이러한 변형 한복은 전통 한복과 다르지만","한복을 입고 즐기는 사람들이 늘어난다는 점에서 그 의미가 큽니다.","[간추림] 우리 한복도 시대의 흐름에 맞게 변화하고 세계화해야 한다.","따라서 우리는 전통 한복의 아름다움만 고집할 것이 아니라","다양하고 새로운 아름다움을 존중해야 합니다."],"title":"「틀린 것이 아니라 새로운 아름다움으로 봐 주세요」(글 ㉯) — 『국어』 66쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_basic#8','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C29',2,'mc','auto','글 ㉮와 글 ㉯의 글쓴이는 관광지에서 입는 변형 한복을 어떻게 다르게 보았나요?',ARRAY['K4-2-u1-X28','K4-2-u1-X18']::text[],false,'{"seq":8,"concept":"K4-2-u1-C29","difficulty":2,"kind":"mc","stem":"글 ㉮와 글 ㉯의 글쓴이는 관광지에서 입는 변형 한복을 어떻게 다르게 보았나요?","options":[{"t":"㉮는 우리 한복을 오해하게 할 수 있다고 걱정하고, ㉯는 한복을 즐기는 사람이 늘어나는 의미가 있다고 본다","correct":true},{"t":"㉮는 변형 한복을 본 적이 없고, ㉯만 보았다","mis":"K4-2-u1-X28"},{"t":"두 글쓴이 모두 변형 한복을 싫어한다","mis":"K4-2-u1-X18"},{"t":"㉯가 변형 한복을 잘못 보았다","mis":"K4-2-u1-X28"}],"explanation":["두 글쓴이는 같은 대상을 보았어요.","㉮는 전통을 지키는 쪽을, ㉯는 많은 사람이 즐기는 쪽을 중요하게 여겼어요.","한쪽이 잘못 본 것이 아니라 보는 눈이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_basic#9','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C30',2,'mc','auto','하솔이와 리윤이의 글을 읽었어요. 하솔이의 글에 나타난 의견은 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X24']::text[],false,'{"seq":9,"concept":"K4-2-u1-C30","difficulty":2,"kind":"mc","stem":"하솔이와 리윤이의 글을 읽었어요. 하솔이의 글에 나타난 의견은 무엇인가요?","options":[{"t":"학교 운동장을 주민들에게 개방해야 한다","correct":true},{"t":"학교 운동장은 온전히 아이들의 것이어야 한다","mis":"K4-2-u1-X19"},{"t":"학교는 공공시설이다","mis":"K4-2-u1-X24"},{"t":"주변에 공공 체육 시설이 부족하다","mis":"K4-2-u1-X24"}],"explanation":["하솔이는 첫 문장에서 의견을 밝혔어요.","「학교는 공공시설이다」, 「체육 시설이 부족하다」는 의견을 받쳐 주는 이유예요.","리윤이는 하솔이와 반대 의견이에요."],"asset":{"type":"passage","lines":["[하솔] 학교 운동장을 주민들에게 개방해야 해요.","[하솔] 첫째, 학교는 공공시설이니 모든 주민이 언제든지 이용할 수 있어야 해요.","[하솔] 둘째, 주변에 공공 체육 시설이 부족해 주민들이 운동할 곳이 없어요.","[리윤] 학교 운동장은 온전히 아이들의 것이어야 해요.","[리윤] 첫째, 학교는 가장 안전한 곳이어야 해요. 외부인에게 개방하면 사고나 위험이 생길 수 있어요.","[리윤] 둘째, 학교의 건물과 시설은 학생들의 학습을 위해 쓰이고 보호되어야 해요."],"title":"하솔이와 리윤이의 글 — 학교 운동장 개방"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_basic#10','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C27',3,'error','auto','글 ㉯의 제목 「틀린 것이 아니라 새로운 아름다움으로 봐 주세요」를 보고 의견을 짐작했어요. 잘못 짐작한 친구는 누구인가요?',ARRAY['K4-2-u1-X25','K4-2-u1-X26']::text[],false,'{"seq":10,"concept":"K4-2-u1-C27","difficulty":3,"kind":"error","stem":"글 ㉯의 제목 「틀린 것이 아니라 새로운 아름다움으로 봐 주세요」를 보고 의견을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"친구 다 — 「제목에 ‘틀린 것’이라는 말이 있으니 변형 한복이 틀렸다는 의견이야.」","correct":true,"mis_target":"K4-2-u1-X25"},{"t":"친구 가 — 「변형 한복을 새로운 아름다움으로 인정해 달라는 의견 같아.」","mis":"K4-2-u1-X26"},{"t":"친구 나 — 「제목으로 짐작한 뒤 끝부분에서 의견을 확인해 봐야겠어.」","mis":"K4-2-u1-X26"}],"explanation":["제목은 「틀린 것이 아니라」라고 했어요.","제목 속 낱말 하나만 보고 의견을 정하면 거꾸로 읽을 수 있어요.","제목으로 짐작하고 끝부분에서 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_challenge#1','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C26',2,'mc','auto','글 ㉮의 글쓴이가 의견을 받쳐 주려고 든 이유로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X24']::text[],false,'{"seq":1,"concept":"K4-2-u1-C26","difficulty":2,"kind":"mc","stem":"글 ㉮의 글쓴이가 의견을 받쳐 주려고 든 이유로 알맞은 것은 무엇인가요?","options":[{"t":"사라진 전통을 회복하는 데 오랜 시간이 걸리기 때문이다","correct":true},{"t":"한복을 입고 즐기는 사람이 늘어나기 때문이다","mis":"K4-2-u1-X19"},{"t":"한복도 시대의 흐름에 맞게 변해야 하기 때문이다","mis":"K4-2-u1-X19"},{"t":"한옥 마을에 관광객이 많기 때문이다","mis":"K4-2-u1-X24"}],"explanation":["『국어』 67쪽 5번 표의 글 ㉮ 칸이에요.","한복은 우리 고유의 소중한 문화이고, 왜곡된 전통을 회복하려면 오래 걸린다고 했어요.","나머지 두 가지는 글 ㉯의 이유예요."],"asset":{"type":"passage","lines":["한복은 예로부터 전해 내려오는 우리나라의 고유한 옷입니다.","[간추림] 국가유산청은 2022년에 한복을 입는 문화인 ‘한복 생활’을 무형유산으로 지정했다.","[간추림] 한복을 단순한 옷이 아니라 소중하고 가치 있는 문화로 여겼기 때문이다.","그러나 요즘에는 한복을 지나치게 변형하여 입는 사람들이 늘고 있습니다.","[간추림] 전문가들은 지나치게 변형된 한복을 외국인이 오해할 수 있다고 걱정한다.","전통이 사라지는 것은 짧은 시간이지만","사라진 전통을 회복하는 데에는 오랜 시간이 걸리기 때문입니다.","[간추림] 그러니 자긍심을 가지고 전통 한복의 아름다움과 가치를 지켜야 한다."],"title":"「우리 전통 한복의 가치를 지켜 주세요」(글 ㉮) — 『국어』 65쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_challenge#2','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C28',2,'mc','auto','서로 다른 글쓴이의 의견을 파악하는 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X26','K4-2-u1-X27','K4-2-u1-X25']::text[],false,'{"seq":2,"concept":"K4-2-u1-C28","difficulty":2,"kind":"mc","stem":"서로 다른 글쓴이의 의견을 파악하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"제목을 보고 짐작한다 → 글의 끝부분에서 의견을 확인한다 → 의견을 받쳐 주는 이유를 찾는다","correct":true},{"t":"이유를 먼저 센다 → 이유가 많은 쪽을 의견으로 정한다 → 제목은 보지 않는다","mis":"K4-2-u1-X26"},{"t":"첫 문장을 의견으로 정한다 → 끝부분은 읽지 않는다 → 이유를 찾는다","mis":"K4-2-u1-X27"},{"t":"제목을 의견으로 정한다 → 글은 읽지 않는다 → 이유도 찾지 않는다","mis":"K4-2-u1-X25"}],"explanation":["제목과 글을 쓴 목적으로 의견을 짐작해요.","글 끝부분의 「따라서 ~해야 합니다」에서 확인해요.","마지막으로 의견을 받쳐 주는 이유를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_challenge#3','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C26',3,'mc','auto','글 ㉮에 나온 문장 가운데 있었던 일(사실)을 나타낸 것은 무엇인가요?',ARRAY['K4-2-u1-X24']::text[],false,'{"seq":3,"concept":"K4-2-u1-C26","difficulty":3,"kind":"mc","stem":"글 ㉮에 나온 문장 가운데 있었던 일(사실)을 나타낸 것은 무엇인가요?","options":[{"t":"국가유산청은 2022년에 ‘한복 생활’을 무형유산으로 지정했다","correct":true},{"t":"우리는 전통 한복의 아름다움을 지켜야 한다","mis":"K4-2-u1-X24"},{"t":"스스로 자긍심을 가져야 한다","mis":"K4-2-u1-X24"},{"t":"왜곡하지 않고 보전해 나가야 한다","mis":"K4-2-u1-X24"}],"explanation":["언제 누가 무엇을 했는지 확인할 수 있는 것은 사실이에요.","「~해야 한다」는 글쓴이의 생각, 곧 의견이에요.","사실은 의견을 받쳐 주는 바탕으로 쓰여요."],"asset":{"type":"passage","lines":["한복은 예로부터 전해 내려오는 우리나라의 고유한 옷입니다.","[간추림] 국가유산청은 2022년에 한복을 입는 문화인 ‘한복 생활’을 무형유산으로 지정했다.","[간추림] 한복을 단순한 옷이 아니라 소중하고 가치 있는 문화로 여겼기 때문이다.","그러나 요즘에는 한복을 지나치게 변형하여 입는 사람들이 늘고 있습니다.","[간추림] 전문가들은 지나치게 변형된 한복을 외국인이 오해할 수 있다고 걱정한다.","전통이 사라지는 것은 짧은 시간이지만","사라진 전통을 회복하는 데에는 오랜 시간이 걸리기 때문입니다.","[간추림] 그러니 자긍심을 가지고 전통 한복의 아름다움과 가치를 지켜야 한다."],"title":"「우리 전통 한복의 가치를 지켜 주세요」(글 ㉮) — 『국어』 65쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_challenge#4','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C29',3,'mc','auto','두 글쓴이가 같은 대상(관광지에서 입는 한복)을 보고도 서로 다르게 판단한 것에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X28','K4-2-u1-X22']::text[],false,'{"seq":4,"concept":"K4-2-u1-C29","difficulty":3,"kind":"mc","stem":"두 글쓴이가 같은 대상(관광지에서 입는 한복)을 보고도 서로 다르게 판단한 것에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"무엇을 중요하게 여기느냐에 따라 같은 대상도 다르게 볼 수 있다","correct":true},{"t":"한쪽이 관광지에 가 보지 않고 잘못 본 것이다","mis":"K4-2-u1-X28"},{"t":"상대 글을 읽지 않고 무조건 반대한 것이다","mis":"K4-2-u1-X28"},{"t":"둘 다 맞으니 따져 볼 필요가 없다","mis":"K4-2-u1-X22"}],"explanation":["㉮는 전통을, ㉯는 많은 사람이 한복을 즐기는 것을 중요하게 여겼어요.","보는 눈이 다를 뿐 한쪽이 잘못 본 것이 아니에요.","그래도 어느 의견이 더 알맞은지는 이유를 따져 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_challenge#5','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C30',3,'mc','auto','리윤이가 의견을 받쳐 주려고 든 이유가 아닌 것은 무엇인가요?',ARRAY['K4-2-u1-X19']::text[],false,'{"seq":5,"concept":"K4-2-u1-C30","difficulty":3,"kind":"mc","stem":"리윤이가 의견을 받쳐 주려고 든 이유가 아닌 것은 무엇인가요?","options":[{"t":"주변에 공공 체육 시설이 부족해서 운동할 곳이 없다","correct":true},{"t":"학교는 아이들이 공부하고 생활하는 가장 안전한 곳이어야 한다","mis":"K4-2-u1-X19"},{"t":"학교의 건물과 시설은 학생들의 학습을 위해 쓰여야 한다","mis":"K4-2-u1-X19"},{"t":"외부인에게 개방하면 학생들이 사고나 위험에 노출될 수 있다","mis":"K4-2-u1-X19"}],"explanation":["공공 체육 시설이 부족하다는 것은 하솔이의 이유예요.","리윤이는 안전과 학생들의 시설을 이유로 들었어요.","글쓴이마다 이유를 섞지 않고 가려요."],"asset":{"type":"passage","lines":["[하솔] 학교 운동장을 주민들에게 개방해야 해요.","[하솔] 첫째, 학교는 공공시설이니 모든 주민이 언제든지 이용할 수 있어야 해요.","[하솔] 둘째, 주변에 공공 체육 시설이 부족해 주민들이 운동할 곳이 없어요.","[리윤] 학교 운동장은 온전히 아이들의 것이어야 해요.","[리윤] 첫째, 학교는 가장 안전한 곳이어야 해요. 외부인에게 개방하면 사고나 위험이 생길 수 있어요.","[리윤] 둘째, 학교의 건물과 시설은 학생들의 학습을 위해 쓰이고 보호되어야 해요."],"title":"하솔이와 리윤이의 글 — 학교 운동장 개방"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_challenge#6','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C27',3,'ox','auto','글쓴이의 의견은 언제나 제목에 그대로 나와 있으니, 제목만 읽으면 글 전체를 읽지 않아도 돼요.',ARRAY['K4-2-u1-X25']::text[],false,'{"seq":6,"concept":"K4-2-u1-C27","difficulty":3,"kind":"ox","stem":"글쓴이의 의견은 언제나 제목에 그대로 나와 있으니, 제목만 읽으면 글 전체를 읽지 않아도 돼요.","answer":"X","reason_options":[{"t":"제목은 의견을 짐작하는 실마리일 뿐이라 끝부분과 이유를 확인해야 하기 때문에","correct":true},{"t":"제목이 곧 글쓴이의 의견이기 때문에","mis":"K4-2-u1-X25"}],"mis":"K4-2-u1-X25","explanation":["제목은 의견을 짐작하게 도와줘요.","하지만 의견은 글의 끝부분에서 확인하고, 이유도 찾아야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_challenge#7','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C30',3,'mc','auto','한복 두 글처럼 서로 다른 의견을 파악하며 읽는 것을 넘어서 얻을 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X30','K4-2-u1-X36','K4-2-u1-X20']::text[],false,'{"seq":7,"concept":"K4-2-u1-C30","difficulty":3,"kind":"mc","stem":"한복 두 글처럼 서로 다른 의견을 파악하며 읽는 것을 넘어서 얻을 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여러 사람의 다양한 생각을 알고 문제를 해결하는 더 나은 방법을 찾을 수 있다","correct":true},{"t":"어느 글쓴이가 더 유명한지 알 수 있다","mis":"K4-2-u1-X30"},{"t":"반대 의견을 쓴 사람을 이길 수 있다","mis":"K4-2-u1-X36"},{"t":"나와 다른 의견은 읽지 않아도 된다는 것을 알 수 있다","mis":"K4-2-u1-X20"}],"explanation":["다른 의견이 있다는 것을 아는 데서 멈추지 않아요.","여러 생각을 알면 더 합리적인 방법을 찾을 수 있어요.","그래서 생활 속 글도 의견을 파악하며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_challenge#8','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C26',4,'essay','teacher','『국어』 67쪽 5번처럼 글 ㉮와 글 ㉯의 글쓴이의 의견과 그렇게 생각한 이유를 각각 정리해 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u1-C26","difficulty":4,"kind":"essay","stem":"『국어』 67쪽 5번처럼 글 ㉮와 글 ㉯의 글쓴이의 의견과 그렇게 생각한 이유를 각각 정리해 쓰세요.","answer_guide":{"answer":"예: 글 ㉮ — 의견: 우리 전통 한복의 아름다움과 가치를 지키자. 이유: 한복은 우리 고유의 소중하고 가치 있는 문화이기 때문이다. 왜곡된 전통을 회복하는 데 오랜 시간이 걸리기 때문이다. 글 ㉯ — 의견: 변형 한복을 입는 것도 새로운 아름다움으로 인정하자. 이유: 시대의 흐름에 맞는 변화로 많은 사람이 한복을 입고 즐길 수 있기 때문이다. 다양하고 새로운 아름다움을 존중해야 하기 때문이다.","scoring_points":["글 ㉮의 의견과 이유를 바르게 정리했는가","글 ㉯의 의견과 이유를 바르게 정리했는가","두 글의 이유를 섞지 않았는가"]},"explanation":["제목으로 짐작하고 끝부분에서 의견을 확인해요.","의견을 받쳐 주는 이유를 글쓴이별로 찾아요.","정리해 두면 두 의견을 비교하기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_challenge#9','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C29',4,'essay','teacher','『국어』 67쪽 6번처럼 두 글을 다시 읽고 한복에 대한 자신의 의견과 그 이유를 쓰세요. 두 글 가운데 어느 쪽 생각과 같은지, 다른지도 밝히세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C29","difficulty":4,"kind":"essay","stem":"『국어』 67쪽 6번처럼 두 글을 다시 읽고 한복에 대한 자신의 의견과 그 이유를 쓰세요. 두 글 가운데 어느 쪽 생각과 같은지, 다른지도 밝히세요.","answer_guide":{"answer":"예: 내 의견 — 변형 한복을 인정하되 우리 고유의 문화를 훼손하지 말자. 이유 — 한복을 간편하게 바꾸어 많은 사람이 즐기는 것은 좋지만, 옷고름이나 저고리처럼 한복의 고유한 모습까지 없애면 전통이 사라질 수 있기 때문이다. 나는 두 글의 생각을 함께 살펴 새로운 의견을 냈다.","scoring_points":["자신의 의견을 밝혔는가","의견을 받쳐 주는 이유를 썼는가","두 글과 같거나 다른 점을 밝혔는가"]},"explanation":["『국어』 67쪽 6번 활동이에요.","두 글 가운데 하나와 같아도 되고, 새로운 의견이어도 돼요.","어느 쪽이든 이유를 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L08_challenge#10','kor',4,2,'u1','L08','tb_g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C30',4,'essay','teacher','하솔이와 리윤이의 글에서 각각 의견과 이유를 하나씩 찾아 쓰고, 학교 운동장을 주민들에게 개방하는 것에 대한 나의 의견을 이유와 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u1-C30","difficulty":4,"kind":"essay","stem":"하솔이와 리윤이의 글에서 각각 의견과 이유를 하나씩 찾아 쓰고, 학교 운동장을 주민들에게 개방하는 것에 대한 나의 의견을 이유와 함께 쓰세요.","answer_guide":{"answer":"예: 하솔 — 의견: 학교 운동장을 주민들에게 개방해야 한다. 이유: 주변에 공공 체육 시설이 부족하다. 리윤 — 의견: 학교 운동장은 온전히 아이들의 것이어야 한다. 이유: 외부인에게 개방하면 학생들이 위험해질 수 있다. 내 의견 — 학생들이 하교한 저녁과 주말에만 운동장을 개방하면 좋겠다. 학생들의 안전도 지키고 주민들도 운동할 수 있기 때문이다.","scoring_points":["하솔이의 의견과 이유를 찾았는가","리윤이의 의견과 이유를 찾았는가","나의 의견과 이유를 썼는가"]},"explanation":["글쓴이의 의견이 무엇인지 생각하며 두 글을 읽어요.","의견과 이유를 글쓴이별로 정리해요.","두 글을 견주면 내 의견을 정하는 데 도움이 돼요."],"asset":{"type":"passage","lines":["[하솔] 학교 운동장을 주민들에게 개방해야 해요.","[하솔] 첫째, 학교는 공공시설이니 모든 주민이 언제든지 이용할 수 있어야 해요.","[하솔] 둘째, 주변에 공공 체육 시설이 부족해 주민들이 운동할 곳이 없어요.","[리윤] 학교 운동장은 온전히 아이들의 것이어야 해요.","[리윤] 첫째, 학교는 가장 안전한 곳이어야 해요. 외부인에게 개방하면 사고나 위험이 생길 수 있어요.","[리윤] 둘째, 학교의 건물과 시설은 학생들의 학습을 위해 쓰이고 보호되어야 해요."],"title":"하솔이와 리윤이의 글 — 학교 운동장 개방"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_basic#1','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C31',1,'match','auto','『국어』 71쪽 「낱말 알기」예요. 밑줄 그은 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u1-C31","difficulty":1,"kind":"match","stem":"『국어』 71쪽 「낱말 알기」예요. 밑줄 그은 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"삶을 더욱 편리하게 합니다","r":"편하고 이로우며 이용하기 쉽다"},{"l":"무인 안내기를 설치하여","r":"필요한 기구나 시설 따위를 두다"},{"l":"기기 사용에 취약한 사람","r":"무르고 약하다"},{"l":"카드로만 결제해야","r":"값을 치르다"}],"mis":"K4-2-u1-X12","explanation":["밑줄 그은 낱말의 앞뒤 문맥으로 뜻을 짐작해요.","「설치하다」는 기계를 두는 것, 「결제하다」는 값을 치르는 것이에요.","「취약하다」는 무르고 약하다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_basic#2','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C32',1,'blank','auto','『국어』 72쪽 날개 「글쓴이의 의견을 평가할 때에는 문제 상황에 (    ) 의견인지, 의견을 뒷받침하는 이유가 타당한지 살펴봐요.」의 빈칸에 들어갈 말은 무엇인가요?',ARRAY['K4-2-u1-X30']::text[],false,'{"seq":2,"concept":"K4-2-u1-C32","difficulty":1,"kind":"blank","stem":"『국어』 72쪽 날개 「글쓴이의 의견을 평가할 때에는 문제 상황에 (    ) 의견인지, 의견을 뒷받침하는 이유가 타당한지 살펴봐요.」의 빈칸에 들어갈 말은 무엇인가요?","options":[{"t":"적절한","correct":true},{"t":"긴","mis":"K4-2-u1-X30"},{"t":"유명한","mis":"K4-2-u1-X30"},{"t":"재미있는","mis":"K4-2-u1-X30"}],"explanation":["날개 말풍선 두 개를 떠올려요.","문제 상황에 적절한지, 이유가 타당한지 살펴봐요.","또 의견대로 했을 때 다른 문제가 생기지 않을지도 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_basic#3','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C26',1,'mc','auto','무인 안내기에 대한 글 ㉮의 글쓴이의 의견은 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X24']::text[],false,'{"seq":3,"concept":"K4-2-u1-C26","difficulty":1,"kind":"mc","stem":"무인 안내기에 대한 글 ㉮의 글쓴이의 의견은 무엇인가요?","options":[{"t":"무인 안내기를 더 많이 설치하여 활용해야 한다","correct":true},{"t":"무인 안내기를 더 많이 설치하면 안 된다","mis":"K4-2-u1-X19"},{"t":"무인 안내기는 식당과 은행에서 쓰인다","mis":"K4-2-u1-X24"},{"t":"직원에게 주는 비용을 줄일 수 있다","mis":"K4-2-u1-X24"}],"explanation":["『국어』 72쪽 (1)번 표의 글 ㉮ 칸이에요.","끝부분의 「그러므로 … 설치하여 활용해야 합니다.」가 의견이에요.","비용을 줄일 수 있다는 것은 이유예요."],"asset":{"type":"passage","lines":["[간추림] 직원 도움 없이 혼자 주문이나 결제를 하는 무인 안내기가 여러 곳에서 쓰인다.","첫째, 무인 안내기를 이용하면 빠르고 정확하게 일을 처리할 수 있습니다.","[간추림] 줄 서지 않고 자리에서 곧바로 주문하고, 사진을 보고 골라 실수가 준다.","둘째, 무인 안내기를 이용하는 것이 더 경제적입니다.","[간추림] 일을 처리해 주는 사람이 덜 필요해 직원에게 주는 비용을 줄일 수 있다.","셋째, 우리말에 서툰 사람들도 무인 안내기를 쉽게 이용할 수 있습니다.","[간추림] 그러므로 더 많은 곳에서 다양한 무인 안내기를 설치하여 활용해야 한다."],"title":"「편리한 무인 안내기」(글 ㉮) — 『국어』 69쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_basic#4','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C33',1,'ox','auto','글 ㉯의 글쓴이가 고령층이 무인 안내기를 쓰지 못하는 까닭을 서울AI(에이아이)재단의 조사 결과로 뒷받침한 것은 이유를 믿을 만하게 해 줘요.',ARRAY['K4-2-u1-X31']::text[],false,'{"seq":4,"concept":"K4-2-u1-C33","difficulty":1,"kind":"ox","stem":"글 ㉯의 글쓴이가 고령층이 무인 안내기를 쓰지 못하는 까닭을 서울AI(에이아이)재단의 조사 결과로 뒷받침한 것은 이유를 믿을 만하게 해 줘요.","answer":"O","reason_options":[{"t":"누가 언제 조사했는지 밝힌 자료는 이유를 믿을 만하게 해 주기 때문에","correct":true},{"t":"조사 결과는 의견과 상관없는 내용이기 때문에","mis":"K4-2-u1-X31"}],"mis":"K4-2-u1-X31","explanation":["이유가 타당한지 볼 때는 이유가 믿을 만한지 살펴요.","조사한 곳(서울AI재단)과 때(2021년)가 밝혀져 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["[간추림] 무인 안내기의 장점 뒤에는 여러 가지 단점이 있다.","첫째, 신체 조건이 맞지 않는 사람은 무인 안내기를 이용하기 어렵습니다.","[간추림] 휠체어를 탄 사람·키가 작은 사람은 쓰기 불편하고, 음성 안내가 없으면 시각 장애인은 못 쓴다.","둘째, 사용 방법이 익숙하지 않은 사람에게 무인 안내기는 전혀 편리하지 않습니다.","[간추림] 서울AI(에이아이)재단 2021년 조사 — 고령층이 못 쓰는 가장 큰 까닭은 사용 방법을 몰라서.","셋째, 현금만 있는 사람은 무인 안내기를 이용하기 어려운 경우가 많습니다.","[간추림] 그러므로 무작정 더 설치하기보다 이용하기 어려운 사람들의 불편을 줄일 방법을 고민해야 한다."],"title":"「무인 안내기, 누군가에게는 큰 불편」(글 ㉯) — 『국어』 70쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_basic#5','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C34',2,'mc','auto','『국어』 71쪽 「내용 알기」 (3)번이에요. 글 ㉯에서 무인 안내기가 불편할 수 있다고 한 사람이 아닌 것은 누구인가요?',ARRAY['K4-2-u1-X32']::text[],false,'{"seq":5,"concept":"K4-2-u1-C34","difficulty":2,"kind":"mc","stem":"『국어』 71쪽 「내용 알기」 (3)번이에요. 글 ㉯에서 무인 안내기가 불편할 수 있다고 한 사람이 아닌 것은 누구인가요?","options":[{"t":"우리말에 서툰 사람","correct":true},{"t":"신체 조건이 맞지 않는 사람","mis":"K4-2-u1-X32"},{"t":"사용 방법이 익숙하지 않은 사람","mis":"K4-2-u1-X32"},{"t":"현금만 있는 사람","mis":"K4-2-u1-X32"}],"explanation":["우리말에 서툰 사람은 글 ㉮에서 여러 언어 안내로 쉽게 쓸 수 있다고 한 사람이에요.","글 ㉯는 신체 조건, 사용 방법, 현금만 있는 사람을 들었어요.","이 사람들이 글 ㉮의 의견대로 했을 때 생길 문제와 이어져요."],"asset":{"type":"passage","lines":["[간추림] 무인 안내기의 장점 뒤에는 여러 가지 단점이 있다.","첫째, 신체 조건이 맞지 않는 사람은 무인 안내기를 이용하기 어렵습니다.","[간추림] 휠체어를 탄 사람·키가 작은 사람은 쓰기 불편하고, 음성 안내가 없으면 시각 장애인은 못 쓴다.","둘째, 사용 방법이 익숙하지 않은 사람에게 무인 안내기는 전혀 편리하지 않습니다.","[간추림] 서울AI(에이아이)재단 2021년 조사 — 고령층이 못 쓰는 가장 큰 까닭은 사용 방법을 몰라서.","셋째, 현금만 있는 사람은 무인 안내기를 이용하기 어려운 경우가 많습니다.","[간추림] 그러므로 무작정 더 설치하기보다 이용하기 어려운 사람들의 불편을 줄일 방법을 고민해야 한다."],"title":"「무인 안내기, 누군가에게는 큰 불편」(글 ㉯) — 『국어』 70쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_basic#6','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C22',2,'match','auto','『국어』 72쪽 (1)번 표를 채우려고 해요. 무인 안내기 글에 나온 내용과 그 내용이 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u1-C22","difficulty":2,"kind":"match","stem":"『국어』 72쪽 (1)번 표를 채우려고 해요. 무인 안내기 글에 나온 내용과 그 내용이 하는 일을 알맞게 이으세요.","pairs":[{"l":"빠르고 정확하게 일을 처리할 수 있다","r":"글 ㉮의 이유"},{"l":"신체 조건이 맞지 않는 사람은 이용하기 어렵다","r":"글 ㉯의 이유"},{"l":"무인 안내기는 식당, 은행, 병원에서 쓰인다","r":"무인 안내기를 소개한 내용"}],"mis":"K4-2-u1-X19","explanation":["글 ㉮는 「첫째」, 「둘째」, 「셋째」로 이유를 들었어요.","글 ㉯의 이유와 섞지 않아요.","쓰이는 곳은 이유가 아니라 무인 안내기를 소개한 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_basic#7','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C35',2,'mc','auto','글 ㉮도 이유를 셋, 글 ㉯도 이유를 셋 들었어요. 어느 의견이 더 적절한지 평가하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X33','K4-2-u1-X22']::text[],false,'{"seq":7,"concept":"K4-2-u1-C35","difficulty":2,"kind":"mc","stem":"글 ㉮도 이유를 셋, 글 ㉯도 이유를 셋 들었어요. 어느 의견이 더 적절한지 평가하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"이유가 문제 상황에 맞는지, 믿을 만한지를 하나하나 따져 본다","correct":true},{"t":"이유의 개수가 같으니 평가할 수 없다","mis":"K4-2-u1-X33"},{"t":"이유를 더 길게 쓴 글이 더 적절하다","mis":"K4-2-u1-X33"},{"t":"마음에 드는 글을 고르면 된다","mis":"K4-2-u1-X22"}],"explanation":["이유가 몇 개인지가 의견의 적절함을 정하지 않아요.","이유 하나하나가 타당한지 따져요.","이유와 상관없이 마음에 드는 쪽을 고르는 것은 평가가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_basic#8','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C38',2,'mc','auto','『국어』 73쪽 (3)번의 틀 「저는 ___(이)라고 생각합니다. 왜냐하면 ___ 때문입니다.」에 맞게 의견을 정리한 것은 무엇인가요?',ARRAY['K4-2-u1-X36','K4-2-u1-X24']::text[],false,'{"seq":8,"concept":"K4-2-u1-C38","difficulty":2,"kind":"mc","stem":"『국어』 73쪽 (3)번의 틀 「저는 ___(이)라고 생각합니다. 왜냐하면 ___ 때문입니다.」에 맞게 의견을 정리한 것은 무엇인가요?","options":[{"t":"저는 무인 안내기의 이용을 돕는 사람이 필요하다고 생각합니다. 왜냐하면 어려워하는 사람들이 익숙해지도록 도울 수 있기 때문입니다.","correct":true},{"t":"저는 무인 안내기가 싫습니다.","mis":"K4-2-u1-X36"},{"t":"무인 안내기는 식당, 은행, 병원에 있습니다.","mis":"K4-2-u1-X24"},{"t":"글 ㉮를 쓴 사람은 틀렸습니다.","mis":"K4-2-u1-X36"}],"explanation":["의견은 「~(이)라고 생각합니다」로 밝혀요.","이유는 「왜냐하면 ~ 때문입니다」로 이어 써요.","이유 없이 의견만 말하거나 다른 의견을 틀렸다고 하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_basic#9','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C37',2,'mc','auto','『국어』 73쪽 날개 「자신의 의견은 글쓴이의 의견과 다를 수도 있어요.」를 생각하며, 내 의견을 정할 때 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u1-X23','K4-2-u1-X35','K4-2-u1-X43']::text[],false,'{"seq":9,"concept":"K4-2-u1-C37","difficulty":2,"kind":"mc","stem":"『국어』 73쪽 날개 「자신의 의견은 글쓴이의 의견과 다를 수도 있어요.」를 생각하며, 내 의견을 정할 때 알맞은 생각은 무엇인가요?","options":[{"t":"내 의견은 글쓴이의 의견과 같아도 되고 달라도 된다","correct":true},{"t":"두 글쓴이 가운데 한 사람의 의견을 꼭 따라야 한다","mis":"K4-2-u1-X23"},{"t":"두 의견을 반씩 섞으면 저절로 가장 좋은 의견이 된다","mis":"K4-2-u1-X35"},{"t":"친구 의견과 다르면 내 의견을 바꿔야 한다","mis":"K4-2-u1-X43"}],"explanation":["날개는 「우리는 다양한 의견을 서로 존중해야 해요.」로 이어져요.","비교하고 평가한 내용을 바탕으로 내 의견을 정해요.","어떤 의견이든 이유가 타당해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_basic#10','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C34',3,'mc','auto','글 ㉮의 의견대로 무인 안내기를 더 많이 설치했을 때 생길 수 있는 문제로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X32','K4-2-u1-X47']::text[],false,'{"seq":10,"concept":"K4-2-u1-C34","difficulty":3,"kind":"mc","stem":"글 ㉮의 의견대로 무인 안내기를 더 많이 설치했을 때 생길 수 있는 문제로 알맞은 것은 무엇인가요?","options":[{"t":"휠체어를 탄 사람이나 디지털 기기 사용에 취약한 사람이 도움을 받기 더 어려워진다","correct":true},{"t":"식당에서 주문이 더 빨라진다","mis":"K4-2-u1-X32"},{"t":"직원에게 주는 비용이 줄어든다","mis":"K4-2-u1-X32"},{"t":"무인 안내기 화면의 색깔이 다양해진다","mis":"K4-2-u1-X47"}],"explanation":["글쓴이의 의견대로 했을 때 다른 문제가 생기지 않을지 생각해요.","글 ㉯가 걱정한 사람들이 실마리예요.","직원이 줄면 도움이 필요한 사람은 더 곤란해져요."],"asset":{"type":"passage","lines":["[간추림] 무인 안내기의 장점 뒤에는 여러 가지 단점이 있다.","첫째, 신체 조건이 맞지 않는 사람은 무인 안내기를 이용하기 어렵습니다.","[간추림] 휠체어를 탄 사람·키가 작은 사람은 쓰기 불편하고, 음성 안내가 없으면 시각 장애인은 못 쓴다.","둘째, 사용 방법이 익숙하지 않은 사람에게 무인 안내기는 전혀 편리하지 않습니다.","[간추림] 서울AI(에이아이)재단 2021년 조사 — 고령층이 못 쓰는 가장 큰 까닭은 사용 방법을 몰라서.","셋째, 현금만 있는 사람은 무인 안내기를 이용하기 어려운 경우가 많습니다.","[간추림] 그러므로 무작정 더 설치하기보다 이용하기 어려운 사람들의 불편을 줄일 방법을 고민해야 한다."],"title":"「무인 안내기, 누군가에게는 큰 불편」(글 ㉯) — 『국어』 70쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_challenge#1','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C31',2,'mc','auto','「디지털 기기 사용에 취약한 사람은 무인 안내기를 사용하기 어렵습니다.」에서 「취약한」과 뜻이 가장 비슷한 말은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":1,"concept":"K4-2-u1-C31","difficulty":2,"kind":"mc","stem":"「디지털 기기 사용에 취약한 사람은 무인 안내기를 사용하기 어렵습니다.」에서 「취약한」과 뜻이 가장 비슷한 말은 무엇인가요?","options":[{"t":"무르고 약한","correct":true},{"t":"값을 치른","mis":"K4-2-u1-X12"},{"t":"편하고 이로운","mis":"K4-2-u1-X12"},{"t":"새로 둔","mis":"K4-2-u1-X12"}],"explanation":["『국어』 71쪽 「낱말 알기」의 셋째 낱말이에요.","기기 다루는 데 약한 사람이라는 뜻이에요.","앞뒤 문맥을 보면 뜻을 짐작할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_challenge#2','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C37',2,'mc','auto','「당나귀를 팔러 가는 아버지와 아들」에서 아버지와 아들이 결국 당나귀를 잃게 된 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X22','K4-2-u1-X11','K4-2-u1-X21']::text[],false,'{"seq":2,"concept":"K4-2-u1-C37","difficulty":2,"kind":"mc","stem":"「당나귀를 팔러 가는 아버지와 아들」에서 아버지와 아들이 결국 당나귀를 잃게 된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"여러 의견을 따져 보지 않고 사람들의 말을 그때그때 그대로 따랐기 때문이다","correct":true},{"t":"사람들의 말을 하나도 듣지 않았기 때문이다","mis":"K4-2-u1-X22"},{"t":"당나귀가 너무 작았기 때문이다","mis":"K4-2-u1-X11"},{"t":"의견이 여러 가지인 것 자체가 잘못이기 때문이다","mis":"K4-2-u1-X21"}],"explanation":["사람마다 경험과 생각이 달라 여러 의견이 나왔어요.","아버지와 아들은 의견을 비교하고 평가하지 않고 그대로 따랐어요.","의견을 따져 보고 스스로 정해야 문제를 해결할 수 있어요."],"asset":{"type":"passage","lines":["[간추림] 아버지와 아들이 당나귀를 팔러 장에 가고 있었다.","[간추림] “왜 타지 않고 걷나?” 하는 말에 아들이 탔다.","[간추림] “아버지를 걷게 하다니!” 하는 말에 아버지가 타고 아들이 걸었다.","[간추림] 아들이 안됐다는 말에 둘 다 탔고, 당나귀가 불쌍하다는 말에 당나귀를 들고 갔다.","[간추림] 사람들이 놀리며 웃자, 놀란 당나귀는 강에 빠지고 말았다."],"title":"이야기 「당나귀를 팔러 가는 아버지와 아들」(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_challenge#3','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C32',3,'mc','auto','무인 안내기를 더 늘릴지에 대한 글을 읽고 친구들이 의견을 냈어요. 문제 상황에 가장 적절한 의견은 무엇인가요?',ARRAY['K4-2-u1-X47','K4-2-u1-X30']::text[],false,'{"seq":3,"concept":"K4-2-u1-C32","difficulty":3,"kind":"mc","stem":"무인 안내기를 더 늘릴지에 대한 글을 읽고 친구들이 의견을 냈어요. 문제 상황에 가장 적절한 의견은 무엇인가요?","options":[{"t":"무인 안내기에 음성 안내와 낮은 화면을 갖추고, 도와줄 사람을 함께 두자","correct":true},{"t":"무인 안내기 화면 배경을 예쁜 그림으로 바꾸자","mis":"K4-2-u1-X47"},{"t":"식당 차림표의 음식 가짓수를 더 늘리자","mis":"K4-2-u1-X47"},{"t":"무인 안내기에 대한 글을 더 길게 쓰자","mis":"K4-2-u1-X30"}],"explanation":["문제 상황은 무인 안내기를 이용하기 어려운 사람이 있다는 것이에요.","적절한 의견은 이 문제와 관련 있어야 해요.","그럴듯해 보여도 문제 상황과 상관없으면 적절하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_challenge#4','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C36',3,'mc','auto','글 ㉮와 글 ㉯를 공평하게 평가한 친구는 누구인가요?',ARRAY['K4-2-u1-X34','K4-2-u1-X33']::text[],false,'{"seq":4,"concept":"K4-2-u1-C36","difficulty":3,"kind":"mc","stem":"글 ㉮와 글 ㉯를 공평하게 평가한 친구는 누구인가요?","options":[{"t":"「두 글 모두 문제 상황에 맞는지, 이유가 타당한지, 의견대로 했을 때 문제가 없는지 똑같이 따졌어.」","correct":true},{"t":"「나는 글 ㉮와 생각이 같으니 글 ㉯만 꼼꼼히 따졌어.」","mis":"K4-2-u1-X34"},{"t":"「글 ㉯는 조사 결과가 있으니 따져 보지 않고 믿었어.」","mis":"K4-2-u1-X34"},{"t":"「이유가 많은 쪽이 이기는 거니까 개수만 셌어.」","mis":"K4-2-u1-X33"}],"explanation":["한쪽만 따지고 다른 쪽은 그냥 믿으면 공평하지 않아요.","두 의견 모두 같은 기준으로 평가해요.","이유의 개수가 아니라 이유의 힘을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_challenge#5','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C35',3,'mc','auto','『국어활동』 8~9쪽에서 도서관을 새롭게 꾸미는 방법에 대한 하윤이와 지민이의 의견을 비교하고 평가할 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X33','K4-2-u1-X30','K4-2-u1-X22']::text[],false,'{"seq":5,"concept":"K4-2-u1-C35","difficulty":3,"kind":"mc","stem":"『국어활동』 8~9쪽에서 도서관을 새롭게 꾸미는 방법에 대한 하윤이와 지민이의 의견을 비교하고 평가할 때 알맞은 것은 무엇인가요?","options":[{"t":"도서관을 새롭게 꾸미는 문제에 맞는지, 이유가 적절한지 두 의견 모두 따진다","correct":true},{"t":"이유가 둘씩이니 두 의견은 똑같이 적절하다","mis":"K4-2-u1-X33"},{"t":"3반 친구의 의견이니 더 적절하다","mis":"K4-2-u1-X30"},{"t":"나는 소파를 좋아하니 하윤이 의견이 적절하다","mis":"K4-2-u1-X22"}],"explanation":["『국어활동』 9쪽 (2)번 표의 두 물음으로 평가해요.","「문제 상황에 적절한 의견인가요?」, 「의견을 뒷받침하는 이유가 적절한가요?」예요.","이유의 개수나 내 취향으로 정하지 않아요."],"asset":{"type":"passage","lines":["[간추림] 기사 제목 — 우리 학교 도서관, 새로운 변화가 필요해요","[하윤] 도서관에 소파를 놓거나 마루를 설치하면 좋겠습니다.","[하윤] 도서관이 편안한 공간이 되면 학생들이 도서관을 좋아하게 될 것입니다.","[하윤] 편안한 자리에서 좋아하는 자세로 책을 읽으면 독서가 더 즐거워질 것입니다.","[지민] 도서관에 책상과 의자를 많이 두면 좋겠습니다.","[지민] 도서관은 공부하는 곳이기 때문입니다.","[지민] 바른 자세로 앉아서 책을 읽어야 독서를 더욱 잘할 수 있기 때문입니다."],"title":"초등학교 신문 — 『국어활동』 8쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_challenge#6','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C34',3,'error','auto','무인 안내기에 대한 친구들의 평가예요. 잘못 평가한 것은 무엇인가요?',ARRAY['K4-2-u1-X32','K4-2-u1-X31']::text[],false,'{"seq":6,"concept":"K4-2-u1-C34","difficulty":3,"kind":"error","stem":"무인 안내기에 대한 친구들의 평가예요. 잘못 평가한 것은 무엇인가요?","options":[{"t":"「글 ㉮의 의견대로 하면 줄을 서지 않아도 되니 아무 문제도 생기지 않아.」","correct":true,"mis_target":"K4-2-u1-X32"},{"t":"「글 ㉯의 이유는 조사 결과가 있어서 믿을 만해.」","mis":"K4-2-u1-X31"},{"t":"「글 ㉮의 의견대로 하면 현금만 있는 사람은 더 불편해질 거야.」","mis":"K4-2-u1-X32"}],"explanation":["의견대로 했을 때 누가 어떤 어려움을 겪을지 살펴야 해요.","글 ㉯가 걱정한 사람들을 떠올리면 문제가 보여요.","좋은 점만 보고 문제가 없다고 하면 잘못 평가한 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_challenge#7','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C37',3,'ox','auto','두 의견을 반씩 섞어 「무인 안내기를 지금의 절반만 더 설치하자」라고 하면 저절로 가장 좋은 의견이 돼요.',ARRAY['K4-2-u1-X35']::text[],false,'{"seq":7,"concept":"K4-2-u1-C37","difficulty":3,"kind":"ox","stem":"두 의견을 반씩 섞어 「무인 안내기를 지금의 절반만 더 설치하자」라고 하면 저절로 가장 좋은 의견이 돼요.","answer":"X","reason_options":[{"t":"섞은 의견도 문제 상황에 맞는지, 이유가 타당한지 같은 기준으로 따져야 하기 때문에","correct":true},{"t":"두 의견의 좋은 점이 저절로 모이기 때문에","mis":"K4-2-u1-X35"}],"mis":"K4-2-u1-X35","explanation":["반씩 섞는다고 문제가 풀리는 것은 아니에요.","절반만 설치해도 이용하기 어려운 사람의 불편은 그대로일 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_challenge#8','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C32',4,'essay','teacher','글 ㉮와 글 ㉯ 가운데 하나를 골라, 문제 상황에 적절한가 · 이유가 타당한가 · 의견대로 했을 때 다른 문제가 생기지 않는가의 세 가지로 평가해 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u1-C32","difficulty":4,"kind":"essay","stem":"글 ㉮와 글 ㉯ 가운데 하나를 골라, 문제 상황에 적절한가 · 이유가 타당한가 · 의견대로 했을 때 다른 문제가 생기지 않는가의 세 가지로 평가해 쓰세요.","answer_guide":{"answer":"예: 글 ㉮를 평가했다. 문제 상황에 적절한가 — 무인 안내기를 어떻게 쓸지에 대한 의견이라 문제와 관련 있다. 이유가 타당한가 — 빠르고 경제적이라는 이유는 믿을 만하지만, 누구나 쉽게 쓴다는 생각은 휠체어를 탄 사람이나 고령층에게는 맞지 않는다. 다른 문제 — 더 많이 설치하면 직원이 줄어 도움이 필요한 사람이 더 불편해질 수 있다.","scoring_points":["세 가지 기준을 모두 썼는가","기준마다 글의 내용을 근거로 들었는가","평가가 공평하고 구체적인가"]},"explanation":["『국어』 72쪽 (2)번 활동이에요.","문제 상황과 관련 있는지, 이유가 믿을 만한지, 의견을 따랐을 때 문제점은 없는지 살펴요.","적절하지 못한 의견을 고르면 더 많은 문제가 생길 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_challenge#9','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C38',4,'essay','teacher','무인 안내기에 대한 자신의 의견을 나타내는 글을 쓰세요. 「……해야 한다.」나 「……(이)라고 생각한다.」 같은 표현을 쓰고, 이유를 두 가지 이상 자세히 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C38","difficulty":4,"kind":"essay","stem":"무인 안내기에 대한 자신의 의견을 나타내는 글을 쓰세요. 「……해야 한다.」나 「……(이)라고 생각한다.」 같은 표현을 쓰고, 이유를 두 가지 이상 자세히 쓰세요.","answer_guide":{"answer":"예: 저는 무인 안내기 곁에 이용을 돕는 사람을 두어야 한다고 생각합니다. 첫째, 사용 방법을 모르는 할머니, 할아버지도 도움을 받아 혼자 주문할 수 있게 되기 때문입니다. 둘째, 휠체어를 탄 사람처럼 화면에 손이 닿지 않는 사람도 불편 없이 이용할 수 있기 때문입니다. 무인 안내기의 편리함을 모든 사람이 누리도록 함께 노력해야 합니다.","scoring_points":["의견을 나타내는 표현으로 의견을 밝혔는가","이유를 두 가지 이상 썼는가","이유가 구체적이고 의견과 이어지는가"]},"explanation":["『국어』 73쪽 (4)번 활동이에요.","서로 다른 글쓴이의 의견을 비교하거나 평가하면서 의견을 정해요.","의견과 이유를 구체적으로 생각해 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L10_challenge#10','kor',4,2,'u1','L10','tb_g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C37',4,'essay','teacher','『국어활동』 9쪽 (3)번처럼 도서관을 새롭게 꾸미는 방법에 대한 자신의 의견과 이유를 쓰고, 하윤이와 지민이의 의견을 어떻게 비교·평가해서 그 의견을 정했는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u1-C37","difficulty":4,"kind":"essay","stem":"『국어활동』 9쪽 (3)번처럼 도서관을 새롭게 꾸미는 방법에 대한 자신의 의견과 이유를 쓰고, 하윤이와 지민이의 의견을 어떻게 비교·평가해서 그 의견을 정했는지 쓰세요.","answer_guide":{"answer":"예: 의견 — 도서관에 혼자 공부하는 공간과 친구들과 함께 편안하게 읽는 공간을 나누어 만들면 좋겠다. 이유 — 모든 친구가 도서관을 즐겁게 이용할 수 있기 때문이다. 정한 과정 — 하윤이의 의견은 독서를 즐겁게 하지만 공부할 자리가 부족해지고, 지민이의 의견은 공부하기 좋지만 편안함이 부족하다고 평가했다. 그래서 두 생각의 좋은 점을 살린 새 의견을 냈다.","scoring_points":["자신의 의견과 이유를 썼는가","두 친구의 의견을 기준에 따라 비교하고 평가했는가","평가한 내용과 내 의견이 이어지는가"]},"explanation":["『국어활동』 9쪽 「더 알아보기」처럼 새로운 의견을 떠올릴 수도 있어요.","새 의견도 같은 기준으로 따져 봐요.","다양한 의견을 비교하면 글을 더 깊이 있게 읽을 수 있어요."],"asset":{"type":"passage","lines":["[간추림] 기사 제목 — 우리 학교 도서관, 새로운 변화가 필요해요","[하윤] 도서관에 소파를 놓거나 마루를 설치하면 좋겠습니다.","[하윤] 도서관이 편안한 공간이 되면 학생들이 도서관을 좋아하게 될 것입니다.","[하윤] 편안한 자리에서 좋아하는 자세로 책을 읽으면 독서가 더 즐거워질 것입니다.","[지민] 도서관에 책상과 의자를 많이 두면 좋겠습니다.","[지민] 도서관은 공부하는 곳이기 때문입니다.","[지민] 바른 자세로 앉아서 책을 읽어야 독서를 더욱 잘할 수 있기 때문입니다."],"title":"초등학교 신문 — 『국어활동』 8쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_basic#1','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C43',1,'mc','auto','『국어』 78쪽 일기에서 「아침에 도서관에 갈려고 놀이터를 지나는데」의 「갈려고」를 바르게 고쳐 쓴 것은 무엇인가요?',ARRAY['K4-2-u1-X39','K4-2-u1-X40']::text[],false,'{"seq":1,"concept":"K4-2-u1-C43","difficulty":1,"kind":"mc","stem":"『국어』 78쪽 일기에서 「아침에 도서관에 갈려고 놀이터를 지나는데」의 「갈려고」를 바르게 고쳐 쓴 것은 무엇인가요?","options":[{"t":"가려고","correct":true},{"t":"갈려고","mis":"K4-2-u1-X39"},{"t":"가을려고","mis":"K4-2-u1-X39"},{"t":"가으려고","mis":"K4-2-u1-X40"}],"explanation":["「가다」에 하려는 뜻의 「-려고」를 붙여요.","「가다」에는 ㄹ 받침이 없어요.","그래서 「가려고」로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_basic#2','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C43',1,'blank','auto','『국어』 78쪽 일기의 「내일은 운동장에서 만나 줄넘기 연습을 같이 (    ) 한다.」에 들어갈 바른 말은 무엇인가요?',ARRAY['K4-2-u1-X39','K4-2-u1-X40']::text[],false,'{"seq":2,"concept":"K4-2-u1-C43","difficulty":1,"kind":"blank","stem":"『국어』 78쪽 일기의 「내일은 운동장에서 만나 줄넘기 연습을 같이 (    ) 한다.」에 들어갈 바른 말은 무엇인가요?","options":[{"t":"하려고","correct":true},{"t":"할려고","mis":"K4-2-u1-X39"},{"t":"하으려고","mis":"K4-2-u1-X40"}],"explanation":["「하다」에 「-려고」를 붙이면 「하려고」예요.","원래 없던 ㄹ을 덧붙이지 않아요.","「할려고」는 자주 틀리는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_basic#3','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C44',1,'match','auto','『국어』 78쪽 2번이에요. 낱말과, 형태가 바뀌지 않는 부분에 「-(으)ㅁ」을 붙여 만든 낱말을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u1-C44","difficulty":1,"kind":"match","stem":"『국어』 78쪽 2번이에요. 낱말과, 형태가 바뀌지 않는 부분에 「-(으)ㅁ」을 붙여 만든 낱말을 알맞게 이으세요.","pairs":[{"l":"기쁘다","r":"기쁨"},{"l":"추다","r":"춤"},{"l":"살다","r":"삶"},{"l":"자다","r":"잠"}],"mis":"K4-2-u1-X41","explanation":["「기쁘-」, 「추-」, 「자-」에 「-ㅁ」을 붙여요.","받침이 ㄹ인 「살-」에 「-ㅁ」이 붙으면 받침이 ㄻ이 돼요.","그래서 「삶」으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_basic#4','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C44',1,'sa','auto','「꾸다」의 형태가 바뀌지 않는 부분에 「-(으)ㅁ」을 붙여 만든 낱말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K4-2-u1-C44","difficulty":1,"kind":"sa","stem":"「꾸다」의 형태가 바뀌지 않는 부분에 「-(으)ㅁ」을 붙여 만든 낱말을 쓰세요.","answer":["꿈"],"explanation":["「꾸다」에서 형태가 바뀌지 않는 부분은 「꾸-」예요.","받침이 없으니 「-ㅁ」을 붙여요.","「꾸-」+「-ㅁ」=「꿈」이에요."],"mis":"K4-2-u1-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_basic#5','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C45',2,'mc','auto','『국어』 79쪽 글씨 쓰기예요. ㄲ 받침을 바르게 쓴 낱말끼리 모은 것은 무엇인가요?',ARRAY['K4-2-u1-X42']::text[],false,'{"seq":5,"concept":"K4-2-u1-C45","difficulty":2,"kind":"mc","stem":"『국어』 79쪽 글씨 쓰기예요. ㄲ 받침을 바르게 쓴 낱말끼리 모은 것은 무엇인가요?","options":[{"t":"깎다 · 떡볶이 · 섞다","correct":true},{"t":"깍다 · 떡복이 · 석다","mis":"K4-2-u1-X42"},{"t":"깎다 · 떡뽁이 · 섟다","mis":"K4-2-u1-X42"},{"t":"깍따 · 떡볶이 · 섞다","mis":"K4-2-u1-X42"}],"explanation":["세 낱말 모두 ㄲ 받침이 있어요.","「깎다」, 「떡볶이」, 「섞다」로 써요.","ㄲ 받침을 ㄱ으로 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_basic#6','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C45',2,'mc','auto','ㅆ 받침을 바르게 쓴 문장은 무엇인가요?',ARRAY['K4-2-u1-X42']::text[],false,'{"seq":6,"concept":"K4-2-u1-C45","difficulty":2,"kind":"mc","stem":"ㅆ 받침을 바르게 쓴 문장은 무엇인가요?","options":[{"t":"어제 할머니 댁에 갔다.","correct":true},{"t":"어제 할머니 댁에 갓다.","mis":"K4-2-u1-X42"},{"t":"어제 할머니 댁에 같다.","mis":"K4-2-u1-X42"},{"t":"어제 할머니 댁에 갖다.","mis":"K4-2-u1-X42"}],"explanation":["「가다」가 지난 일을 나타내면 「갔다」예요.","받침은 ㅆ이에요.","『국어』 79쪽의 「갔다」, 「좋겠다」, 「있다」도 ㅆ 받침이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_basic#7','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C40',2,'mc','auto','『국어』 75쪽 ○○시청 누리집 글이에요. 전재현의 글에 나타난 의견은 무엇인가요?',ARRAY['K4-2-u1-X24','K4-2-u1-X19']::text[],false,'{"seq":7,"concept":"K4-2-u1-C40","difficulty":2,"kind":"mc","stem":"『국어』 75쪽 ○○시청 누리집 글이에요. 전재현의 글에 나타난 의견은 무엇인가요?","options":[{"t":"마을에 오는 관광객을 제한해 달라","correct":true},{"t":"관광객들이 늦은 시간까지 큰 소리로 떠든다","mis":"K4-2-u1-X24"},{"t":"관광객 숙소를 더 지어 달라","mis":"K4-2-u1-X19"},{"t":"저녁 8시까지로 관광 시간을 제한하자","mis":"K4-2-u1-X19"}],"explanation":["먼저 누가 한 말인지 가려요.","전재현은 주민들이 조용하고 깨끗하게 지내도록 관광객을 제한해 달라고 했어요.","늦게까지 떠드는 일은 의견이 아니라 이유예요."],"asset":{"type":"passage","lines":["[전재현의 글] 요즘 우리 한옥 마을이 많은 관광객으로 몸살을 앓고 있습니다.","[전재현의 글] 관광객들이 늦은 시간까지 큰 소리로 떠들고, 집 앞에 쓰레기가 쌓입니다.","[전재현의 글] 주민들이 조용하고 깨끗하게 지내도록 관광객을 제한해 주시면 좋겠습니다.","[윤시완의 댓글] 저는 마을이 관광객들로 더욱 활기찬 것 같아 즐겁습니다.","[윤시완의 댓글] 우리 가족은 관광객을 위한 숙소와 식당을 운영합니다.","[윤시완의 댓글] 관광객을 제한하면 숙소나 가게를 하는 사람들이 경제적으로 어려워집니다.","[김누리의 댓글] 서로 양보해서 저녁 8시까지로 관광 시간을 제한하면 좋겠습니다.","[김누리의 댓글] 주민은 저녁에 쉴 수 있고 숙소나 가게도 운영될 수 있기 때문입니다."],"title":"○○시청 누리집 ‘시민의 소리’ — 『국어』 75쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_basic#8','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C40',2,'mc','auto','윤시완이 댓글에서 관광객을 제한하면 안 된다는 의견을 받쳐 주려고 든 이유는 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X24']::text[],false,'{"seq":8,"concept":"K4-2-u1-C40","difficulty":2,"kind":"mc","stem":"윤시완이 댓글에서 관광객을 제한하면 안 된다는 의견을 받쳐 주려고 든 이유는 무엇인가요?","options":[{"t":"관광객을 제한하면 숙소나 가게를 운영하는 사람들이 경제적으로 어려워진다","correct":true},{"t":"집 앞에 관광객이 버린 쓰레기가 쌓인다","mis":"K4-2-u1-X19"},{"t":"주민들이 저녁에 조용하게 쉴 수 있다","mis":"K4-2-u1-X19"},{"t":"한옥 마을에 사는 4학년이다","mis":"K4-2-u1-X24"}],"explanation":["윤시완은 마을이 활기차서 즐겁다고 했어요.","또 가족이 관광객을 위한 숙소와 식당을 운영한다고 했어요.","쓰레기 이야기는 전재현의 이유예요."],"asset":{"type":"passage","lines":["[전재현의 글] 요즘 우리 한옥 마을이 많은 관광객으로 몸살을 앓고 있습니다.","[전재현의 글] 관광객들이 늦은 시간까지 큰 소리로 떠들고, 집 앞에 쓰레기가 쌓입니다.","[전재현의 글] 주민들이 조용하고 깨끗하게 지내도록 관광객을 제한해 주시면 좋겠습니다.","[윤시완의 댓글] 저는 마을이 관광객들로 더욱 활기찬 것 같아 즐겁습니다.","[윤시완의 댓글] 우리 가족은 관광객을 위한 숙소와 식당을 운영합니다.","[윤시완의 댓글] 관광객을 제한하면 숙소나 가게를 하는 사람들이 경제적으로 어려워집니다.","[김누리의 댓글] 서로 양보해서 저녁 8시까지로 관광 시간을 제한하면 좋겠습니다.","[김누리의 댓글] 주민은 저녁에 쉴 수 있고 숙소나 가게도 운영될 수 있기 때문입니다."],"title":"○○시청 누리집 ‘시민의 소리’ — 『국어』 75쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_basic#9','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C39',2,'mc','auto','『국어』 74쪽 「감상한 작품 소개하기」의 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X37','K4-2-u1-X10']::text[],false,'{"seq":9,"concept":"K4-2-u1-C39","difficulty":2,"kind":"mc","stem":"『국어』 74쪽 「감상한 작품 소개하기」의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"현실 세계와 다른 장면 그리기 → 작품 속 세계와 현실 세계 비교하기 → 친구들에게 작품 소개하기","correct":true},{"t":"작품 소개하기 → 장면 그리기 → 비교하기","mis":"K4-2-u1-X37"},{"t":"줄거리 받아쓰기 → 소개하기 → 끝","mis":"K4-2-u1-X37"},{"t":"비교하기 → 작품에서 틀린 곳 고치기 → 소개하기","mis":"K4-2-u1-X10"}],"explanation":["먼저 재미있게 감상한 만화나 영화에서 현실 세계와 다른 장면을 그려요.","그다음 비슷한 점과 다른 점을 정리해요.","정리한 내용을 바탕으로 작품을 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_basic#10','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C42',3,'mc','auto','김누리의 댓글이 의견을 나누는 댓글로 알맞은 까닭은 무엇인가요?',ARRAY['K4-2-u1-X38']::text[],false,'{"seq":10,"concept":"K4-2-u1-C42","difficulty":3,"kind":"mc","stem":"김누리의 댓글이 의견을 나누는 댓글로 알맞은 까닭은 무엇인가요?","options":[{"t":"의견(저녁 8시까지로 관광 시간 제한)과 이유가 드러나고, 두 사람의 걱정을 함께 살폈기 때문이다","correct":true},{"t":"다른 사람의 의견을 깎아내렸기 때문이다","mis":"K4-2-u1-X38"},{"t":"「저도요」 한마디로 짧게 썼기 때문이다","mis":"K4-2-u1-X38"},{"t":"이유 없이 의견만 크게 외쳤기 때문이다","mis":"K4-2-u1-X38"}],"explanation":["김누리는 「서로 조금씩 양보해서」 시간을 정하자고 했어요.","주민의 쉼과 숙소·가게 운영을 함께 이유로 들었어요.","의견과 이유가 드러나고 존중하는 말투예요."],"asset":{"type":"passage","lines":["[전재현의 글] 요즘 우리 한옥 마을이 많은 관광객으로 몸살을 앓고 있습니다.","[전재현의 글] 관광객들이 늦은 시간까지 큰 소리로 떠들고, 집 앞에 쓰레기가 쌓입니다.","[전재현의 글] 주민들이 조용하고 깨끗하게 지내도록 관광객을 제한해 주시면 좋겠습니다.","[윤시완의 댓글] 저는 마을이 관광객들로 더욱 활기찬 것 같아 즐겁습니다.","[윤시완의 댓글] 우리 가족은 관광객을 위한 숙소와 식당을 운영합니다.","[윤시완의 댓글] 관광객을 제한하면 숙소나 가게를 하는 사람들이 경제적으로 어려워집니다.","[김누리의 댓글] 서로 양보해서 저녁 8시까지로 관광 시간을 제한하면 좋겠습니다.","[김누리의 댓글] 주민은 저녁에 쉴 수 있고 숙소나 가게도 운영될 수 있기 때문입니다."],"title":"○○시청 누리집 ‘시민의 소리’ — 『국어』 75쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_challenge#1','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C41',2,'mc','auto','전재현과 윤시완은 관광객 제한에 대해 의견이 갈렸어요. 두 사람의 의견에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X28','K4-2-u1-X21']::text[],false,'{"seq":1,"concept":"K4-2-u1-C41","difficulty":2,"kind":"mc","stem":"전재현과 윤시완은 관광객 제한에 대해 의견이 갈렸어요. 두 사람의 의견에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"두 사람 모두 한옥 마을의 생활을 아끼지만 걱정하는 사람과 일이 다르다","correct":true},{"t":"한 사람은 마을을 잘 모르고 반대했다","mis":"K4-2-u1-X28"},{"t":"관광객이 버린 쓰레기를 두 사람 모두 반긴다","mis":"K4-2-u1-X28"},{"t":"의견이 반대이니 한 사람은 틀렸다","mis":"K4-2-u1-X21"}],"explanation":["전재현은 조용하고 깨끗한 마을을, 윤시완은 숙소와 가게를 하는 이웃의 생활을 걱정해요.","둘 다 마을에 살며 겪은 일을 이유로 들었어요.","걱정하는 사람이 다를 뿐 한쪽이 잘못 안 것이 아니에요."],"asset":{"type":"passage","lines":["[전재현의 글] 요즘 우리 한옥 마을이 많은 관광객으로 몸살을 앓고 있습니다.","[전재현의 글] 관광객들이 늦은 시간까지 큰 소리로 떠들고, 집 앞에 쓰레기가 쌓입니다.","[전재현의 글] 주민들이 조용하고 깨끗하게 지내도록 관광객을 제한해 주시면 좋겠습니다.","[윤시완의 댓글] 저는 마을이 관광객들로 더욱 활기찬 것 같아 즐겁습니다.","[윤시완의 댓글] 우리 가족은 관광객을 위한 숙소와 식당을 운영합니다.","[윤시완의 댓글] 관광객을 제한하면 숙소나 가게를 하는 사람들이 경제적으로 어려워집니다.","[김누리의 댓글] 서로 양보해서 저녁 8시까지로 관광 시간을 제한하면 좋겠습니다.","[김누리의 댓글] 주민은 저녁에 쉴 수 있고 숙소나 가게도 운영될 수 있기 때문입니다."],"title":"○○시청 누리집 ‘시민의 소리’ — 『국어』 75쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_challenge#2','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C10',2,'mc','auto','「꽃」의 「꽃이 얼굴을 내밀었다」를 친구가 「친구가 손을 내밀었다」로 바꾸어 썼어요. 친구는 무엇을 바탕으로 바꾸어 썼나요?',ARRAY['K4-2-u1-X09','K4-2-u1-X01']::text[],false,'{"seq":2,"concept":"K4-2-u1-C10","difficulty":2,"kind":"mc","stem":"「꽃」의 「꽃이 얼굴을 내밀었다」를 친구가 「친구가 손을 내밀었다」로 바꾸어 썼어요. 친구는 무엇을 바탕으로 바꾸어 썼나요?","options":[{"t":"친구와 화해했던 현실 세계의 자신의 경험","correct":true},{"t":"시에 나온 낱말을 아무거나 바꾼 것","mis":"K4-2-u1-X09"},{"t":"시를 외워 그대로 옮긴 것","mis":"K4-2-u1-X09"},{"t":"꽃에 실제로 얼굴이 있다는 사실","mis":"K4-2-u1-X01"}],"explanation":["우리 반 활동 예시 1은 시를 읽고 자신의 경험을 떠올려 바꾸어 써요.","꽃이 먼저 기다렸듯 친구도 먼저 화해를 기다렸다고 바꾸었어요.","현실의 경험과 견주어 바꾸었기 때문에 뜻이 이어져요."],"asset":{"type":"passage","lines":["친구가 손을 내밀었다","나만 화해하고 싶은 줄 알았는데","[간추림] 친구는 마음이 갈라지는 길목에서 내가 먼저 손 내밀기를 날마다 기다렸다.","내가 더 나중에 다가가서 미안하다."],"title":"친구가 「꽃」을 바꾸어 쓴 시 「친구」 — 우리 반 활동 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_challenge#3','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C39',3,'mc','auto','재미있게 감상한 만화나 영화를 친구들에게 소개할 때 담을 내용으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X37']::text[],false,'{"seq":3,"concept":"K4-2-u1-C39","difficulty":3,"kind":"mc","stem":"재미있게 감상한 만화나 영화를 친구들에게 소개할 때 담을 내용으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"제목, 현실과 비슷한 점과 다른 점, 현실과 다른 장면이 준 재미나 깨달음","correct":true},{"t":"처음부터 끝까지의 줄거리","mis":"K4-2-u1-X37"},{"t":"「재미있었다」 한마디","mis":"K4-2-u1-X37"},{"t":"영화를 본 극장의 표 값","mis":"K4-2-u1-X37"}],"explanation":["소단원 1에서 배운 작품 속 세계와 현실 세계 비교를 넓힌 활동이에요.","언제, 누구와 감상했는지와 인상 깊은 장면을 떠올려요.","줄거리를 옮기거나 한마디로 끝내면 소개가 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_challenge#4','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C30',3,'mc','auto','우리 반 활동 예시 2에서 공익 광고에 나타난 의견과 이유를 짐작하는 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X29','K4-2-u1-X27']::text[],false,'{"seq":4,"concept":"K4-2-u1-C30","difficulty":3,"kind":"mc","stem":"우리 반 활동 예시 2에서 공익 광고에 나타난 의견과 이유를 짐작하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"광고에 담긴 의견 짐작하기 → 해결할 수 있는 문제 상황 생각하기 → 의견과 뒷받침하는 이유 쓰기 → 다른 공익 광고 더 찾아보기","correct":true},{"t":"광고 그림 따라 그리기 → 광고 음악 외우기 → 끝","mis":"K4-2-u1-X29"},{"t":"이유 쓰기 → 광고는 보지 않기 → 의견 지어내기","mis":"K4-2-u1-X27"},{"t":"광고에는 의견이 없으니 넘어가기","mis":"K4-2-u1-X29"}],"explanation":["공익 광고는 시각 자료와 짧은 글로 의견을 전해요.","의견을 짐작하고, 그 의견으로 해결할 문제와 이유를 생각해요.","생활 속 광고에서도 의견과 이유를 찾을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_challenge#5','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C43',3,'ox','auto','「-ㄹ려고」는 언제나 틀린 말이니 「놀려고」도 「노려고」로 고쳐 써야 해요.',ARRAY['K4-2-u1-X40']::text[],false,'{"seq":5,"concept":"K4-2-u1-C43","difficulty":3,"kind":"ox","stem":"「-ㄹ려고」는 언제나 틀린 말이니 「놀려고」도 「노려고」로 고쳐 써야 해요.","answer":"X","reason_options":[{"t":"「놀다」처럼 원래 ㄹ 받침이 있는 말은 ㄹ을 살려 「놀려고」로 쓰기 때문에","correct":true},{"t":"「-려고」 앞에는 ㄹ이 올 수 없기 때문에","mis":"K4-2-u1-X40"}],"mis":"K4-2-u1-X40","explanation":["「가다」, 「하다」처럼 ㄹ 받침이 없는 말에 ㄹ을 덧붙이면 틀려요.","「놀다」, 「만들다」는 원래 ㄹ 받침이 있어요.","그래서 「놀려고」, 「만들려고」는 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_challenge#6','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C44',3,'mc','auto','「살다」에 「-(으)ㅁ」을 붙여 만든 낱말을 바르게 쓴 문장은 무엇인가요?',ARRAY['K4-2-u1-X41']::text[],false,'{"seq":6,"concept":"K4-2-u1-C44","difficulty":3,"kind":"mc","stem":"「살다」에 「-(으)ㅁ」을 붙여 만든 낱말을 바르게 쓴 문장은 무엇인가요?","options":[{"t":"할아버지께서 들려주신 삶의 이야기가 감동적이었다.","correct":true},{"t":"할아버지께서 들려주신 살음의 이야기가 감동적이었다.","mis":"K4-2-u1-X41"},{"t":"할아버지께서 들려주신 삼의 이야기가 감동적이었다.","mis":"K4-2-u1-X41"},{"t":"할아버지께서 들려주신 살미 이야기가 감동적이었다.","mis":"K4-2-u1-X41"}],"explanation":["「살-」의 받침은 ㄹ이에요.","ㄹ 받침인 말에 「-ㅁ」이 붙으면 받침이 ㄻ이 돼요.","그래서 「삶」으로 써요. 「알다」도 「앎」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_challenge#7','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C42',3,'error','auto','○○시청 누리집 글에 단 댓글이에요. 의견을 나누는 댓글로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u1-X38']::text[],false,'{"seq":7,"concept":"K4-2-u1-C42","difficulty":3,"kind":"error","stem":"○○시청 누리집 글에 단 댓글이에요. 의견을 나누는 댓글로 알맞지 않은 것은 무엇인가요?","options":[{"t":"「관광객 싫어요! 다 오지 마세요!」","correct":true,"mis_target":"K4-2-u1-X38"},{"t":"「관광객이 많은 주말에만 쓰레기통을 늘리면 좋겠습니다. 마을도 깨끗해지고 관광객도 올 수 있기 때문입니다.」","mis":"K4-2-u1-X38"},{"t":"「저는 윤시완 님 의견에 찬성합니다. 가게가 문을 닫으면 마을이 활기를 잃기 때문입니다.」","mis":"K4-2-u1-X38"}],"explanation":["댓글에는 자신의 의견과 그 의견을 뒷받침하는 이유를 써요.","이유 없이 외치기만 하면 의견을 나눌 수 없어요.","다른 사람을 존중하는 말투로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_challenge#8','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C39',4,'essay','teacher','재미있게 감상한 만화나 영화 하나를 골라 현실 세계와 다른 장면을 설명하고, 현실과 비슷한 점과 다른 점을 넣어 친구들에게 소개하는 글을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u1-C39","difficulty":4,"kind":"essay","stem":"재미있게 감상한 만화나 영화 하나를 골라 현실 세계와 다른 장면을 설명하고, 현실과 비슷한 점과 다른 점을 넣어 친구들에게 소개하는 글을 쓰세요.","answer_guide":{"answer":"예: 제목 — 「하늘을 나는 자전거」. 장면 — 주인공이 자전거 페달을 힘껏 밟자 자전거가 하늘로 떠올라 구름 사이를 달리는 장면. 비슷한 점 — 자전거를 처음 배울 때 넘어지고 다시 일어나는 모습은 나와 같았다. 다른 점 — 현실의 자전거는 하늘을 날 수 없다. 소개 — 포기하지 않고 연습하면 꿈에 닿을 수 있다는 생각이 들게 하는 작품이라 친구들에게 추천한다.","scoring_points":["작품 제목과 현실 세계와 다른 장면을 썼는가","현실과 비슷한 점과 다른 점을 썼는가","친구들이 보고 싶어지도록 소개했는가"]},"explanation":["『국어』 74쪽 「감상한 작품 소개하기」 활동이에요.","장면 그리기 → 비교하기 → 소개하기 차례로 해요.","줄거리를 늘어놓기보다 비교한 내용을 중심으로 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_challenge#9','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C42',4,'essay','teacher','○○시청 누리집 글과 윤시완의 댓글을 비교한 뒤, 자신의 의견과 그 이유를 댓글로 쓰세요. 두 사람의 걱정 가운데 무엇을 살폈는지도 드러나게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C42","difficulty":4,"kind":"essay","stem":"○○시청 누리집 글과 윤시완의 댓글을 비교한 뒤, 자신의 의견과 그 이유를 댓글로 쓰세요. 두 사람의 걱정 가운데 무엇을 살폈는지도 드러나게 쓰세요.","answer_guide":{"answer":"예: 저는 관광객이 다니는 길을 정하고, 밤 9시 이후에는 골목 출입을 줄이면 좋겠습니다. 전재현 님 말씀처럼 주민들이 밤에 조용히 쉴 수 있고, 윤시완 님 가족처럼 가게를 하는 분들도 낮에는 손님을 맞을 수 있기 때문입니다. 쓰레기는 관광 안내소에서 봉투를 나누어 주면 줄일 수 있을 것입니다.","scoring_points":["자신의 의견과 이유를 썼는가","두 사람의 걱정을 살펴 썼는가","존중하는 말투의 댓글 꼴로 썼는가"]},"explanation":["『국어』 75쪽 「누리집 게시판에 댓글 쓰기」 3번 활동이에요.","글을 쓴 사람과 댓글을 쓴 사람의 의견과 이유를 먼저 비교해요.","그것을 바탕으로 내 의견과 이유를 댓글로 써요."],"asset":{"type":"passage","lines":["[전재현의 글] 요즘 우리 한옥 마을이 많은 관광객으로 몸살을 앓고 있습니다.","[전재현의 글] 관광객들이 늦은 시간까지 큰 소리로 떠들고, 집 앞에 쓰레기가 쌓입니다.","[전재현의 글] 주민들이 조용하고 깨끗하게 지내도록 관광객을 제한해 주시면 좋겠습니다.","[윤시완의 댓글] 저는 마을이 관광객들로 더욱 활기찬 것 같아 즐겁습니다.","[윤시완의 댓글] 우리 가족은 관광객을 위한 숙소와 식당을 운영합니다.","[윤시완의 댓글] 관광객을 제한하면 숙소나 가게를 하는 사람들이 경제적으로 어려워집니다.","[김누리의 댓글] 서로 양보해서 저녁 8시까지로 관광 시간을 제한하면 좋겠습니다.","[김누리의 댓글] 주민은 저녁에 쉴 수 있고 숙소나 가게도 운영될 수 있기 때문입니다."],"title":"○○시청 누리집 ‘시민의 소리’ — 『국어』 75쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_L12_challenge#10','kor',4,2,'u1','L12','tb_g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C10',4,'essay','teacher','「꽃」을 읽고 현실 세계에서 겪은 자신의 경험을 떠올려, 「내가 먼저 ~줄 알았지만」의 짜임을 살려 시를 바꾸어 쓰세요. 무엇을 바탕으로 바꾸었는지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u1-C10","difficulty":4,"kind":"essay","stem":"「꽃」을 읽고 현실 세계에서 겪은 자신의 경험을 떠올려, 「내가 먼저 ~줄 알았지만」의 짜임을 살려 시를 바꾸어 쓰세요. 무엇을 바탕으로 바꾸었는지도 쓰세요.","answer_guide":{"answer":"예: 엄마가 문을 열었다 / 내가 먼저 기다린 줄 알았지만 / 늦은 저녁 길목에서 / 내가 돌아오기를 날마다 기다리고 있었다 / 내가 더 나중에 알아서 미안하다. 바탕 — 학원에서 늦게 돌아온 날, 엄마가 현관 앞에서 기다리고 계셨던 경험을 떠올렸다.","scoring_points":["「내가 먼저 ~줄 알았지만」의 짜임을 살렸는가","현실 세계에서 겪은 경험을 바탕으로 바꾸었는가","바탕이 된 경험을 밝혔는가"]},"explanation":["우리 반 활동 예시 1이에요.","시에서 현실 세계를 어떻게 나타냈는지 살핀 뒤 내 경험으로 바꾸어 써요.","쓴 시와 어울리는 그림을 그려 전시할 수도 있어요."],"asset":{"type":"passage","lines":["꽃이 얼굴을 내밀었다","내가 먼저 본 줄 알았지만","[간추림] 꽃은 봄 길목에서 내가 보아 주기를 날마다 기다리고, 날마다 말을 걸고, 웃고 있었다.","내가 더 나중에 보아서 미안하다."],"title":"「꽃」(정여민) 간추림 — 우리 반 활동 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#1','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C2',1,'ox','auto','『국어』 77쪽 「정리하기」예요. 작품 속 세계와 현실 세계의 모습은 항상 같아요.',ARRAY['K4-2-u1-X01']::text[],false,'{"seq":1,"concept":"K4-2-u1-C2","difficulty":1,"kind":"ox","stem":"『국어』 77쪽 「정리하기」예요. 작품 속 세계와 현실 세계의 모습은 항상 같아요.","answer":"X","reason_options":[{"t":"작품에는 현실과 비슷한 부분도 있고 글쓴이가 꾸며 쓴 부분도 있기 때문에","correct":true},{"t":"작품은 현실을 그대로 옮겨 쓴 것이기 때문에","mis":"K4-2-u1-X01"}],"mis":"K4-2-u1-X01","explanation":["「정리하기」에서 ○ 표를 하지 않는 문장이에요.","「스펀지 교실」도, 「언제나 다정 죽집」도 현실과 다른 부분이 있었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#2','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C1',1,'mc','auto','1단원 「비교하며 읽어요」에서 배운 두 가지를 바르게 고른 것은 무엇인가요?',ARRAY['K4-2-u1-X10','K4-2-u1-X01','K4-2-u1-X20']::text[],false,'{"seq":2,"concept":"K4-2-u1-C1","difficulty":1,"kind":"mc","stem":"1단원 「비교하며 읽어요」에서 배운 두 가지를 바르게 고른 것은 무엇인가요?","options":[{"t":"현실 세계와 비교하며 작품 감상하기 · 다른 의견이 담긴 글을 비교하며 읽기","correct":true},{"t":"작품에서 틀린 곳 찾기 · 긴 글만 골라 읽기","mis":"K4-2-u1-X10"},{"t":"작품 속 일을 사실로 믿기 · 한 가지 의견만 따르기","mis":"K4-2-u1-X01"},{"t":"작품 외우기 · 의견을 따지지 않고 읽기","mis":"K4-2-u1-X20"}],"explanation":["소단원 1은 작품 속 세계와 현실 세계를 비교하며 감상해요.","소단원 2는 다른 의견이 담긴 글을 비교하며 읽어요.","둘 다 나란히 놓고 견주는 공부예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#3','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C7',1,'mc','auto','「스펀지 교실」에 나타난 모습 가운데 현실과 다른 점은 무엇인가요?',ARRAY['K4-2-u1-X44']::text[],false,'{"seq":3,"concept":"K4-2-u1-C7","difficulty":1,"kind":"mc","stem":"「스펀지 교실」에 나타난 모습 가운데 현실과 다른 점은 무엇인가요?","options":[{"t":"복도를 뛰어다녀도 다칠 일이 없다","correct":true},{"t":"교실에서 친구들과 함께 공부한다","mis":"K4-2-u1-X44"},{"t":"교실에서 속상한 일이 생기기도 한다","mis":"K4-2-u1-X44"},{"t":"복도를 뛰어다니기도 한다","mis":"K4-2-u1-X44"}],"explanation":["현실의 교실은 딱딱한 콘크리트나 나무로 되어 있어요.","복도를 뛰다 넘어지면 다칠 수 있어요.","함께 공부하거나 속상한 일이 생기는 것은 현실과 같아요."],"asset":{"type":"passage","lines":["혹시 스펀지 교실에서 공부해 본 적 있니?","[간추림] 스펀지 창문 밖 나무들은 통통하게 웃고, 새들은 스펀지 날개를 매단 듯 여유롭다.","[간추림] 새들 보금자리처럼 우리 교실도 폭신폭신하다.","우당탕탕 복도를 뛰어다녀도","딱딱한 바닥에 무릎 다칠 일 없는"],"title":"「스펀지 교실」(권기덕) 앞부분 — 『국어』 38쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#4','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C26',1,'sa','auto','어떤 문제에 대해 글쓴이가 가진 생각을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K4-2-u1-C26","difficulty":1,"kind":"sa","stem":"어떤 문제에 대해 글쓴이가 가진 생각을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["의견"],"explanation":["의견은 어떤 문제에 대한 생각이에요.","이유는 그렇게 생각한 까닭이에요.","사실은 실제로 있었던 일이에요."],"mis":"K4-2-u1-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#5','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C43',1,'mc','auto','무엇을 할 뜻을 나타낼 때 「가다」에 「-려고」를 붙여 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u1-X39','K4-2-u1-X40']::text[],false,'{"seq":5,"concept":"K4-2-u1-C43","difficulty":1,"kind":"mc","stem":"무엇을 할 뜻을 나타낼 때 「가다」에 「-려고」를 붙여 바르게 쓴 것은 무엇인가요?","options":[{"t":"가려고","correct":true},{"t":"갈려고","mis":"K4-2-u1-X39"},{"t":"가을려고","mis":"K4-2-u1-X39"},{"t":"갈으려고","mis":"K4-2-u1-X40"}],"explanation":["『국어』 78쪽 1번에서 배웠어요.","「가다」+「-려고」는 「가려고」예요.","원래 없던 ㄹ을 덧붙이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#6','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C44',1,'mc','auto','「기쁘다」의 형태가 바뀌지 않는 부분에 「-(으)ㅁ」을 붙인 낱말은 무엇인가요?',ARRAY['K4-2-u1-X41']::text[],false,'{"seq":6,"concept":"K4-2-u1-C44","difficulty":1,"kind":"mc","stem":"「기쁘다」의 형태가 바뀌지 않는 부분에 「-(으)ㅁ」을 붙인 낱말은 무엇인가요?","options":[{"t":"기쁨","correct":true},{"t":"기쁘음","mis":"K4-2-u1-X41"},{"t":"기쁜","mis":"K4-2-u1-X41"},{"t":"기뿜","mis":"K4-2-u1-X41"}],"explanation":["형태가 바뀌지 않는 부분은 「기쁘-」예요.","받침이 없으니 「-ㅁ」을 붙여요.","「기쁨」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#7','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C45',1,'blank','auto','「연필을 칼로 (    ).」의 빈칸에 들어갈 바른 말은 무엇인가요?',ARRAY['K4-2-u1-X42']::text[],false,'{"seq":7,"concept":"K4-2-u1-C45","difficulty":1,"kind":"blank","stem":"「연필을 칼로 (    ).」의 빈칸에 들어갈 바른 말은 무엇인가요?","options":[{"t":"깎다","correct":true},{"t":"깍다","mis":"K4-2-u1-X42"},{"t":"깍따","mis":"K4-2-u1-X42"},{"t":"깟다","mis":"K4-2-u1-X42"}],"explanation":["「깎다」는 ㄲ 받침이에요.","소리가 비슷해도 ㄱ으로 쓰지 않아요.","『국어』 79쪽 글씨 쓰기 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#8','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C13',1,'mc','auto','「막연했던 추측이 사실이었던 거예요!」에서 「막연했던」의 뜻은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":8,"concept":"K4-2-u1-C13","difficulty":1,"kind":"mc","stem":"「막연했던 추측이 사실이었던 거예요!」에서 「막연했던」의 뜻은 무엇인가요?","options":[{"t":"뚜렷하지 못하고 어렴풋했던","correct":true},{"t":"느껴서 알았던","mis":"K4-2-u1-X12"},{"t":"물건이나 권리를 건네받았던","mis":"K4-2-u1-X12"},{"t":"얼굴을 들고 대하기가 부끄러웠던","mis":"K4-2-u1-X12"}],"explanation":["『국어』 58쪽 「낱말 알기」예요.","팥냥이 덕분에 움직인다는 짐작이 어렴풋했는데 사실로 밝혀졌어요.","「막연하다」는 뚜렷하지 못하고 어렴풋하다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#9','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C6',2,'mc','auto','작품 속 세계와 현실 세계를 비교하려고 할 때 먼저 하면 좋은 일은 무엇인가요?',ARRAY['K4-2-u1-X49','K4-2-u1-X10','K4-2-u1-X09']::text[],false,'{"seq":9,"concept":"K4-2-u1-C6","difficulty":2,"kind":"mc","stem":"작품 속 세계와 현실 세계를 비교하려고 할 때 먼저 하면 좋은 일은 무엇인가요?","options":[{"t":"작품을 읽고 자신이 경험한 일을 떠올린다","correct":true},{"t":"글쓴이의 의견과 이유가 알맞은지 따진다","mis":"K4-2-u1-X49"},{"t":"작품에서 틀린 곳을 찾는다","mis":"K4-2-u1-X10"},{"t":"작품 속 낱말을 외운다","mis":"K4-2-u1-X09"}],"explanation":["『국어활동』 6쪽 2번의 첫째 방법이에요.","경험을 떠올려 작품에서 일어난 일과 비교해요.","의견과 이유 따지기는 의견이 담긴 글을 읽을 때 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#10','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C3',2,'mc','auto','「스펀지 교실」에서 교실을 스펀지로 꾸며 쓴 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X01','K4-2-u1-X10','K4-2-u1-X02']::text[],false,'{"seq":10,"concept":"K4-2-u1-C3","difficulty":2,"kind":"mc","stem":"「스펀지 교실」에서 교실을 스펀지로 꾸며 쓴 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"다치지 않고 마음 편한 교실을 바라는 마음을 또렷하게 보여 주려고","correct":true},{"t":"스펀지 교실이 실제로 있다는 것을 알려 주려고","mis":"K4-2-u1-X01"},{"t":"우리 교실이 틀렸다고 고쳐 주려고","mis":"K4-2-u1-X10"},{"t":"시를 길게 늘이려고","mis":"K4-2-u1-X02"}],"explanation":["꾸며 쓴 부분은 거짓말이 아니에요.","말하는 이가 바라는 교실의 모습을 또렷하게 보여 줘요.","그래서 읽는 사람도 우리 교실을 되돌아보게 돼요."],"asset":{"type":"passage","lines":["속상한 일 있을 땐","그냥 스펀지 벽에 점프만 하면 돼","[간추림] 서로의 눈빛만으로 웃음이 터지는 마법 같은 교실이다.","스펀지 책상의 둥근 모서리처럼","우리도 점점 둥글어지고 있어"],"title":"「스펀지 교실」(권기덕) 뒷부분 — 『국어』 39쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#11','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C12',2,'blank','auto','「언제나 다정 죽집」에서 할머니는 팥 삶은 물을 맑은 윗물과 무거운 앙금으로 나눈 뒤, 쌀을 익힐 때 (    )만 떠서 썼어요. 빈칸에 들어갈 말은 무엇인가요?',ARRAY['K4-2-u1-X11']::text[],false,'{"seq":11,"concept":"K4-2-u1-C12","difficulty":2,"kind":"blank","stem":"「언제나 다정 죽집」에서 할머니는 팥 삶은 물을 맑은 윗물과 무거운 앙금으로 나눈 뒤, 쌀을 익힐 때 (    )만 떠서 썼어요. 빈칸에 들어갈 말은 무엇인가요?","options":[{"t":"맑은 윗물","correct":true},{"t":"팥을 처음 끓인 첫 물","mis":"K4-2-u1-X11"},{"t":"설탕을 탄 물","mis":"K4-2-u1-X11"},{"t":"뻑뻑한 앙금","mis":"K4-2-u1-X11"}],"explanation":["할머니는 팥을 끓인 첫 물을 버렸어요.","뻑뻑한 앙금으로는 쌀을 부드럽게 익히기 힘들다고 했어요.","그래서 맑은 윗물만 떠서 썼어요."],"asset":{"type":"passage","lines":["[간추림] 마지막 장삿날 아침, 할머니는 동지 팥죽을 준비했다.","[간추림] 첫 물을 버리고, 앙금을 가라앉힌 맑은 윗물만 떠서 쌀을 익혔다.","[간추림] 설탕도 소금도 넣지 않은 소박한 팥죽이었다.","“하지만 몸을 추스르자고 먹는 죽에다가","차마 그런 것들을 들이부을 수야 없지.”"],"title":"「언제나 다정 죽집」 가운데 ① — 『국어』 47~50쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#12','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C14',2,'mc','auto','「언제나 다정 죽집」의 부엌 친구들이 맡은 역할을 열심히 하며 빵을 만드는 행동에서 짐작할 수 있는 성격은 무엇인가요?',ARRAY['K4-2-u1-X13']::text[],false,'{"seq":12,"concept":"K4-2-u1-C14","difficulty":2,"kind":"mc","stem":"「언제나 다정 죽집」의 부엌 친구들이 맡은 역할을 열심히 하며 빵을 만드는 행동에서 짐작할 수 있는 성격은 무엇인가요?","options":[{"t":"성실하고 부지런하다","correct":true},{"t":"게으르다","mis":"K4-2-u1-X13"},{"t":"샘이 많다","mis":"K4-2-u1-X13"},{"t":"겁이 많다","mis":"K4-2-u1-X13"}],"explanation":["『국어』 59쪽 (2)번 표의 부엌 친구들 칸이에요.","팥을 끓이고, 식빵을 밀고, 발자국을 새기며 저마다 열심히 일했어요.","행동을 근거로 성격을 짐작해요."],"asset":{"type":"passage","lines":["[간추림] 할머니와 할아버지는 오랫동안 팥죽 가게 ‘다정 죽집’을 꾸려 왔다.","[간추림] 할아버지가 돌아가신 뒤, 죽집은 문을 닫을 위기에 놓였다.","[간추림] 고양이 팥냥이가 꾹꾹이를 해 주자 부엌 친구들이 말하고 움직이게 되었다.","“아무튼 오늘 최고의 고양이빵을 만들어야 해.","이 가게의 운명이 너희 손에 달려 있으니까.”","[간추림] 가마솥인 ‘나’는 팥을 끓이고, 홍두깨·인두·주걱·사발도 저마다 일을 맡았다.","[간추림] 부엌 친구들은 고양이빵 다섯 개를 만들어 상자에 담아 몰래 숨겨 두었다."],"title":"「언제나 다정 죽집」(우신영 글) 앞부분 — 『국어』 44~47쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#13','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C23',2,'mc','auto','다른 의견이 담긴 글을 비교하며 읽으면 좋은 점이 아닌 것은 무엇인가요?',ARRAY['K4-2-u1-X20']::text[],false,'{"seq":13,"concept":"K4-2-u1-C23","difficulty":2,"kind":"mc","stem":"다른 의견이 담긴 글을 비교하며 읽으면 좋은 점이 아닌 것은 무엇인가요?","options":[{"t":"글쓴이가 누구인지 외울 수 있다","correct":true},{"t":"같은 문제에 대한 다양한 생각을 알 수 있다","mis":"K4-2-u1-X20"},{"t":"문제에 대한 내 의견을 생각하는 데 도움이 된다","mis":"K4-2-u1-X20"},{"t":"더 적절한 의견이 무엇인지 평가할 수 있다","mis":"K4-2-u1-X20"}],"explanation":["『국어』 63쪽 2번의 좋은 점은 세 가지예요.","글쓴이를 외우는 것은 비교하며 읽는 까닭이 아니에요.","다양한 생각, 내 의견, 더 적절한 의견을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#14','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C27',2,'mc','auto','제목 「틀린 것이 아니라 새로운 아름다움으로 봐 주세요」에서 짐작할 수 있는 의견은 무엇인가요?',ARRAY['K4-2-u1-X25','K4-2-u1-X19','K4-2-u1-X26']::text[],false,'{"seq":14,"concept":"K4-2-u1-C27","difficulty":2,"kind":"mc","stem":"제목 「틀린 것이 아니라 새로운 아름다움으로 봐 주세요」에서 짐작할 수 있는 의견은 무엇인가요?","options":[{"t":"변형 한복도 새로운 아름다움으로 인정하자","correct":true},{"t":"변형 한복은 틀렸다","mis":"K4-2-u1-X25"},{"t":"전통 한복만 입자","mis":"K4-2-u1-X19"},{"t":"제목은 보지 않고 넘어가자","mis":"K4-2-u1-X26"}],"explanation":["글 ㉯의 제목이에요.","「틀린 것이 아니라」라고 했으니 변형 한복을 인정해 달라는 뜻이에요.","제목 속 낱말 하나만 떼어 읽지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#15','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C32',2,'mc','auto','글쓴이의 의견을 평가할 때 살펴볼 것이 아닌 것은 무엇인가요?',ARRAY['K4-2-u1-X47','K4-2-u1-X31','K4-2-u1-X32']::text[],false,'{"seq":15,"concept":"K4-2-u1-C32","difficulty":2,"kind":"mc","stem":"글쓴이의 의견을 평가할 때 살펴볼 것이 아닌 것은 무엇인가요?","options":[{"t":"글쓴이가 유명한 사람인가","correct":true},{"t":"문제 상황에 적절한 의견인가","mis":"K4-2-u1-X47"},{"t":"의견을 뒷받침하는 이유가 타당한가","mis":"K4-2-u1-X31"},{"t":"의견대로 했을 때 다른 문제가 생기지 않는가","mis":"K4-2-u1-X32"}],"explanation":["의견을 평가하는 기준은 세 가지예요.","문제 상황에 적절한지, 이유가 타당한지, 다른 문제가 생기지 않는지예요.","글쓴이가 누구인지는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#16','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C30',2,'mc','auto','『국어』 77쪽 「생활 속으로」에서 이 단원에서 배운 것을 생활에서 실천하는 다짐으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X29','K4-2-u1-X01','K4-2-u1-X20']::text[],false,'{"seq":16,"concept":"K4-2-u1-C30","difficulty":2,"kind":"mc","stem":"『국어』 77쪽 「생활 속으로」에서 이 단원에서 배운 것을 생활에서 실천하는 다짐으로 알맞은 것은 무엇인가요?","options":[{"t":"이야기 속 문제 상황에 대해 친구들과 의견을 나누어 볼 거야.","correct":true},{"t":"의견은 국어 시간 글에서만 찾을 거야.","mis":"K4-2-u1-X29"},{"t":"작품 속 일은 모두 사실로 믿을 거야.","mis":"K4-2-u1-X01"},{"t":"나와 다른 의견은 읽지 않을 거야.","mis":"K4-2-u1-X20"}],"explanation":["「생활 속으로」의 예시에는 세 가지가 있어요.","작품 속 세계와 현실 세계를 비교하며 감상하기, 의견을 비교하며 읽기도 있어요.","배운 것을 생활 속 작품과 글에도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#17','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C7',3,'error','auto','평가 글 「황금 알을 낳는 거위」를 읽고 친구들이 이야기와 현실을 견주었어요. 잘못 견준 친구는 누구인가요?',ARRAY['K4-2-u1-X44']::text[],false,'{"seq":17,"concept":"K4-2-u1-C7","difficulty":3,"kind":"error","stem":"평가 글 「황금 알을 낳는 거위」를 읽고 친구들이 이야기와 현실을 견주었어요. 잘못 견준 친구는 누구인가요?","options":[{"t":"친구 다 — 「거위가 알을 낳는 것은 현실과 다르다.」","correct":true,"mis_target":"K4-2-u1-X44"},{"t":"친구 가 — 「거위가 황금 알을 낳는 것은 현실과 다르다.」","mis":"K4-2-u1-X44"},{"t":"친구 나 — 「욕심을 부리다 가진 것을 잃는 것은 현실과 비슷하다.」","mis":"K4-2-u1-X44"}],"explanation":["거위가 알을 낳는 것은 현실에서도 흔한 일이에요.","현실과 다른 것은 그 알이 황금이라는 점이에요.","현실의 모습을 바르게 알아야 비교할 수 있어요."],"asset":{"type":"passage","lines":["[간추림] 옛날 어느 마을에 가난한 농부가 시장에서 거위 한 마리를 샀다.","[간추림] 거위는 아침마다 번쩍이는 황금 알을 한 개씩 낳았다.","[간추림] 농부는 황금 알을 팔아 부자가 되고 넓은 집도 샀지만, 점점 욕심이 생겼다.","[간추림] “거위 뱃속에 황금 알이 가득할 거야!” 농부는 거위의 배를 갈랐다.","[간추림] 뱃속에는 황금 알이 하나도 없었고, 농부는 거위도 잃고 다시 가난해졌다."],"title":"평가 글 「황금 알을 낳는 거위」(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#18','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C18',3,'mc','auto','「황금 알을 낳는 거위」에서 글쓴이가 이야기를 통해 전하고자 하는 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X16','K4-2-u1-X17','K4-2-u1-X46']::text[],false,'{"seq":18,"concept":"K4-2-u1-C18","difficulty":3,"kind":"mc","stem":"「황금 알을 낳는 거위」에서 글쓴이가 이야기를 통해 전하고자 하는 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"지나친 욕심을 부리면 가진 것까지 잃을 수 있다","correct":true},{"t":"거위를 기르면 부자가 될 수 있다","mis":"K4-2-u1-X16"},{"t":"거위의 배를 가르면 황금 알을 찾을 수 있다","mis":"K4-2-u1-X17"},{"t":"이야기에는 현실과 다른 점이 있다","mis":"K4-2-u1-X46"}],"explanation":["농부는 욕심 때문에 거위와 황금 알을 모두 잃었어요.","꾸민 장치(황금 알)를 그대로 믿는 생각은 주제가 아니에요.","다른 점을 찾은 데서 멈추지 않고 그 까닭을 생각해요."],"asset":{"type":"passage","lines":["[간추림] 옛날 어느 마을에 가난한 농부가 시장에서 거위 한 마리를 샀다.","[간추림] 거위는 아침마다 번쩍이는 황금 알을 한 개씩 낳았다.","[간추림] 농부는 황금 알을 팔아 부자가 되고 넓은 집도 샀지만, 점점 욕심이 생겼다.","[간추림] “거위 뱃속에 황금 알이 가득할 거야!” 농부는 거위의 배를 갈랐다.","[간추림] 뱃속에는 황금 알이 하나도 없었고, 농부는 거위도 잃고 다시 가난해졌다."],"title":"평가 글 「황금 알을 낳는 거위」(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#19','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C34',3,'mc','auto','글 ㉯의 글쓴이가 글 ㉮의 의견대로 무인 안내기를 늘렸을 때 걱정한 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X32','K4-2-u1-X19']::text[],false,'{"seq":19,"concept":"K4-2-u1-C34","difficulty":3,"kind":"mc","stem":"글 ㉯의 글쓴이가 글 ㉮의 의견대로 무인 안내기를 늘렸을 때 걱정한 일로 알맞은 것은 무엇인가요?","options":[{"t":"신체 조건이 맞지 않거나 현금만 있는 사람이 무인 안내기를 쓰기 더 어려워진다","correct":true},{"t":"주문 시간이 더 짧아진다","mis":"K4-2-u1-X32"},{"t":"직원이 더 많이 필요해진다","mis":"K4-2-u1-X32"},{"t":"여러 나라 말로 안내하게 된다","mis":"K4-2-u1-X19"}],"explanation":["글 ㉯는 무인 안내기가 불편한 사람들을 들었어요.","그 사람들이 글 ㉮의 의견대로 했을 때 생길 문제와 이어져요.","반대쪽 글이 걱정한 일이 평가의 실마리예요."],"asset":{"type":"passage","lines":["[간추림] 무인 안내기의 장점 뒤에는 여러 가지 단점이 있다.","첫째, 신체 조건이 맞지 않는 사람은 무인 안내기를 이용하기 어렵습니다.","[간추림] 휠체어를 탄 사람·키가 작은 사람은 쓰기 불편하고, 음성 안내가 없으면 시각 장애인은 못 쓴다.","둘째, 사용 방법이 익숙하지 않은 사람에게 무인 안내기는 전혀 편리하지 않습니다.","[간추림] 서울AI(에이아이)재단 2021년 조사 — 고령층이 못 쓰는 가장 큰 까닭은 사용 방법을 몰라서.","셋째, 현금만 있는 사람은 무인 안내기를 이용하기 어려운 경우가 많습니다.","[간추림] 그러므로 무작정 더 설치하기보다 이용하기 어려운 사람들의 불편을 줄일 방법을 고민해야 한다."],"title":"「무인 안내기, 누군가에게는 큰 불편」(글 ㉯) — 『국어』 70쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#20','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C35',3,'mc','auto','『국어활동』 8쪽에서 하윤이가 의견을 받쳐 주려고 든 이유로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X24']::text[],false,'{"seq":20,"concept":"K4-2-u1-C35","difficulty":3,"kind":"mc","stem":"『국어활동』 8쪽에서 하윤이가 의견을 받쳐 주려고 든 이유로 알맞은 것은 무엇인가요?","options":[{"t":"도서관이 편안해지면 학생들이 도서관을 좋아하게 되고, 좋아하는 자세로 읽으면 독서가 즐거워진다","correct":true},{"t":"도서관은 공부하는 곳이다","mis":"K4-2-u1-X19"},{"t":"바른 자세로 앉아야 독서를 잘한다","mis":"K4-2-u1-X19"},{"t":"하윤이는 4학년 1반 학생이다","mis":"K4-2-u1-X24"}],"explanation":["하윤이의 의견은 소파나 마루를 두자는 것이에요.","이유는 편안함과 즐거운 독서예요.","공부하는 곳, 바른 자세는 지민이의 이유예요."],"asset":{"type":"passage","lines":["[간추림] 기사 제목 — 우리 학교 도서관, 새로운 변화가 필요해요","[하윤] 도서관에 소파를 놓거나 마루를 설치하면 좋겠습니다.","[하윤] 도서관이 편안한 공간이 되면 학생들이 도서관을 좋아하게 될 것입니다.","[하윤] 편안한 자리에서 좋아하는 자세로 책을 읽으면 독서가 더 즐거워질 것입니다.","[지민] 도서관에 책상과 의자를 많이 두면 좋겠습니다.","[지민] 도서관은 공부하는 곳이기 때문입니다.","[지민] 바른 자세로 앉아서 책을 읽어야 독서를 더욱 잘할 수 있기 때문입니다."],"title":"초등학교 신문 — 『국어활동』 8쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#21','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C40',3,'match','auto','○○시청 누리집 글과 댓글을 쓴 사람과 그 사람의 의견을 알맞게 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K4-2-u1-C40","difficulty":3,"kind":"match","stem":"○○시청 누리집 글과 댓글을 쓴 사람과 그 사람의 의견을 알맞게 이으세요.","pairs":[{"l":"전재현","r":"마을에 오는 관광객을 제한해 달라"},{"l":"윤시완","r":"관광객을 제한하면 안 된다"},{"l":"김누리","r":"저녁 8시까지로 관광 시간을 제한하자"}],"mis":"K4-2-u1-X19","explanation":["먼저 누가 한 말인지 가려요.","게시글과 댓글에서 각각 의견을 찾아요.","쓰레기, 숙소 이야기는 의견이 아니라 이유예요."],"asset":{"type":"passage","lines":["[전재현의 글] 요즘 우리 한옥 마을이 많은 관광객으로 몸살을 앓고 있습니다.","[전재현의 글] 관광객들이 늦은 시간까지 큰 소리로 떠들고, 집 앞에 쓰레기가 쌓입니다.","[전재현의 글] 주민들이 조용하고 깨끗하게 지내도록 관광객을 제한해 주시면 좋겠습니다.","[윤시완의 댓글] 저는 마을이 관광객들로 더욱 활기찬 것 같아 즐겁습니다.","[윤시완의 댓글] 우리 가족은 관광객을 위한 숙소와 식당을 운영합니다.","[윤시완의 댓글] 관광객을 제한하면 숙소나 가게를 하는 사람들이 경제적으로 어려워집니다.","[김누리의 댓글] 서로 양보해서 저녁 8시까지로 관광 시간을 제한하면 좋겠습니다.","[김누리의 댓글] 주민은 저녁에 쉴 수 있고 숙소나 가게도 운영될 수 있기 때문입니다."],"title":"○○시청 누리집 ‘시민의 소리’ — 『국어』 75쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#22','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C28',3,'blank','auto','글 ㉮ 「편리한 무인 안내기」의 끝부분 「(    ) 우리는 편리함의 혜택이 가져다주는 변화를 받아들이고 … 활용해야 합니다.」에서 글쓴이의 의견을 이끄는 빈칸의 말은 무엇인가요?',ARRAY['K4-2-u1-X27']::text[],false,'{"seq":22,"concept":"K4-2-u1-C28","difficulty":3,"kind":"blank","stem":"글 ㉮ 「편리한 무인 안내기」의 끝부분 「(    ) 우리는 편리함의 혜택이 가져다주는 변화를 받아들이고 … 활용해야 합니다.」에서 글쓴이의 의견을 이끄는 빈칸의 말은 무엇인가요?","options":[{"t":"그러므로","correct":true},{"t":"첫째,","mis":"K4-2-u1-X27"},{"t":"예를 들어","mis":"K4-2-u1-X27"},{"t":"또","mis":"K4-2-u1-X27"}],"explanation":["의견은 대개 끝부분에서 「그러므로 ~해야 합니다」로 드러나요.","「첫째」, 「둘째」, 「셋째」 뒤에는 이유가 나와요.","제목으로 짐작하고 끝부분에서 의견을 확인해요."],"asset":{"type":"passage","lines":["[간추림] 직원 도움 없이 혼자 주문이나 결제를 하는 무인 안내기가 여러 곳에서 쓰인다.","첫째, 무인 안내기를 이용하면 빠르고 정확하게 일을 처리할 수 있습니다.","[간추림] 줄 서지 않고 자리에서 곧바로 주문하고, 사진을 보고 골라 실수가 준다.","둘째, 무인 안내기를 이용하는 것이 더 경제적입니다.","[간추림] 일을 처리해 주는 사람이 덜 필요해 직원에게 주는 비용을 줄일 수 있다.","셋째, 우리말에 서툰 사람들도 무인 안내기를 쉽게 이용할 수 있습니다.","[간추림] 그러므로 더 많은 곳에서 다양한 무인 안내기를 설치하여 활용해야 한다."],"title":"「편리한 무인 안내기」(글 ㉮) — 『국어』 69쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#23','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C18',4,'essay','teacher','「황금 알을 낳는 거위」에 나타난 모습과 현실의 모습을 비교해 비슷한 점과 다른 점을 하나씩 쓰고, 글쓴이가 이야기를 통해 전하고자 하는 생각을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u1-C18","difficulty":4,"kind":"essay","stem":"「황금 알을 낳는 거위」에 나타난 모습과 현실의 모습을 비교해 비슷한 점과 다른 점을 하나씩 쓰고, 글쓴이가 이야기를 통해 전하고자 하는 생각을 쓰세요.","answer_guide":{"answer":"예: 비슷한 점 — 시장에서 거위 같은 가축을 사고, 욕심을 부리다가 손해를 보는 사람이 있다. 다른 점 — 이야기의 거위는 황금 알을 낳지만, 현실의 거위는 황금 알을 낳지 못한다. 전하려는 생각 — 가진 것에 만족하지 못하고 지나친 욕심을 부리면 가진 것까지 모두 잃을 수 있다.","scoring_points":["같은 대상끼리 견주어 비슷한 점을 썼는가","같은 대상끼리 견주어 다른 점을 썼는가","비교를 바탕으로 글쓴이가 전하려는 생각을 썼는가"]},"explanation":["평가 자료 1의 2번 활동이에요.","경험을 바탕으로 사실과 허구를 비교해요.","비교한 결과에서 멈추지 않고 글쓴이의 생각까지 정리해요."],"asset":{"type":"passage","lines":["[간추림] 옛날 어느 마을에 가난한 농부가 시장에서 거위 한 마리를 샀다.","[간추림] 거위는 아침마다 번쩍이는 황금 알을 한 개씩 낳았다.","[간추림] 농부는 황금 알을 팔아 부자가 되고 넓은 집도 샀지만, 점점 욕심이 생겼다.","[간추림] “거위 뱃속에 황금 알이 가득할 거야!” 농부는 거위의 배를 갈랐다.","[간추림] 뱃속에는 황금 알이 하나도 없었고, 농부는 거위도 잃고 다시 가난해졌다."],"title":"평가 글 「황금 알을 낳는 거위」(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#24','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C26',4,'essay','teacher','우리 반에서 함께 해결해야 할 문제 상황을 하나 쓰고, 그 문제에 대한 자신의 의견과 그 이유를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u1-C26","difficulty":4,"kind":"essay","stem":"우리 반에서 함께 해결해야 할 문제 상황을 하나 쓰고, 그 문제에 대한 자신의 의견과 그 이유를 쓰세요.","answer_guide":{"answer":"예: 문제 상황 — 쉬는 시간에 교실 뒤에서 공놀이를 하다가 친구들이 부딪히는 일이 잦다. 내 의견 — 교실에서는 공놀이 대신 보드게임이나 종이접기를 하자. 이유 — 교실은 좁고 책상 모서리가 있어 다치기 쉽기 때문이다. 공놀이는 점심시간에 운동장에서 하면 된다.","scoring_points":["우리 반의 문제 상황을 구체적으로 썼는가","문제 상황에 맞는 의견을 썼는가","의견을 받쳐 주는 이유를 썼는가"]},"explanation":["평가 자료 2의 1·2번 활동이에요.","문제 상황을 해결할 수 있는 적절한 의견을 찾아요.","의견과 이유가 잘 드러나게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_a#25','kor',4,2,'u1','','tb_g4_2_kor_u1_review_a','unit_review','K4-2-u1-C38',4,'essay','teacher','친구가 「저는 무인 안내기 설치를 줄여야 한다고 생각합니다. 왜냐하면 몇몇 사람이 불편을 겪는다면 그 불편함을 없애는 방법을 찾는 것이 더 중요하기 때문입니다.」라고 썼어요. 의견과 이유가 적절한지 평가하는 말을 쓰고, 내 의견이 다르다면 존중하며 덧붙일 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u1-C38","difficulty":4,"kind":"essay","stem":"친구가 「저는 무인 안내기 설치를 줄여야 한다고 생각합니다. 왜냐하면 몇몇 사람이 불편을 겪는다면 그 불편함을 없애는 방법을 찾는 것이 더 중요하기 때문입니다.」라고 썼어요. 의견과 이유가 적절한지 평가하는 말을 쓰고, 내 의견이 다르다면 존중하며 덧붙일 말을 쓰세요.","answer_guide":{"answer":"예: 평가 — 무인 안내기를 이용하기 어려운 사람이 있다는 문제와 관련 있는 의견이고, 불편을 겪는 사람을 먼저 생각한 이유도 타당하다. 다만 설치를 줄이면 빠르게 주문하던 사람들이 불편해질 수 있다. 덧붙일 말 — 네 생각처럼 불편한 사람을 먼저 생각하는 것이 중요해. 나는 설치를 줄이기보다 음성 안내와 도우미를 함께 두는 방법도 좋다고 생각해.","scoring_points":["문제 상황에 적절한지 평가했는가","이유가 타당한지, 다른 문제는 없는지 평가했는가","다른 의견을 존중하며 말했는가"]},"explanation":["『국어』 73쪽 「의견 평가하기」 활동이에요.","의견과 그 이유가 적절한지 평가하며 친구가 쓴 글을 읽어요.","같은 문제에도 다양한 의견이 있을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#1','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C11',1,'ox','auto','『국어』 77쪽 「정리하기」예요. 작품 속 세계와 현실 세계를 비교하면 작품을 더 깊이 있게 이해할 수 있어요.',ARRAY['K4-2-u1-X06']::text[],false,'{"seq":1,"concept":"K4-2-u1-C11","difficulty":1,"kind":"ox","stem":"『국어』 77쪽 「정리하기」예요. 작품 속 세계와 현실 세계를 비교하면 작품을 더 깊이 있게 이해할 수 있어요.","answer":"O","reason_options":[{"t":"현실과 비슷한 점과 다른 점을 찾으며 인물·사건·배경을 더 잘 알게 되기 때문에","correct":true},{"t":"작품은 다 꾸민 것이라 현실과 견줄 필요가 없기 때문에","mis":"K4-2-u1-X06"}],"mis":"K4-2-u1-X06","explanation":["「정리하기」에서 ○ 표를 하는 문장이에요.","자신의 경험을 바탕으로 사실인 부분과 꾸며 쓴 부분을 비교해요.","그러면 인물, 상황, 배경, 분위기를 더 깊이 이해할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#2','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C1',1,'mc','auto','『국어』 37쪽 「무엇을 배울까요」에서 소단원 2를 공부하는 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X27','K4-2-u1-X20','K4-2-u1-X24']::text[],false,'{"seq":2,"concept":"K4-2-u1-C1","difficulty":1,"kind":"mc","stem":"『국어』 37쪽 「무엇을 배울까요」에서 소단원 2를 공부하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"의견을 비교하며 읽으면 좋은 점 알기 → 서로 다른 글쓴이의 의견 파악하기 → 의견을 비교하고 평가하며 글 읽기","correct":true},{"t":"의견을 평가하기 → 좋은 점 알기 → 의견 파악하기","mis":"K4-2-u1-X27"},{"t":"의견 파악하기 → 평가하기 → 끝","mis":"K4-2-u1-X20"},{"t":"평가하기 → 의견 파악하기 → 좋은 점 알기","mis":"K4-2-u1-X24"}],"explanation":["먼저 비교하며 읽으면 좋은 점을 알아요.","그다음 서로 다른 의견을 파악해요.","마지막으로 의견을 비교하고 평가하며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#3','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C17',1,'mc','auto','「언제나 다정 죽집」에 나타난 모습 가운데 현실과 비슷한 점은 무엇인가요?',ARRAY['K4-2-u1-X01','K4-2-u1-X05']::text[],false,'{"seq":3,"concept":"K4-2-u1-C17","difficulty":1,"kind":"mc","stem":"「언제나 다정 죽집」에 나타난 모습 가운데 현실과 비슷한 점은 무엇인가요?","options":[{"t":"음식을 만들 때 부엌 도구를 사용한다","correct":true},{"t":"부엌 도구들이 말하고 스스로 움직인다","mis":"K4-2-u1-X01"},{"t":"고양이가 사람처럼 말을 한다","mis":"K4-2-u1-X01"},{"t":"고양이가 말을 하는 것만 빼면 나머지는 모두 실제로 있었던 일이다","mis":"K4-2-u1-X05"}],"explanation":["『국어』 61쪽 (1)번 예시의 비슷한 점이에요.","가마솥, 주걱, 사발로 음식을 만드는 것은 현실과 같아요.","부엌 도구가 말하는 것, 빵 이야기 같은 부분은 꾸며 쓴 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#4','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C26',1,'mc','auto','친구가 「가을에는 시원한 바람이 불어 기분이 좋다.」라고 말했어요. 이 문장에서 기분이 좋은 이유에 해당하는 부분은 무엇인가요?',ARRAY['K4-2-u1-X24']::text[],false,'{"seq":4,"concept":"K4-2-u1-C26","difficulty":1,"kind":"mc","stem":"친구가 「가을에는 시원한 바람이 불어 기분이 좋다.」라고 말했어요. 이 문장에서 기분이 좋은 이유에 해당하는 부분은 무엇인가요?","options":[{"t":"시원한 바람이 불어","correct":true},{"t":"가을에는","mis":"K4-2-u1-X24"},{"t":"기분이 좋다","mis":"K4-2-u1-X24"},{"t":"가을의 기분","mis":"K4-2-u1-X24"}],"explanation":["「기분이 좋다」는 친구의 생각이에요.","그렇게 생각한 까닭은 시원한 바람이에요.","의견과 이유를 나누면 생각이 또렷해져요."],"asset":{"type":"speech","turns":[{"who":"하은","text":"가을은 단풍이 드는 계절이라서 아름답다."},{"who":"도현","text":"가을에는 시원한 바람이 불어 기분이 좋다."},{"who":"지아","text":"가을에는 맛있는 과일을 많이 먹을 수 있다."},{"who":"서준","text":"가을에는 학교 운동회를 해서 기대된다."},{"who":"유나","text":"가을마다 우리 가족은 등산을 해서 즐겁다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#5','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C43',1,'mc','auto','하려는 뜻의 「-려고」를 바르게 쓴 문장은 무엇인가요?',ARRAY['K4-2-u1-X39','K4-2-u1-X40']::text[],false,'{"seq":5,"concept":"K4-2-u1-C43","difficulty":1,"kind":"mc","stem":"하려는 뜻의 「-려고」를 바르게 쓴 문장은 무엇인가요?","options":[{"t":"숙제를 먼저 하려고 책상에 앉았다.","correct":true},{"t":"숙제를 먼저 할려고 책상에 앉았다.","mis":"K4-2-u1-X39"},{"t":"친구를 만날려고 공원에 갔다.","mis":"K4-2-u1-X39"},{"t":"동생과 놀으려고 밖에 나갔다.","mis":"K4-2-u1-X40"}],"explanation":["「하다」+「-려고」는 「하려고」, 「만나다」+「-려고」는 「만나려고」예요.","「놀다」는 원래 ㄹ 받침이 있어 「놀려고」로 써요.","받침이 없는 말에 ㄹ을 덧붙이거나 「-으려고」를 붙이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#6','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C44',1,'sa','auto','「알다」의 형태가 바뀌지 않는 부분에 「-(으)ㅁ」을 붙여 만든 낱말을 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u1-C44","difficulty":1,"kind":"sa","stem":"「알다」의 형태가 바뀌지 않는 부분에 「-(으)ㅁ」을 붙여 만든 낱말을 쓰세요.","answer":["앎"],"explanation":["「알-」의 받침은 ㄹ이에요.","ㄹ 받침에 「-ㅁ」이 붙으면 받침이 ㄻ이 돼요.","그래서 「알음」, 「암」이 아니라 「앎」으로 써요."],"mis":"K4-2-u1-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#7','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C45',1,'sa','auto','친구가 『국어』 79쪽 글씨 쓰기 낱말을 「떡복이」라고 잘못 썼어요. 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K4-2-u1-C45","difficulty":1,"kind":"sa","stem":"친구가 『국어』 79쪽 글씨 쓰기 낱말을 「떡복이」라고 잘못 썼어요. 바르게 고쳐 쓰세요.","answer":["떡볶이"],"explanation":["「볶」의 받침은 ㄲ이에요.","「볶다」에서 온 말이에요.","그래서 「떡볶이」로 써요."],"mis":"K4-2-u1-X42"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#8','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C13',1,'mc','auto','「가게 인수하실 분 소개도 드리려고 왔습니다.」에서 「인수하실」과 바꾸어 쓸 수 있는 말은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":8,"concept":"K4-2-u1-C13","difficulty":1,"kind":"mc","stem":"「가게 인수하실 분 소개도 드리려고 왔습니다.」에서 「인수하실」과 바꾸어 쓸 수 있는 말은 무엇인가요?","options":[{"t":"건네받으실","correct":true},{"t":"느끼실","mis":"K4-2-u1-X12"},{"t":"부끄러워하실","mis":"K4-2-u1-X12"},{"t":"어렴풋해하실","mis":"K4-2-u1-X12"}],"explanation":["「인수하다」는 물건이나 권리를 건네받는다는 뜻이에요.","키다리 아저씨는 다정 죽집 자리를 넘겨받을 사람이에요.","그래서 「건네받으실」로 바꿀 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#9','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C7',2,'mc','auto','「스펀지 교실」과 현실을 견줄 때 같은 대상끼리 바르게 견준 것은 무엇인가요?',ARRAY['K4-2-u1-X07']::text[],false,'{"seq":9,"concept":"K4-2-u1-C7","difficulty":2,"kind":"mc","stem":"「스펀지 교실」과 현실을 견줄 때 같은 대상끼리 바르게 견준 것은 무엇인가요?","options":[{"t":"시 — 스펀지로 된 폭신한 벽 / 현실 — 딱딱한 벽","correct":true},{"t":"시 — 스펀지 벽 / 현실 — 운동장의 나무","mis":"K4-2-u1-X07"},{"t":"시 — 새들의 여유로운 몸짓 / 현실 — 딱딱한 복도","mis":"K4-2-u1-X07"},{"t":"시 — 둥근 책상 모서리 / 현실 — 둥근 스펀지 책상","mis":"K4-2-u1-X07"}],"explanation":["비교할 때는 같은 대상끼리 나란히 놓아요.","벽은 벽끼리, 복도는 복도끼리 견주어요.","현실의 모습을 바르게 알고 견주어야 해요."],"asset":{"type":"passage","lines":["[표] 「스펀지 교실」에 나타난 모습과 현실의 모습","비슷한 점 — 교실에서 친구들과 함께 공부한다.","다른 점 ① 시 — 복도를 뛰어다녀도 다칠 일이 없다.","다른 점 ① 현실 — 복도를 뛰어다니다가 넘어져 다칠 수도 있다.","다른 점 ② 시 — 속상한 일이 있을 땐 스펀지 벽에 점프할 수 있다.","다른 점 ② 현실 — 딱딱한 벽에는 점프할 수 없다."],"title":"4번 (2) 예시 — 『국어』 41쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#10','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C17',2,'blank','auto','「작품 속 세계는 현실 세계를 비슷하게 반영해 (    )을 주고, 현실을 허구적으로 꾸며 써서 재미나 감동, 깨달음을 줘요.」의 빈칸에 들어갈 말은 무엇인가요?',ARRAY['K4-2-u1-X02','K4-2-u1-X15']::text[],false,'{"seq":10,"concept":"K4-2-u1-C17","difficulty":2,"kind":"blank","stem":"「작품 속 세계는 현실 세계를 비슷하게 반영해 (    )을 주고, 현실을 허구적으로 꾸며 써서 재미나 감동, 깨달음을 줘요.」의 빈칸에 들어갈 말은 무엇인가요?","options":[{"t":"공감","correct":true},{"t":"거짓","mis":"K4-2-u1-X02"},{"t":"두려움","mis":"K4-2-u1-X15"},{"t":"지루함","mis":"K4-2-u1-X15"}],"explanation":["현실과 비슷하면 내 일처럼 느껴져요.","그래서 읽는 사람이 공감해요.","꾸며 쓴 부분은 재미나 감동, 깨달음을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#11','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C12',2,'mc','auto','과일 가게 아저씨가 다정 죽집을 찾아온 까닭은 무엇인가요?',ARRAY['K4-2-u1-X11']::text[],false,'{"seq":11,"concept":"K4-2-u1-C12","difficulty":2,"kind":"mc","stem":"과일 가게 아저씨가 다정 죽집을 찾아온 까닭은 무엇인가요?","options":[{"t":"입덧하던 아내가 먹은 고양이 발 모양 빵을 또 구하고 싶어서","correct":true},{"t":"팥죽값을 따지러","mis":"K4-2-u1-X11"},{"t":"가게를 인수하려고","mis":"K4-2-u1-X11"},{"t":"빵 만드는 법을 배우려고","mis":"K4-2-u1-X11"}],"explanation":["아저씨는 며칠 전 받은 빵을 아내에게 남겨 주었어요.","입덧으로 밥을 못 먹던 아내가 그 빵을 찾았어요.","가게를 인수할 사람은 키다리 아저씨예요."],"asset":{"type":"passage","lines":["[간추림] 할머니는 이 주째 아침마다 놓여 있던 빵을 ‘빵 요정의 마법’이라고 여겼다.","[간추림] 과일 가게 아저씨가 와서 며칠 전 받은 고양이 발 모양 빵을 구할 수 있는지 물었다.","[간추림] 입덧으로 밥을 못 먹던 아내가 그 빵만은 먹고 또 찾는다고 했다.","[간추림] 눈치 빠른 인두가 고양이빵 상자를 할머니 눈에 띄는 탁자에 몰래 놓았다.","[간추림] 할머니는 팥죽값만 받고 팥죽 두 그릇에 고양이빵 두 개를 함께 건넸다.","“식구가 셋인데 하나 가지곤 안 되죠."],"title":"「언제나 다정 죽집」 가운데 ② — 『국어』 51~53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#12','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C14',2,'mc','auto','할머니가 베레모 아저씨와 키다리 아저씨에게 넉넉한 대접에 팥죽을 그득 담아 건넨 행동으로 짐작한 성격은 무엇인가요?',ARRAY['K4-2-u1-X13']::text[],false,'{"seq":12,"concept":"K4-2-u1-C14","difficulty":2,"kind":"mc","stem":"할머니가 베레모 아저씨와 키다리 아저씨에게 넉넉한 대접에 팥죽을 그득 담아 건넨 행동으로 짐작한 성격은 무엇인가요?","options":[{"t":"다정하고 자상하다","correct":true},{"t":"매정하다","mis":"K4-2-u1-X13"},{"t":"욕심이 많다","mis":"K4-2-u1-X13"},{"t":"무뚝뚝하다","mis":"K4-2-u1-X13"}],"explanation":["가게를 넘겨받을 사람에게도 팥죽을 넉넉히 내었어요.","「정성껏 끓인 것이니 달게 자셔 주세요.」라고 했어요.","다정하고 자상한 성격이에요."],"asset":{"type":"passage","lines":["[간추림] 건물 주인 베레모 아저씨가 가게를 넘겨받을 키다리 아저씨와 함께 왔다.","[간추림] 할머니는 넉넉한 대접에 팥죽을 그득 담아 두 사람에게 내었다.","“비결이랄 게 있나요. 그저 팥죽을 팥죽답게 끓였을 뿐이지요.”","[간추림] 좋은 재료를 고집하고 얕은수는 쓰지 않았으며, 늘 넉넉하게 나눴다고 했다.","“이 죽집 이름이 맛의 비밀이었어요.”"],"title":"「언제나 다정 죽집」 뒷부분 — 『국어』 54~57쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#13','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C23',2,'mc','auto','글 ㉮와 글 ㉯를 비교하며 읽은 친구가 「축구를 하고 싶은 친구와 다칠까 봐 걱정하는 친구의 생각을 다 알게 됐어.」라고 말했어요. 이 친구가 느낀 좋은 점은 무엇인가요?',ARRAY['K4-2-u1-X21','K4-2-u1-X20']::text[],false,'{"seq":13,"concept":"K4-2-u1-C23","difficulty":2,"kind":"mc","stem":"글 ㉮와 글 ㉯를 비교하며 읽은 친구가 「축구를 하고 싶은 친구와 다칠까 봐 걱정하는 친구의 생각을 다 알게 됐어.」라고 말했어요. 이 친구가 느낀 좋은 점은 무엇인가요?","options":[{"t":"같은 문제에 대한 다양한 생각을 알 수 있다","correct":true},{"t":"어느 글이 틀렸는지 알 수 있다","mis":"K4-2-u1-X21"},{"t":"긴 글을 따르면 된다는 것을 알았다","mis":"K4-2-u1-X20"},{"t":"나와 같은 의견만 읽으면 된다는 것을 알았다","mis":"K4-2-u1-X20"}],"explanation":["두 글을 함께 읽으니 두 가지 생각을 알게 되었어요.","같은 문제에 대한 다양한 생각을 알 수 있다는 좋은 점이에요.","어느 글이 틀렸는지를 가리는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#14','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C27',2,'mc','auto','한복 글 ㉮와 글 ㉯의 제목을 나란히 놓고 보면 무엇을 짐작할 수 있나요?',ARRAY['K4-2-u1-X30','K4-2-u1-X21']::text[],false,'{"seq":14,"concept":"K4-2-u1-C27","difficulty":2,"kind":"mc","stem":"한복 글 ㉮와 글 ㉯의 제목을 나란히 놓고 보면 무엇을 짐작할 수 있나요?","options":[{"t":"두 글쓴이의 의견이 어떻게 다른지","correct":true},{"t":"두 글의 글자 수","mis":"K4-2-u1-X30"},{"t":"두 글쓴이의 나이","mis":"K4-2-u1-X30"},{"t":"어느 글이 정답인지","mis":"K4-2-u1-X21"}],"explanation":["제목에 드러난 다른 점으로 의견의 다른 점을 짐작할 수 있어요.","㉮는 지키자, ㉯는 인정하자는 쪽이에요.","짐작한 뒤 글을 읽으며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#15','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C34',2,'mc','auto','『국어』 72쪽에서 「글쓴이의 의견대로 했을 때 다른 문제가 생기지 않을지도 생각해 봐요.」라고 한 까닭은 무엇인가요?',ARRAY['K4-2-u1-X43','K4-2-u1-X33','K4-2-u1-X32']::text[],false,'{"seq":15,"concept":"K4-2-u1-C34","difficulty":2,"kind":"mc","stem":"『국어』 72쪽에서 「글쓴이의 의견대로 했을 때 다른 문제가 생기지 않을지도 생각해 봐요.」라고 한 까닭은 무엇인가요?","options":[{"t":"잘못된 의견을 따르면 문제를 해결하지 못하거나 더 많은 문제가 생길 수 있기 때문에","correct":true},{"t":"의견은 따르기만 하면 되기 때문에","mis":"K4-2-u1-X43"},{"t":"이유가 많으면 문제가 없기 때문에","mis":"K4-2-u1-X33"},{"t":"다른 문제는 글쓴이가 걱정할 일이기 때문에","mis":"K4-2-u1-X32"}],"explanation":["의견대로 했을 때 문제 상황을 해결할 수 있는지 생각해요.","적절하지 못한 의견을 고르면 더 많은 문제가 생길 수 있어요.","그래서 의견대로 했을 때의 일까지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#16','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C42',2,'mc','auto','누리집 게시판에 댓글을 쓸 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u1-X38']::text[],false,'{"seq":16,"concept":"K4-2-u1-C42","difficulty":2,"kind":"mc","stem":"누리집 게시판에 댓글을 쓸 때 알맞은 방법은 무엇인가요?","options":[{"t":"자신의 의견과 그 의견을 뒷받침하는 이유를 함께 쓴다","correct":true},{"t":"「저도요」 한마디만 쓴다","mis":"K4-2-u1-X38"},{"t":"다른 사람의 의견을 깎아내린다","mis":"K4-2-u1-X38"},{"t":"이유 없이 의견만 크게 외친다","mis":"K4-2-u1-X38"}],"explanation":["『국어』 75쪽 3번 활동이에요.","의견과 이유가 드러나게 써요.","다른 사람을 존중하는 말투로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#17','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C17',3,'mc','auto','「황금 알을 낳는 거위」에 나타난 모습 가운데 현실과 비슷한 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X01','K4-2-u1-X05']::text[],false,'{"seq":17,"concept":"K4-2-u1-C17","difficulty":3,"kind":"mc","stem":"「황금 알을 낳는 거위」에 나타난 모습 가운데 현실과 비슷한 점으로 알맞은 것은 무엇인가요?","options":[{"t":"욕심을 부리다가 가진 것을 잃는 사람이 있다","correct":true},{"t":"거위 뱃속에 황금 알이 가득하다","mis":"K4-2-u1-X01"},{"t":"하루에 한 알씩 황금이 생긴다","mis":"K4-2-u1-X01"},{"t":"거위가 황금 알을 낳는 것만 꾸민 것이고, 농부가 부자가 된 것은 실제로 있었던 일이다","mis":"K4-2-u1-X05"}],"explanation":["욕심 때문에 일을 그르치는 모습은 현실에서도 볼 수 있어요.","황금 알과 그 알로 부자가 된 일은 꾸며 쓴 이야기예요.","현실과 닮은 부분이 있어 읽는 사람이 공감해요."],"asset":{"type":"passage","lines":["[간추림] 옛날 어느 마을에 가난한 농부가 시장에서 거위 한 마리를 샀다.","[간추림] 거위는 아침마다 번쩍이는 황금 알을 한 개씩 낳았다.","[간추림] 농부는 황금 알을 팔아 부자가 되고 넓은 집도 샀지만, 점점 욕심이 생겼다.","[간추림] “거위 뱃속에 황금 알이 가득할 거야!” 농부는 거위의 배를 갈랐다.","[간추림] 뱃속에는 황금 알이 하나도 없었고, 농부는 거위도 잃고 다시 가난해졌다."],"title":"평가 글 「황금 알을 낳는 거위」(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#18','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C18',3,'mc','auto','「비밀의 무게」에서 겉으로 화려해 보였던 남산 타워도 실제로는 힘들다는 것을 찬이가 깨닫는 장면에서 짐작할 수 있는 글쓴이의 생각은 무엇인가요?',ARRAY['K4-2-u1-X16','K4-2-u1-X17']::text[],false,'{"seq":18,"concept":"K4-2-u1-C18","difficulty":3,"kind":"mc","stem":"「비밀의 무게」에서 겉으로 화려해 보였던 남산 타워도 실제로는 힘들다는 것을 찬이가 깨닫는 장면에서 짐작할 수 있는 글쓴이의 생각은 무엇인가요?","options":[{"t":"겉으로 좋아 보이는 것에도 남모르는 어려움이 있을 수 있다","correct":true},{"t":"남산 타워는 밤에 사람의 방으로 놀러 온다","mis":"K4-2-u1-X16"},{"t":"힘든 일은 아무에게도 말하지 말고 숨겨야 한다","mis":"K4-2-u1-X17"},{"t":"남산 타워는 먼지투성이이니 가지 말아야 한다","mis":"K4-2-u1-X17"}],"explanation":["찬이는 사랑받는 남산 타워를 부러워했어요.","가까이서 보니 남산 타워도 피곤하고 힘들었어요.","이 깨달음에서 글쓴이의 생각을 짐작할 수 있어요."],"asset":{"type":"passage","lines":["[간추림] 찬이는 기분이 좋지 않을 때마다 창밖의 남산 타워를 부러워하며 바라본다.","[간추림] 찬이가 놀러 오라고 말하자 남산 타워가 정말로 찬이 방에 찾아온다.","[간추림] 가까이서 본 남산 타워는 먼지투성이였고, 밤낮없이 서 있어 피곤하다며 침대에 눕는다.","[간추림] 찬이는 비밀을 지키려고 학교와 집에서 말과 행동을 조심하다 마음이 무거워진다.","[간추림] 찬이의 마음을 이해한 남산 타워는 고마워하며 남산으로 돌아간다."],"title":"『국어활동』 스스로 읽기 「비밀의 무게」(심순 글) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#19','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C32',3,'error','auto','점심시간 운동장 축구 문제에 대해 친구들이 의견을 냈어요. 문제 상황과 관련 없는 의견을 낸 친구는 누구인가요?',ARRAY['K4-2-u1-X47']::text[],false,'{"seq":19,"concept":"K4-2-u1-C32","difficulty":3,"kind":"error","stem":"점심시간 운동장 축구 문제에 대해 친구들이 의견을 냈어요. 문제 상황과 관련 없는 의견을 낸 친구는 누구인가요?","options":[{"t":"친구 다 — 「급식에 반찬을 하나 더 주면 좋겠어.」","correct":true,"mis_target":"K4-2-u1-X47"},{"t":"친구 가 — 「저학년 하교 시간에는 운동장 한쪽을 비워 두자.」","mis":"K4-2-u1-X47"},{"t":"친구 나 — 「축구를 하는 곳에 높은 그물망을 설치하자.」","mis":"K4-2-u1-X47"}],"explanation":["문제 상황은 점심시간 운동장 축구의 안전이에요.","적절한 의견은 이 문제와 관련 있어야 해요.","반찬 이야기는 그럴듯해 보여도 문제와 상관없어요."],"asset":{"type":"passage","lines":["㉮ [간추림] 축구를 할 수 있는 시간은 점심시간뿐이고, 즐겁고 건강에도 좋다.","㉮ [간추림] 운동장은 모두의 공간이고, 위험하면 그물망·안전 수칙으로 막으면 된다.","㉮ [간추림] 그래서 점심시간에 운동장에서 축구를 하는 것에 찬성한다.","㉯ [간추림] 쉬는 시간인 것은 맞지만, 고학년 점심시간은 저학년 하교 시간이다.","㉯ [간추림] 지난봄 1학년 동생이 공에 맞아 다쳤고, 축구하는 사람도 다칠 수 있다.","㉯ [간추림] 그래서 점심시간에 운동장에서 축구를 하는 것에 반대한다."],"title":"학교 누리집에 올라온 두 글 — 『국어』 62~63쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#20','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C36',3,'mc','auto','지민이의 의견을 평가한 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X33','K4-2-u1-X21','K4-2-u1-X34']::text[],false,'{"seq":20,"concept":"K4-2-u1-C36","difficulty":3,"kind":"mc","stem":"지민이의 의견을 평가한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"도서관 꾸미기 문제에 맞는 의견이지만, 바른 자세여야만 독서를 잘한다는 이유는 사람마다 다를 수 있어 더 따져 봐야 한다","correct":true},{"t":"이유가 두 개라 무조건 적절하다","mis":"K4-2-u1-X33"},{"t":"하윤이 의견과 다르니 틀렸다","mis":"K4-2-u1-X21"},{"t":"나는 책상이 좋으니 따지지 않고 믿는다","mis":"K4-2-u1-X34"}],"explanation":["문제 상황에 맞는지, 이유가 적절한지 차례로 따져요.","이유의 개수가 아니라 이유가 타당한지를 봐요.","내 생각과 같은 쪽도 똑같이 따져요."],"asset":{"type":"passage","lines":["[간추림] 기사 제목 — 우리 학교 도서관, 새로운 변화가 필요해요","[하윤] 도서관에 소파를 놓거나 마루를 설치하면 좋겠습니다.","[하윤] 도서관이 편안한 공간이 되면 학생들이 도서관을 좋아하게 될 것입니다.","[하윤] 편안한 자리에서 좋아하는 자세로 책을 읽으면 독서가 더 즐거워질 것입니다.","[지민] 도서관에 책상과 의자를 많이 두면 좋겠습니다.","[지민] 도서관은 공부하는 곳이기 때문입니다.","[지민] 바른 자세로 앉아서 책을 읽어야 독서를 더욱 잘할 수 있기 때문입니다."],"title":"초등학교 신문 — 『국어활동』 8쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#21','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C41',3,'mc','auto','전재현과 윤시완의 의견에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X28','K4-2-u1-X21','K4-2-u1-X22']::text[],false,'{"seq":21,"concept":"K4-2-u1-C41","difficulty":3,"kind":"mc","stem":"전재현과 윤시완의 의견에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"두 사람 모두 한옥 마을에 살며 겪은 일을 이유로 들었고, 걱정하는 사람과 일이 다를 뿐이다","correct":true},{"t":"한 사람은 마을을 잘 모르고 반대했다","mis":"K4-2-u1-X28"},{"t":"의견이 반대이니 한 사람은 틀렸다","mis":"K4-2-u1-X21"},{"t":"둘 다 맞으니 이유를 따질 필요가 없다","mis":"K4-2-u1-X22"}],"explanation":["전재현은 주민의 쉼과 깨끗함을, 윤시완은 숙소와 가게의 생활을 걱정해요.","둘 다 직접 겪은 일을 이유로 들었어요.","의견과 이유를 비교하고 평가해 보아요."],"asset":{"type":"passage","lines":["[전재현의 글] 요즘 우리 한옥 마을이 많은 관광객으로 몸살을 앓고 있습니다.","[전재현의 글] 관광객들이 늦은 시간까지 큰 소리로 떠들고, 집 앞에 쓰레기가 쌓입니다.","[전재현의 글] 주민들이 조용하고 깨끗하게 지내도록 관광객을 제한해 주시면 좋겠습니다.","[윤시완의 댓글] 저는 마을이 관광객들로 더욱 활기찬 것 같아 즐겁습니다.","[윤시완의 댓글] 우리 가족은 관광객을 위한 숙소와 식당을 운영합니다.","[윤시완의 댓글] 관광객을 제한하면 숙소나 가게를 하는 사람들이 경제적으로 어려워집니다.","[김누리의 댓글] 서로 양보해서 저녁 8시까지로 관광 시간을 제한하면 좋겠습니다.","[김누리의 댓글] 주민은 저녁에 쉴 수 있고 숙소나 가게도 운영될 수 있기 때문입니다."],"title":"○○시청 누리집 ‘시민의 소리’ — 『국어』 75쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#22','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C24',3,'mc','auto','『국어』 73쪽 날개 「자신의 의견은 글쓴이의 의견과 다를 수도 있어요.」 다음에 이어지는 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X21','K4-2-u1-X43','K4-2-u1-X22']::text[],false,'{"seq":22,"concept":"K4-2-u1-C24","difficulty":3,"kind":"mc","stem":"『국어』 73쪽 날개 「자신의 의견은 글쓴이의 의견과 다를 수도 있어요.」 다음에 이어지는 말로 알맞은 것은 무엇인가요?","options":[{"t":"우리는 다양한 의견을 서로 존중해야 해요.","correct":true},{"t":"그러니 다른 의견은 틀렸다고 말해요.","mis":"K4-2-u1-X21"},{"t":"그러니 무조건 글쓴이 의견을 따라야 해요.","mis":"K4-2-u1-X43"},{"t":"그러니 의견은 따져 볼 필요가 없어요.","mis":"K4-2-u1-X22"}],"explanation":["의견이 다를 수 있다는 것을 알면 존중할 수 있어요.","존중은 무조건 따르는 것이 아니에요.","서로의 이유를 듣고 따져 보는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#23','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C19',4,'essay','teacher','자신에게 황금 알을 낳는 거위가 있다면 어떻게 하고 싶은지 상상해 쓰고, 그렇게 한다면 이야기 속 농부와 무엇이 다를지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u1-C19","difficulty":4,"kind":"essay","stem":"자신에게 황금 알을 낳는 거위가 있다면 어떻게 하고 싶은지 상상해 쓰고, 그렇게 한다면 이야기 속 농부와 무엇이 다를지 쓰세요.","answer_guide":{"answer":"예: 나는 하루에 한 알씩 낳는 황금 알을 모아, 절반은 아픈 친구들의 병원비를 돕는 데 쓰고 절반은 거위를 잘 돌보는 데 쓰겠다. 농부는 더 많이 가지려고 거위의 배를 갈랐지만, 나는 거위를 아끼고 기다리기 때문에 황금 알도 거위도 잃지 않을 것이다.","scoring_points":["거위가 있다면 하고 싶은 일을 상상해 썼는가","이야기 속 농부의 행동과 견주었는가","이야기에서 얻은 생각이 드러나는가"]},"explanation":["평가 자료 1의 3번 활동이에요.","자신이 바라는 소망을 긍정적인 방향으로 상상해요.","농부와 견주면 이야기가 주는 깨달음이 또렷해져요."],"asset":{"type":"passage","lines":["[간추림] 옛날 어느 마을에 가난한 농부가 시장에서 거위 한 마리를 샀다.","[간추림] 거위는 아침마다 번쩍이는 황금 알을 한 개씩 낳았다.","[간추림] 농부는 황금 알을 팔아 부자가 되고 넓은 집도 샀지만, 점점 욕심이 생겼다.","[간추림] “거위 뱃속에 황금 알이 가득할 거야!” 농부는 거위의 배를 갈랐다.","[간추림] 뱃속에는 황금 알이 하나도 없었고, 농부는 거위도 잃고 다시 가난해졌다."],"title":"평가 글 「황금 알을 낳는 거위」(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#24','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C37',4,'essay','teacher','학급 토의에서 친구들의 의견이 여러 가지로 나왔어요. 친구 의견 두 가지를 예로 들어 비교하고 평가한 뒤, 내 의견을 어떻게 정했는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u1-C37","difficulty":4,"kind":"essay","stem":"학급 토의에서 친구들의 의견이 여러 가지로 나왔어요. 친구 의견 두 가지를 예로 들어 비교하고 평가한 뒤, 내 의견을 어떻게 정했는지 쓰세요.","answer_guide":{"answer":"예: 문제 — 학급 문고 책이 자꾸 없어진다. 친구 1 — 책 빌리기 공책을 만들자: 누가 빌렸는지 알 수 있어 문제와 관련 있고 이유가 타당하다. 친구 2 — 학급 문고를 없애자: 책이 없어지는 문제는 사라지지만 책을 읽을 기회가 줄어드는 다른 문제가 생긴다. 내 의견 — 친구 1의 의견에 찬성하고, 책 정리 도우미를 정하자는 의견을 더했다.","scoring_points":["친구 의견 두 가지를 썼는가","같은 기준으로 비교하고 평가했는가","평가를 바탕으로 내 의견을 정한 과정을 썼는가"]},"explanation":["평가 자료 2의 3번 활동이에요.","친구들이 낸 여러 의견 가운데 적절성을 판단해 내 의견을 정할 수 있어요.","자신의 의견을 정하고 이유를 찾아 토의하는 과정이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_b#25','kor',4,2,'u1','','tb_g4_2_kor_u1_review_b','unit_review','K4-2-u1-C29',4,'essay','teacher','글 ㉮ 「우리 전통 한복의 가치를 지켜 주세요」와 글 ㉯ 「틀린 것이 아니라 새로운 아름다움으로 봐 주세요」를 읽고, 두 글쓴이가 관광지의 변형 한복을 서로 다르게 본 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u1-C29","difficulty":4,"kind":"essay","stem":"글 ㉮ 「우리 전통 한복의 가치를 지켜 주세요」와 글 ㉯ 「틀린 것이 아니라 새로운 아름다움으로 봐 주세요」를 읽고, 두 글쓴이가 관광지의 변형 한복을 서로 다르게 본 까닭을 쓰세요.","answer_guide":{"answer":"예: 글 ㉮의 글쓴이는 한복을 우리 고유의 소중한 문화로 여겨, 지나치게 바뀐 한복이 전통을 왜곡하고 외국인에게 오해를 줄까 봐 걱정했다. 글 ㉯의 글쓴이는 많은 사람이 한복을 입고 즐기는 것을 중요하게 여겨, 변형 한복이 한복을 세계에 알리는 새로운 아름다움이라고 보았다. 무엇을 더 중요하게 여기느냐가 달랐기 때문이다.","scoring_points":["글 ㉮가 중요하게 여긴 것을 썼는가","글 ㉯가 중요하게 여긴 것을 썼는가","다르게 본 까닭을 두 글의 근거로 설명했는가"]},"explanation":["두 글쓴이는 같은 대상을 보았어요.","중요하게 여기는 것이 달라 의견이 달라졌어요.","한쪽이 잘못 본 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#1','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C20',1,'ox','auto','『국어』 77쪽 「정리하기」예요. 같은 문제 상황에 대해 사람들의 의견은 서로 다를 수 있어요.',ARRAY['K4-2-u1-X21']::text[],false,'{"seq":1,"concept":"K4-2-u1-C20","difficulty":1,"kind":"ox","stem":"『국어』 77쪽 「정리하기」예요. 같은 문제 상황에 대해 사람들의 의견은 서로 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 경험, 생각, 배경지식이 다르기 때문에","correct":true},{"t":"같은 문제에는 하나의 의견만 있어야 하기 때문에","mis":"K4-2-u1-X21"}],"mis":"K4-2-u1-X21","explanation":["「정리하기」에서 ○ 표를 하는 문장이에요.","점심시간 축구, 한복, 무인 안내기 모두 의견이 둘로 갈렸어요.","의견이 다르다고 하나가 틀린 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#2','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C6',1,'blank','auto','『국어활동』 7쪽 「더 알아보기」예요. 「(    )을 바탕으로 작품에서 사실인 부분과 꾸며 쓴 부분을 비교하면 작품을 더 깊이 있게 이해할 수 있어요.」의 빈칸에 들어갈 말은 무엇인가요?',ARRAY['K4-2-u1-X30','K4-2-u1-X03']::text[],false,'{"seq":2,"concept":"K4-2-u1-C6","difficulty":1,"kind":"blank","stem":"『국어활동』 7쪽 「더 알아보기」예요. 「(    )을 바탕으로 작품에서 사실인 부분과 꾸며 쓴 부분을 비교하면 작품을 더 깊이 있게 이해할 수 있어요.」의 빈칸에 들어갈 말은 무엇인가요?","options":[{"t":"자신의 경험","correct":true},{"t":"작품의 글자 수","mis":"K4-2-u1-X30"},{"t":"친구가 고른 정답","mis":"K4-2-u1-X03"},{"t":"작품을 쓴 날짜","mis":"K4-2-u1-X30"}],"explanation":["「자신의 경험을 바탕으로 작품에서 사실인 부분과 꾸며 쓴 부분을 비교하면」이라고 했어요.","그러면 인물, 상황, 배경, 일어난 일, 분위기를 더 깊이 이해할 수 있어요.","경험은 사람마다 달라도 괜찮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#3','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C16',1,'mc','auto','「비밀의 무게」에서 찬이의 방에 남산 타워가 찾아와 침대에 눕는 일은 어떤 부분인가요?',ARRAY['K4-2-u1-X01','K4-2-u1-X02']::text[],false,'{"seq":3,"concept":"K4-2-u1-C16","difficulty":1,"kind":"mc","stem":"「비밀의 무게」에서 찬이의 방에 남산 타워가 찾아와 침대에 눕는 일은 어떤 부분인가요?","options":[{"t":"현실에서 일어나기 어려운 일을 꾸며 쓴 부분","correct":true},{"t":"현실에서 흔히 일어나는 일","mis":"K4-2-u1-X01"},{"t":"글쓴이가 실제로 겪은 일","mis":"K4-2-u1-X01"},{"t":"잘못 쓴 부분이라 고쳐야 할 곳","mis":"K4-2-u1-X02"}],"explanation":["남산 타워는 움직일 수 없어요.","이 장면은 글쓴이가 상상하여 꾸며 쓴 부분이에요.","꾸며 쓴 부분은 잘못이 아니라 이야기의 재미와 깨달음을 줘요."],"asset":{"type":"passage","lines":["[간추림] 찬이는 기분이 좋지 않을 때마다 창밖의 남산 타워를 부러워하며 바라본다.","[간추림] 찬이가 놀러 오라고 말하자 남산 타워가 정말로 찬이 방에 찾아온다.","[간추림] 가까이서 본 남산 타워는 먼지투성이였고, 밤낮없이 서 있어 피곤하다며 침대에 눕는다.","[간추림] 찬이는 비밀을 지키려고 학교와 집에서 말과 행동을 조심하다 마음이 무거워진다.","[간추림] 찬이의 마음을 이해한 남산 타워는 고마워하며 남산으로 돌아간다."],"title":"『국어활동』 스스로 읽기 「비밀의 무게」(심순 글) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#4','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C26',1,'sa','auto','의견을 말한 뒤 「왜냐하면 ~ 때문입니다.」로 덧붙이는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K4-2-u1-C26","difficulty":1,"kind":"sa","stem":"의견을 말한 뒤 「왜냐하면 ~ 때문입니다.」로 덧붙이는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["이유"],"explanation":["「왜냐하면 ~ 때문입니다.」는 이유를 말할 때 써요.","의견만 말하면 듣는 사람이 까닭을 알 수 없어요.","의견과 이유를 함께 말해요."],"mis":"K4-2-u1-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#5','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C43',1,'blank','auto','「책을 (    ) 도서관에 갔다.」의 빈칸에 들어갈 바른 말은 무엇인가요?',ARRAY['K4-2-u1-X39','K4-2-u1-X40']::text[],false,'{"seq":5,"concept":"K4-2-u1-C43","difficulty":1,"kind":"blank","stem":"「책을 (    ) 도서관에 갔다.」의 빈칸에 들어갈 바른 말은 무엇인가요?","options":[{"t":"보려고","correct":true},{"t":"볼려고","mis":"K4-2-u1-X39"},{"t":"보으려고","mis":"K4-2-u1-X40"}],"explanation":["「보다」에는 받침이 없어요.","「보-」+「-려고」=「보려고」예요.","「볼려고」는 원래 없던 ㄹ을 덧붙인 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#6','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C44',1,'mc','auto','「추다」와 「자다」에 「-(으)ㅁ」을 붙여 바꾼 낱말끼리 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u1-X41']::text[],false,'{"seq":6,"concept":"K4-2-u1-C44","difficulty":1,"kind":"mc","stem":"「추다」와 「자다」에 「-(으)ㅁ」을 붙여 바꾼 낱말끼리 바르게 짝지은 것은 무엇인가요?","options":[{"t":"춤 · 잠","correct":true},{"t":"추음 · 자음","mis":"K4-2-u1-X41"},{"t":"춤 · 자음","mis":"K4-2-u1-X41"},{"t":"추움 · 잠","mis":"K4-2-u1-X41"}],"explanation":["「추-」, 「자-」에는 받침이 없어요.","받침이 없으면 「-ㅁ」을 붙여요.","「춤」, 「잠」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#7','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C45',1,'blank','auto','「밀가루와 설탕을 골고루 (    ).」의 빈칸에 들어갈 바른 말은 무엇인가요?',ARRAY['K4-2-u1-X42']::text[],false,'{"seq":7,"concept":"K4-2-u1-C45","difficulty":1,"kind":"blank","stem":"「밀가루와 설탕을 골고루 (    ).」의 빈칸에 들어갈 바른 말은 무엇인가요?","options":[{"t":"섞다","correct":true},{"t":"석다","mis":"K4-2-u1-X42"},{"t":"섯다","mis":"K4-2-u1-X42"},{"t":"섞따","mis":"K4-2-u1-X42"}],"explanation":["「섞다」는 ㄲ 받침이에요.","받침을 ㄱ이나 ㅅ으로 쓰지 않아요.","소리 나는 대로 「섞따」로 쓰지도 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#8','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C31',1,'mc','auto','「카드로만 결제해야 하기 때문에 불편합니다.」에서 「결제해야」의 뜻은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":8,"concept":"K4-2-u1-C31","difficulty":1,"kind":"mc","stem":"「카드로만 결제해야 하기 때문에 불편합니다.」에서 「결제해야」의 뜻은 무엇인가요?","options":[{"t":"값을 치러야","correct":true},{"t":"필요한 기구를 두어야","mis":"K4-2-u1-X12"},{"t":"편하고 이로워야","mis":"K4-2-u1-X12"},{"t":"무르고 약해야","mis":"K4-2-u1-X12"}],"explanation":["『국어』 71쪽 「낱말 알기」예요.","「결제하다」는 값을 치른다는 뜻이에요.","현금만 있는 사람은 카드로 값을 치를 수 없어 불편해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#9','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C1',2,'mc','auto','「글쓴이의 의견과 이유가 알맞은지 살펴본다」는 이 단원에서 무엇을 할 때 쓰는 방법인가요?',ARRAY['K4-2-u1-X49','K4-2-u1-X12']::text[],false,'{"seq":9,"concept":"K4-2-u1-C1","difficulty":2,"kind":"mc","stem":"「글쓴이의 의견과 이유가 알맞은지 살펴본다」는 이 단원에서 무엇을 할 때 쓰는 방법인가요?","options":[{"t":"다른 의견이 담긴 글을 비교하며 읽을 때","correct":true},{"t":"작품 속 세계와 현실 세계를 비교하며 작품을 감상할 때","mis":"K4-2-u1-X49"},{"t":"시를 바꾸어 쓸 때","mis":"K4-2-u1-X49"},{"t":"낱말의 뜻을 짐작할 때","mis":"K4-2-u1-X12"}],"explanation":["이 방법은 소단원 2에서 써요.","작품을 감상할 때는 경험을 떠올려 인물·일어난 일·배경을 현실과 견주어요.","두 방법을 섞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#10','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C17',2,'mc','auto','「언제나 다정 죽집」에서 말하는 부엌 친구들처럼 현실을 허구적으로 꾸며 쓴 부분이 주는 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X01','K4-2-u1-X02','K4-2-u1-X15']::text[],false,'{"seq":10,"concept":"K4-2-u1-C17","difficulty":2,"kind":"mc","stem":"「언제나 다정 죽집」에서 말하는 부엌 친구들처럼 현실을 허구적으로 꾸며 쓴 부분이 주는 것으로 알맞은 것은 무엇인가요?","options":[{"t":"재미나 감동, 깨달음","correct":true},{"t":"현실과 똑같다는 믿음","mis":"K4-2-u1-X01"},{"t":"고쳐야 할 잘못","mis":"K4-2-u1-X02"},{"t":"공감만 주고 재미는 없음","mis":"K4-2-u1-X15"}],"explanation":["부엌 친구들의 눈으로 보니 할머니의 다정함이 더 크게 느껴져요.","꾸며 쓴 부분은 재미나 감동, 깨달음을 줘요.","현실과 닮은 부분은 공감을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#11','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C12',2,'mc','auto','「언제나 다정 죽집」에서 할머니가 과일 가게 아저씨에게 고양이빵을 건넨 일 바로 다음에 일어난 일은 무엇인가요?',ARRAY['K4-2-u1-X11']::text[],false,'{"seq":11,"concept":"K4-2-u1-C12","difficulty":2,"kind":"mc","stem":"「언제나 다정 죽집」에서 할머니가 과일 가게 아저씨에게 고양이빵을 건넨 일 바로 다음에 일어난 일은 무엇인가요?","options":[{"t":"베레모 아저씨와 키다리 아저씨가 와서 할머니의 팥죽 맛에 감동했다","correct":true},{"t":"부엌 친구들이 고양이빵을 만들었다","mis":"K4-2-u1-X11"},{"t":"팥냥이가 부엌 친구들에게 처음 말을 걸었다","mis":"K4-2-u1-X11"},{"t":"할머니가 동지 팥죽을 끓이기 시작했다","mis":"K4-2-u1-X11"}],"explanation":["『국어』 59쪽 (1)번 차례의 마지막 두 칸이에요.","고양이빵은 새벽에, 팥죽은 아침에 준비했어요.","과일 가게 아저씨 다음에 두 아저씨가 왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#12','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C14',2,'match','auto','『국어』 59쪽 (2)번 표처럼 「언제나 다정 죽집」 인물의 말이나 행동과 짐작한 성격을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K4-2-u1-C14","difficulty":2,"kind":"match","stem":"『국어』 59쪽 (2)번 표처럼 「언제나 다정 죽집」 인물의 말이나 행동과 짐작한 성격을 알맞게 이으세요.","pairs":[{"l":"할머니 — 설탕도 소금도 넣지 않고 몸을 돌보는 팥죽을 끓임","r":"정직하다"},{"l":"부엌 친구들 — 맡은 역할을 열심히 하며 빵을 만듦","r":"부지런하다"},{"l":"부엌 친구들 — 「일단 우리가 할 수 있는 한 최선을 다해 보자.」","r":"긍정적이다"}],"mis":"K4-2-u1-X13","explanation":["인물이 처한 상황과 말이나 행동을 근거로 성격을 짐작해요.","한 장면이 아니라 여러 장면을 함께 보면 더 정확해요.","이름이나 그림 색깔은 성격의 근거가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#13','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C23',2,'ox','auto','의견을 비교하며 읽는다는 것은 나와 같은 의견이 담긴 글만 골라 읽는다는 뜻이에요.',ARRAY['K4-2-u1-X21']::text[],false,'{"seq":13,"concept":"K4-2-u1-C23","difficulty":2,"kind":"ox","stem":"의견을 비교하며 읽는다는 것은 나와 같은 의견이 담긴 글만 골라 읽는다는 뜻이에요.","answer":"X","reason_options":[{"t":"나와 다른 의견도 함께 읽고 견주어야 하기 때문에","correct":true},{"t":"나와 다른 의견은 틀린 것이기 때문에","mis":"K4-2-u1-X21"}],"mis":"K4-2-u1-X21","explanation":["비교하려면 다른 의견도 읽어야 해요.","나와 다른 의견은 틀린 것이 아니라 다른 생각이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#14','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C28',2,'mc','auto','제목으로 글쓴이의 의견을 짐작한 다음에 해야 할 일은 무엇인가요?',ARRAY['K4-2-u1-X25','K4-2-u1-X27']::text[],false,'{"seq":14,"concept":"K4-2-u1-C28","difficulty":2,"kind":"mc","stem":"제목으로 글쓴이의 의견을 짐작한 다음에 해야 할 일은 무엇인가요?","options":[{"t":"글을 읽으며 끝부분에서 의견을 확인하고 이유를 찾는다","correct":true},{"t":"제목이 의견이니 더 읽지 않는다","mis":"K4-2-u1-X25"},{"t":"글 앞부분 첫 문장을 의견으로 정한다","mis":"K4-2-u1-X27"},{"t":"제목과 상관없이 아무 문장이나 고른다","mis":"K4-2-u1-X27"}],"explanation":["제목은 실마리예요.","글 끝부분에서 의견을 확인해요.","그다음 의견을 받쳐 주는 이유를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#15','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C32',2,'ox','auto','글쓴이의 의견을 비교하고 평가하는 까닭은 의견을 낸 사람을 이기기 위해서예요.',ARRAY['K4-2-u1-X36']::text[],false,'{"seq":15,"concept":"K4-2-u1-C32","difficulty":2,"kind":"ox","stem":"글쓴이의 의견을 비교하고 평가하는 까닭은 의견을 낸 사람을 이기기 위해서예요.","answer":"X","reason_options":[{"t":"더 나은 의견을 판단하고, 잘못된 의견을 따라 문제를 해결하지 못하는 일을 막으려는 것이기 때문에","correct":true},{"t":"토의는 이기고 지는 놀이이기 때문에","mis":"K4-2-u1-X36"}],"mis":"K4-2-u1-X36","explanation":["사람마다 경험, 생각, 배경지식이 달라 의견이 다를 수 있어요.","그 가운데 더 나은 의견을 판단하려고 비교하고 평가해요.","누군가를 이기려는 것이 아니니 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#16','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C30',2,'mc','auto','공익 광고처럼 시각 자료와 짧은 글로 된 자료에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X29']::text[],false,'{"seq":16,"concept":"K4-2-u1-C30","difficulty":2,"kind":"mc","stem":"공익 광고처럼 시각 자료와 짧은 글로 된 자료에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"짧은 광고에도 의견이 담겨 있어 그 의견과 이유를 짐작해 볼 수 있다","correct":true},{"t":"광고에는 의견이 없다","mis":"K4-2-u1-X29"},{"t":"의견은 긴 글에만 있다","mis":"K4-2-u1-X29"},{"t":"광고는 그림만 보고 넘기면 된다","mis":"K4-2-u1-X29"}],"explanation":["우리 반 활동 예시 2에서 공익 광고의 의견과 이유를 짐작했어요.","광고는 짧지만 전하고 싶은 의견이 있어요.","생활 속 여러 자료에서 의견을 찾을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#17','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C16',3,'mc','auto','「비밀의 무게」에서 찬이가 비밀을 지키느라 학교와 집에서 말과 행동을 조심하며 마음이 무거워지는 모습에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X06','K4-2-u1-X01','K4-2-u1-X44']::text[],false,'{"seq":17,"concept":"K4-2-u1-C16","difficulty":3,"kind":"mc","stem":"「비밀의 무게」에서 찬이가 비밀을 지키느라 학교와 집에서 말과 행동을 조심하며 마음이 무거워지는 모습에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"남산 타워가 찾아온 일은 꾸민 것이지만, 비밀을 지키며 마음이 무거워지는 것은 현실에서도 겪을 수 있는 마음이다","correct":true},{"t":"남산 타워가 나오니 찬이의 마음도 모두 현실과 상관없다","mis":"K4-2-u1-X06"},{"t":"찬이의 이야기는 모두 실제로 있었던 일이다","mis":"K4-2-u1-X01"},{"t":"마음이 무거워지는 것은 현실에서 일어날 수 없는 일이다","mis":"K4-2-u1-X44"}],"explanation":["작품에는 꾸며 쓴 부분과 현실과 닮은 부분이 함께 있어요.","비밀을 지키느라 마음이 무거웠던 경험은 우리에게도 있어요.","그래서 꾸민 이야기를 읽으면서도 공감할 수 있어요."],"asset":{"type":"passage","lines":["[간추림] 찬이는 기분이 좋지 않을 때마다 창밖의 남산 타워를 부러워하며 바라본다.","[간추림] 찬이가 놀러 오라고 말하자 남산 타워가 정말로 찬이 방에 찾아온다.","[간추림] 가까이서 본 남산 타워는 먼지투성이였고, 밤낮없이 서 있어 피곤하다며 침대에 눕는다.","[간추림] 찬이는 비밀을 지키려고 학교와 집에서 말과 행동을 조심하다 마음이 무거워진다.","[간추림] 찬이의 마음을 이해한 남산 타워는 고마워하며 남산으로 돌아간다."],"title":"『국어활동』 스스로 읽기 「비밀의 무게」(심순 글) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#18','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C18',3,'mc','auto','작품 속 세계와 현실 세계를 비교한 뒤 한 걸음 더 나아가 생각할 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X46','K4-2-u1-X02','K4-2-u1-X45']::text[],false,'{"seq":18,"concept":"K4-2-u1-C18","difficulty":3,"kind":"mc","stem":"작품 속 세계와 현실 세계를 비교한 뒤 한 걸음 더 나아가 생각할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"글쓴이가 꾸며 낸 세계를 통해 전하고자 하는 주제가 무엇인지 생각한다","correct":true},{"t":"비슷한 점과 다른 점을 많이 찾았으면 감상이 끝난 것이다","mis":"K4-2-u1-X46"},{"t":"다른 점이 많은 작품은 잘못 쓴 작품이라고 정한다","mis":"K4-2-u1-X02"},{"t":"꾸민 장치를 현실에서 그대로 해 본다","mis":"K4-2-u1-X45"}],"explanation":["비슷한 점과 다른 점을 찾는 활동에서 나아가요.","글쓴이가 허구적 장치로 전하려는 주제를 생각해요.","그러면 현실의 모습을 새로운 관점에서 이해할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#19','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C34',3,'mc','auto','하솔이의 의견대로 학교 운동장을 주민들에게 언제든지 개방했을 때 리윤이가 걱정할 문제는 무엇인가요?',ARRAY['K4-2-u1-X32','K4-2-u1-X24']::text[],false,'{"seq":19,"concept":"K4-2-u1-C34","difficulty":3,"kind":"mc","stem":"하솔이의 의견대로 학교 운동장을 주민들에게 언제든지 개방했을 때 리윤이가 걱정할 문제는 무엇인가요?","options":[{"t":"학생들이 여러 가지 사고나 위험에 노출될 수 있다","correct":true},{"t":"주민들이 운동할 곳이 부족해진다","mis":"K4-2-u1-X32"},{"t":"주변에 공공 체육 시설이 늘어난다","mis":"K4-2-u1-X32"},{"t":"학교가 공공시설이 아니게 된다","mis":"K4-2-u1-X24"}],"explanation":["리윤이는 학교가 가장 안전한 곳이어야 한다고 했어요.","외부인에게 개방하면 위험이 생길 수 있다고 걱정했어요.","반대 의견이 의견대로 했을 때의 문제를 알려 줘요."],"asset":{"type":"passage","lines":["[하솔] 학교 운동장을 주민들에게 개방해야 해요.","[하솔] 첫째, 학교는 공공시설이니 모든 주민이 언제든지 이용할 수 있어야 해요.","[하솔] 둘째, 주변에 공공 체육 시설이 부족해 주민들이 운동할 곳이 없어요.","[리윤] 학교 운동장은 온전히 아이들의 것이어야 해요.","[리윤] 첫째, 학교는 가장 안전한 곳이어야 해요. 외부인에게 개방하면 사고나 위험이 생길 수 있어요.","[리윤] 둘째, 학교의 건물과 시설은 학생들의 학습을 위해 쓰이고 보호되어야 해요."],"title":"하솔이와 리윤이의 글 — 학교 운동장 개방"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#20','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C25',3,'mc','auto','하윤이와 지민이의 의견을 비교한 뒤 낸 새로운 의견으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X23','K4-2-u1-X35','K4-2-u1-X47']::text[],false,'{"seq":20,"concept":"K4-2-u1-C25","difficulty":3,"kind":"mc","stem":"하윤이와 지민이의 의견을 비교한 뒤 낸 새로운 의견으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"혼자 공부하는 공간과 친구들과 함께 편안하게 읽는 공간을 나누어 만든다","correct":true},{"t":"둘 가운데 하나를 꼭 골라야 하니 새 의견은 없다","mis":"K4-2-u1-X23"},{"t":"소파와 책상을 반씩 아무렇게나 놓으면 저절로 가장 좋다","mis":"K4-2-u1-X35"},{"t":"도서관을 아예 없앤다","mis":"K4-2-u1-X47"}],"explanation":["『국어활동』 9쪽 (3)번의 예시예요.","두 의견의 좋은 점을 살펴 새로운 의견을 낼 수 있어요.","모든 친구가 도서관을 즐겁게 이용할 수 있다는 이유도 있어요."],"asset":{"type":"passage","lines":["[간추림] 기사 제목 — 우리 학교 도서관, 새로운 변화가 필요해요","[하윤] 도서관에 소파를 놓거나 마루를 설치하면 좋겠습니다.","[하윤] 도서관이 편안한 공간이 되면 학생들이 도서관을 좋아하게 될 것입니다.","[하윤] 편안한 자리에서 좋아하는 자세로 책을 읽으면 독서가 더 즐거워질 것입니다.","[지민] 도서관에 책상과 의자를 많이 두면 좋겠습니다.","[지민] 도서관은 공부하는 곳이기 때문입니다.","[지민] 바른 자세로 앉아서 책을 읽어야 독서를 더욱 잘할 수 있기 때문입니다."],"title":"초등학교 신문 — 『국어활동』 8쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#21','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C41',3,'mc','auto','김누리의 댓글은 전재현과 윤시완의 어떤 걱정을 함께 살폈나요?',ARRAY['K4-2-u1-X34','K4-2-u1-X47']::text[],false,'{"seq":21,"concept":"K4-2-u1-C41","difficulty":3,"kind":"mc","stem":"김누리의 댓글은 전재현과 윤시완의 어떤 걱정을 함께 살폈나요?","options":[{"t":"주민들이 저녁에 조용히 쉬는 것과 숙소·가게가 운영되는 것","correct":true},{"t":"관광객이 늦게까지 떠드는 것만","mis":"K4-2-u1-X34"},{"t":"가게를 운영하는 것만","mis":"K4-2-u1-X34"},{"t":"쓰레기를 버리는 곳만","mis":"K4-2-u1-X47"}],"explanation":["김누리는 「서로 조금씩 양보해서」라고 했어요.","저녁 8시까지로 시간을 정하면 주민은 쉬고 가게는 운영돼요.","두 걱정을 함께 살핀 의견이에요."],"asset":{"type":"passage","lines":["[전재현의 글] 요즘 우리 한옥 마을이 많은 관광객으로 몸살을 앓고 있습니다.","[전재현의 글] 관광객들이 늦은 시간까지 큰 소리로 떠들고, 집 앞에 쓰레기가 쌓입니다.","[전재현의 글] 주민들이 조용하고 깨끗하게 지내도록 관광객을 제한해 주시면 좋겠습니다.","[윤시완의 댓글] 저는 마을이 관광객들로 더욱 활기찬 것 같아 즐겁습니다.","[윤시완의 댓글] 우리 가족은 관광객을 위한 숙소와 식당을 운영합니다.","[윤시완의 댓글] 관광객을 제한하면 숙소나 가게를 하는 사람들이 경제적으로 어려워집니다.","[김누리의 댓글] 서로 양보해서 저녁 8시까지로 관광 시간을 제한하면 좋겠습니다.","[김누리의 댓글] 주민은 저녁에 쉴 수 있고 숙소나 가게도 운영될 수 있기 때문입니다."],"title":"○○시청 누리집 ‘시민의 소리’ — 『국어』 75쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#22','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C26',3,'mc','auto','글 ㉯ 「무인 안내기, 누군가에게는 큰 불편」에서 조사 결과(사실)를 나타낸 것은 무엇인가요?',ARRAY['K4-2-u1-X24']::text[],false,'{"seq":22,"concept":"K4-2-u1-C26","difficulty":3,"kind":"mc","stem":"글 ㉯ 「무인 안내기, 누군가에게는 큰 불편」에서 조사 결과(사실)를 나타낸 것은 무엇인가요?","options":[{"t":"서울AI(에이아이)재단의 2021년 조사에서 고령층이 무인 안내기를 쓰지 못하는 가장 큰 까닭은 사용 방법을 몰라서였다","correct":true},{"t":"무작정 더 설치하기보다 불편을 줄일 방법을 고민해야 한다","mis":"K4-2-u1-X24"},{"t":"무인 안내기는 누군가에게는 큰 불편이다","mis":"K4-2-u1-X24"},{"t":"불편을 줄일 방법을 함께 찾아야 한다","mis":"K4-2-u1-X24"}],"explanation":["누가 언제 조사했는지 확인할 수 있는 것은 사실이에요.","「~해야 한다」는 글쓴이의 생각, 곧 의견이에요.","사실은 의견을 받쳐 주는 이유로 쓰였어요."],"asset":{"type":"passage","lines":["[간추림] 무인 안내기의 장점 뒤에는 여러 가지 단점이 있다.","첫째, 신체 조건이 맞지 않는 사람은 무인 안내기를 이용하기 어렵습니다.","[간추림] 휠체어를 탄 사람·키가 작은 사람은 쓰기 불편하고, 음성 안내가 없으면 시각 장애인은 못 쓴다.","둘째, 사용 방법이 익숙하지 않은 사람에게 무인 안내기는 전혀 편리하지 않습니다.","[간추림] 서울AI(에이아이)재단 2021년 조사 — 고령층이 못 쓰는 가장 큰 까닭은 사용 방법을 몰라서.","셋째, 현금만 있는 사람은 무인 안내기를 이용하기 어려운 경우가 많습니다.","[간추림] 그러므로 무작정 더 설치하기보다 이용하기 어려운 사람들의 불편을 줄일 방법을 고민해야 한다."],"title":"「무인 안내기, 누군가에게는 큰 불편」(글 ㉯) — 『국어』 70쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#23','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C17',4,'essay','teacher','「언제나 다정 죽집」에서 말하고 움직이는 부엌 친구들이라는 꾸며 쓴 장치가 없다면 이야기가 어떻게 달라질지 쓰고, 이 장치가 읽는 사람에게 주는 것을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u1-C17","difficulty":4,"kind":"essay","stem":"「언제나 다정 죽집」에서 말하고 움직이는 부엌 친구들이라는 꾸며 쓴 장치가 없다면 이야기가 어떻게 달라질지 쓰고, 이 장치가 읽는 사람에게 주는 것을 쓰세요.","answer_guide":{"answer":"예: 부엌 친구들이 없다면 할머니 혼자 마지막 장사를 하는 쓸쓸한 이야기가 되고, 고양이빵 덕분에 과일 가게 아저씨 가족이 행복해지는 일도 없었을 것이다. 부엌 친구들은 할머니 곁을 오래 지켜 온 눈으로 할머니의 다정함을 보여 주어, 읽는 사람에게 재미와 감동을 준다.","scoring_points":["장치가 없을 때 이야기가 어떻게 달라질지 썼는가","장치가 주는 재미·감동·깨달음을 썼는가","이야기 속 장면을 근거로 들었는가"]},"explanation":["글쓴이는 말하고 움직이는 고양이와 부엌 친구들이라는 허구적 장치를 썼어요.","이 장치로 전하려는 주제를 생각해요.","꾸며 쓴 부분은 재미나 감동, 깨달음을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#24','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C36',4,'essay','teacher','「점심시간에 운동장에서 축구를 해도 될까?」를 두고 토의할 때, 찬성하는 친구와 반대하는 친구의 의견을 같은 기준으로 평가해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u1-C36","difficulty":4,"kind":"essay","stem":"「점심시간에 운동장에서 축구를 해도 될까?」를 두고 토의할 때, 찬성하는 친구와 반대하는 친구의 의견을 같은 기준으로 평가해 쓰세요.","answer_guide":{"answer":"예: 찬성 — 축구할 시간이 점심시간뿐이라는 이유는 타당하지만, 저학년 하교 시간과 겹치는 문제를 그물망만으로 다 막기는 어렵다. 반대 — 동생이 다친 경험은 믿을 만한 이유이지만, 축구를 아예 못 하게 되면 고학년이 운동할 시간이 줄어드는 문제가 생긴다. 두 의견 모두 문제 상황과 관련 있지만, 서로의 걱정을 살피는 방법이 더 필요하다.","scoring_points":["두 의견을 같은 기준으로 평가했는가","이유가 타당한지 따졌는가","의견대로 했을 때 생길 문제를 살폈는가"]},"explanation":["한쪽만 따지고 다른 쪽을 그냥 믿지 않아요.","세 가지 기준을 두 의견에 똑같이 대어 봐요.","이유의 개수가 아니라 이유의 힘을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_c#25','kor',4,2,'u1','','tb_g4_2_kor_u1_review_c','unit_review','K4-2-u1-C10',4,'essay','teacher','「스펀지 교실」의 「속상한 일 있을 땐 / 그냥 스펀지 벽에 점프만 하면 돼」를 내 경험을 떠올려 바꾸어 쓰고, 바꾸어 쓴 뒤의 생각이나 느낌을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u1-C10","difficulty":4,"kind":"essay","stem":"「스펀지 교실」의 「속상한 일 있을 땐 / 그냥 스펀지 벽에 점프만 하면 돼」를 내 경험을 떠올려 바꾸어 쓰고, 바꾸어 쓴 뒤의 생각이나 느낌을 쓰세요.","answer_guide":{"answer":"예: 서운한 일 있을 땐 / 스펀지 책상에 볼을 대고 / 친구 이름 한 번 부르면 돼. 생각이나 느낌 — 짝과 다툰 날 말없이 책상에 엎드려 있던 경험을 떠올려 바꾸었다. 현실에서는 어렵지만 이런 교실이라면 서운한 마음을 쉽게 풀 수 있을 것 같아 재미있었다.","scoring_points":["원래 시의 짜임을 살려 바꾸었는가","내 경험과 현실 세계를 떠올려 바꾸었는가","바꾸어 쓴 뒤의 생각이나 느낌을 썼는가"]},"explanation":["『국어』 42쪽 5번 (1)·(2)번 활동이에요.","작품 속 세계와 현실 세계를 비교한 것을 바탕으로 상상력을 발휘해요.","바꾼 뒤의 생각이나 느낌을 친구들과 나누어요."],"asset":{"type":"passage","lines":["속상한 일 있을 땐","그냥 스펀지 벽에 점프만 하면 돼","[간추림] 서로의 눈빛만으로 웃음이 터지는 마법 같은 교실이다.","스펀지 책상의 둥근 모서리처럼","우리도 점점 둥글어지고 있어"],"title":"「스펀지 교실」(권기덕) 뒷부분 — 『국어』 39쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#1','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C32',1,'ox','auto','『국어』 77쪽 「정리하기」예요. 글쓴이의 의견을 비교하고 평가하면 더 적절한 의견이 무엇인지 알 수 있어요.',ARRAY['K4-2-u1-X22']::text[],false,'{"seq":1,"concept":"K4-2-u1-C32","difficulty":1,"kind":"ox","stem":"『국어』 77쪽 「정리하기」예요. 글쓴이의 의견을 비교하고 평가하면 더 적절한 의견이 무엇인지 알 수 있어요.","answer":"O","reason_options":[{"t":"문제 상황에 맞는지, 이유가 타당한지 따져 보게 되기 때문에","correct":true},{"t":"의견은 모두 맞으니 평가해도 달라지는 것이 없기 때문에","mis":"K4-2-u1-X22"}],"mis":"K4-2-u1-X22","explanation":["「정리하기」에서 ○ 표를 하는 문장이에요.","평가할 때는 문제 상황, 이유, 의견대로 했을 때의 문제를 살펴요.","그러면 더 적절한 의견을 찾을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#2','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C3',1,'mc','auto','『국어』 37쪽에서 친구가 「소금을 만드는 맷돌」을 맷돌이 바다에 빠져 바닷물이 짜졌다고 꾸며 쓴 이야기라고 소개했어요. 이렇게 꾸며 쓴 부분에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X02','K4-2-u1-X01','K4-2-u1-X06']::text[],false,'{"seq":2,"concept":"K4-2-u1-C3","difficulty":1,"kind":"mc","stem":"『국어』 37쪽에서 친구가 「소금을 만드는 맷돌」을 맷돌이 바다에 빠져 바닷물이 짜졌다고 꾸며 쓴 이야기라고 소개했어요. 이렇게 꾸며 쓴 부분에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"현실과 달라도 읽는 재미와 상상하는 즐거움을 준다","correct":true},{"t":"거짓말이니 이야기에서 빼야 한다","mis":"K4-2-u1-X02"},{"t":"바닷물은 실제로 맷돌 때문에 짜졌다","mis":"K4-2-u1-X01"},{"t":"현실과 다르니 읽을 필요가 없다","mis":"K4-2-u1-X06"}],"explanation":["바닷물이 짠 까닭을 맷돌로 꾸며 썼어요.","현실과 다르지만 거짓말이 아니라 상상의 재미예요.","꾸며 쓴 부분 덕분에 이야기가 더 즐거워져요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"내 주변에도 형과 사이가 좋은 친구가 있는데 그런 모습이 「의좋은 형제」에 잘 나타나 있어."},{"who":"친구 2","text":"「소가 된 게으름뱅이」는 게으른 농부가 소가 된다고 상상해서 지어낸 이야기야."},{"who":"친구 3","text":"「소금을 만드는 맷돌」은 맷돌이 바다에 빠져 바닷물이 짜졌다고 꾸며 쓴 이야기야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#3','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C2',1,'mc','auto','『심청전』에서 심청이 공양미 삼백 석을 마련하려 한 일과 연꽃에서 다시 살아 나온 일 가운데 현실에서 일어나기 어려운 일은 무엇인가요?',ARRAY['K4-2-u1-X44','K4-2-u1-X01']::text[],false,'{"seq":3,"concept":"K4-2-u1-C2","difficulty":1,"kind":"mc","stem":"『심청전』에서 심청이 공양미 삼백 석을 마련하려 한 일과 연꽃에서 다시 살아 나온 일 가운데 현실에서 일어나기 어려운 일은 무엇인가요?","options":[{"t":"연꽃에서 다시 살아 나온 일","correct":true},{"t":"공양미를 마련하려 한 일","mis":"K4-2-u1-X44"},{"t":"둘 다 현실에서 흔히 일어나는 일","mis":"K4-2-u1-X01"},{"t":"둘 다 현실에서 일어날 수 없는 일","mis":"K4-2-u1-X44"}],"explanation":["부모님을 위해 애쓰는 일은 현실에서도 볼 수 있어요.","죽었던 사람이 연꽃에서 살아 나오는 일은 현실에서 일어나기 어려워요.","작품에는 현실과 비슷한 부분과 다른 부분이 함께 있어요."],"asset":{"type":"speech","turns":[{"who":"수아","text":"민균아, 『심청전』 읽어 봤어? 효녀 심청에 대한 이야기야."},{"who":"민균","text":"그럼, 읽어 봤지! 심청이 아버지의 눈을 뜨게 하려고 바다에 빠져서 안타까웠어."},{"who":"수아","text":"심청이 연꽃에서 다시 살아 나오는 장면은 신기했어."},{"who":"민균","text":"나는 앞을 못 보던 아버지가 다시 살아난 심청을 만나서 눈을 번쩍 뜨는 장면이 정말 감동적이었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#4','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C26',1,'ox','auto','글 ㉯의 「지난봄에 하교하던 1학년 동생이 축구공에 맞아서 다친 적이 있어요.」는 글쓴이의 의견이에요.',ARRAY['K4-2-u1-X24']::text[],false,'{"seq":4,"concept":"K4-2-u1-C26","difficulty":1,"kind":"ox","stem":"글 ㉯의 「지난봄에 하교하던 1학년 동생이 축구공에 맞아서 다친 적이 있어요.」는 글쓴이의 의견이에요.","answer":"X","reason_options":[{"t":"실제로 있었던 일로, 반대 의견을 받쳐 주는 이유로 쓰였기 때문에","correct":true},{"t":"글에 나온 문장은 모두 의견이기 때문에","mis":"K4-2-u1-X24"}],"mis":"K4-2-u1-X24","explanation":["있었던 일(사실)과 의견은 달라요.","글 ㉯의 의견은 점심시간 운동장 축구에 반대한다는 것이에요.","동생이 다친 일은 그 의견을 받쳐 주는 이유예요."],"asset":{"type":"passage","lines":["[간추림] 점심시간이 급식을 먹은 뒤 자유롭게 쉬는 시간인 것은 맞다.","그런데 우리 학교 고학년의 점심시간은 저학년의 하교 시간이기도 해요.","지난봄에 하교하던 1학년 동생이 축구공에 맞아서 다친 적이 있어요.","[간추림] 축구를 하는 사람도 크게 다칠 위험이 있다.","[간추림] 그래서 모두의 안전을 위해 점심시간 운동장 축구에 반대한다."],"title":"「점심시간에 운동장에서 축구를 하는 것은 위험해요」(글 ㉯) — 『국어』 63쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#5','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C43',1,'sa','auto','「먹다」에 하려는 뜻의 말을 붙여 「점심을 ○○○○ 식당에 갔다.」의 ○○○○에 들어갈 말을 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u1-C43","difficulty":1,"kind":"sa","stem":"「먹다」에 하려는 뜻의 말을 붙여 「점심을 ○○○○ 식당에 갔다.」의 ○○○○에 들어갈 말을 쓰세요.","answer":["먹으려고"],"explanation":["「먹-」처럼 받침이 있는 말에는 「-으려고」를 붙여요.","그래서 「먹으려고」예요.","「먹을려고」처럼 ㄹ을 덧붙이지 않아요."],"mis":"K4-2-u1-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#6','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C44',1,'match','auto','「-(으)ㅁ」을 붙여 바꾼 낱말을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u1-C44","difficulty":1,"kind":"match","stem":"「-(으)ㅁ」을 붙여 바꾼 낱말을 알맞게 이으세요.","pairs":[{"l":"웃다","r":"웃음"},{"l":"느끼다","r":"느낌"},{"l":"슬프다","r":"슬픔"}],"mis":"K4-2-u1-X41","explanation":["받침이 있는 「웃-」에는 「-음」을 붙여요.","받침이 없는 「느끼-」, 「슬프-」에는 「-ㅁ」을 붙여요.","「웃음」, 「느낌」, 「슬픔」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#7','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C45',1,'mc','auto','ㅆ 받침을 바르게 쓴 낱말끼리 모은 것은 무엇인가요?',ARRAY['K4-2-u1-X42']::text[],false,'{"seq":7,"concept":"K4-2-u1-C45","difficulty":1,"kind":"mc","stem":"ㅆ 받침을 바르게 쓴 낱말끼리 모은 것은 무엇인가요?","options":[{"t":"갔다 · 좋겠다 · 있다","correct":true},{"t":"갓다 · 좋겟다 · 잇다","mis":"K4-2-u1-X42"},{"t":"갔다 · 좋겠다 · 읻다","mis":"K4-2-u1-X42"},{"t":"같다 · 좋겠다 · 있다","mis":"K4-2-u1-X42"}],"explanation":["『국어』 79쪽 글씨 쓰기 낱말이에요.","세 낱말 모두 ㅆ 받침이 있어요.","ㅆ 받침을 ㅅ이나 다른 받침으로 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#8','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C31',1,'mc','auto','「다양한 무인 안내기를 설치하여 활용해야 합니다.」에서 「설치하여」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":8,"concept":"K4-2-u1-C31","difficulty":1,"kind":"mc","stem":"「다양한 무인 안내기를 설치하여 활용해야 합니다.」에서 「설치하여」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"필요한 기구나 시설 따위를 두어","correct":true},{"t":"값을 치러","mis":"K4-2-u1-X12"},{"t":"무르고 약하여","mis":"K4-2-u1-X12"},{"t":"편하고 이로우며","mis":"K4-2-u1-X12"}],"explanation":["『국어』 71쪽 「낱말 알기」예요.","「설치하다」는 필요한 기구나 시설 따위를 둔다는 뜻이에요.","무인 안내기를 여러 곳에 둔다는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#9','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C11',2,'mc','auto','「현실의 모습을 새로운 눈으로 폭넓게 이해할 수 있다」는 무엇을 하면 좋은 점인가요?',ARRAY['K4-2-u1-X10','K4-2-u1-X49','K4-2-u1-X01']::text[],false,'{"seq":9,"concept":"K4-2-u1-C11","difficulty":2,"kind":"mc","stem":"「현실의 모습을 새로운 눈으로 폭넓게 이해할 수 있다」는 무엇을 하면 좋은 점인가요?","options":[{"t":"작품 속 세계와 현실 세계를 비교하며 읽을 때","correct":true},{"t":"글을 소리 내어 빨리 읽을 때","mis":"K4-2-u1-X10"},{"t":"중심 문장과 뒷받침 문장을 찾을 때","mis":"K4-2-u1-X49"},{"t":"작품 속 일을 모두 사실로 믿을 때","mis":"K4-2-u1-X01"}],"explanation":["『국어』 43쪽 7번에서 친구가 말한 좋은 점이에요.","『국어활동』 7쪽 3번의 「해」 칸에도 있어요.","비교하며 읽으면 익숙한 현실을 새롭게 보게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#10','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C2',2,'mc','auto','작품에서 현실의 모습을 비슷하게 나타냈다는 것은 무슨 뜻인가요?',ARRAY['K4-2-u1-X01','K4-2-u1-X07','K4-2-u1-X45']::text[],false,'{"seq":10,"concept":"K4-2-u1-C2","difficulty":2,"kind":"mc","stem":"작품에서 현실의 모습을 비슷하게 나타냈다는 것은 무슨 뜻인가요?","options":[{"t":"작품 속 인물, 사건, 배경 등이 우리의 현실과 비슷하다는 뜻","correct":true},{"t":"작품이 실제로 있었던 일만 담았다는 뜻","mis":"K4-2-u1-X01"},{"t":"작품에 그림이 많다는 뜻","mis":"K4-2-u1-X07"},{"t":"작품 속 일을 현실에서 그대로 따라 해야 한다는 뜻","mis":"K4-2-u1-X45"}],"explanation":["『국어』 37쪽 2번 활동의 바탕이 되는 생각이에요.","인물·사건·배경이 현실과 비슷하면 현실을 비슷하게 나타낸 거예요.","다르면 현실과 다르게 표현한 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#11','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C12',2,'mc','auto','키다리 아저씨가 「이 죽집 이름이 맛의 비밀이었어요.」라고 한 까닭은 무엇인가요?',ARRAY['K4-2-u1-X11','K4-2-u1-X16']::text[],false,'{"seq":11,"concept":"K4-2-u1-C12","difficulty":2,"kind":"mc","stem":"키다리 아저씨가 「이 죽집 이름이 맛의 비밀이었어요.」라고 한 까닭은 무엇인가요?","options":[{"t":"팥죽 맛의 비밀이 할머니의 다정함이었기 때문에","correct":true},{"t":"죽집 이름에 재료가 적혀 있기 때문에","mis":"K4-2-u1-X11"},{"t":"팥냥이의 꾹꾹이 덕분이기 때문에","mis":"K4-2-u1-X16"},{"t":"이름을 바꾸면 맛이 달라지기 때문에","mis":"K4-2-u1-X11"}],"explanation":["죽집 이름은 ‘다정’이에요.","할머니는 기운을 들이고 사람을 살리는 음식이라 믿고 넉넉하게 나눴어요.","알아주지 않아도 몸과 마음을 돌보는 다정함이 비밀이었어요."],"asset":{"type":"passage","lines":["[간추림] 건물 주인 베레모 아저씨가 가게를 넘겨받을 키다리 아저씨와 함께 왔다.","[간추림] 할머니는 넉넉한 대접에 팥죽을 그득 담아 두 사람에게 내었다.","“비결이랄 게 있나요. 그저 팥죽을 팥죽답게 끓였을 뿐이지요.”","[간추림] 좋은 재료를 고집하고 얕은수는 쓰지 않았으며, 늘 넉넉하게 나눴다고 했다.","“이 죽집 이름이 맛의 비밀이었어요.”"],"title":"「언제나 다정 죽집」 뒷부분 — 『국어』 54~57쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#12','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C14',2,'error','auto','인물의 성격을 짐작한 것 가운데 근거가 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u1-X13']::text[],false,'{"seq":12,"concept":"K4-2-u1-C14","difficulty":2,"kind":"error","stem":"인물의 성격을 짐작한 것 가운데 근거가 알맞지 않은 것은 무엇인가요?","options":[{"t":"할머니는 정직하다 — 가게 문에 고양이 모양 풍경이 걸려 있기 때문이다","correct":true,"mis_target":"K4-2-u1-X13"},{"t":"부엌 친구들은 긍정적이다 — 「결과가 어떻게 될지 모르지만, 최선을 다해 보자」라고 했다","mis":"K4-2-u1-X13"},{"t":"할머니는 다정하다 — 아기 몫까지 고양이빵을 챙겨 주었다","mis":"K4-2-u1-X13"}],"explanation":["성격의 근거는 인물의 말이나 행동이어야 해요.","풍경이 걸려 있는 것은 할머니의 말이나 행동이 아니에요.","할머니가 정직하다는 근거는 설탕을 넣지 않겠다는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#13','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C25',2,'mc','auto','『국어활동』 9쪽 「더 알아보기」에서 다양한 의견을 생각하고 비교하면 좋다며 떠올려 보라고 한 것은 무엇인가요?',ARRAY['K4-2-u1-X23','K4-2-u1-X33','K4-2-u1-X30']::text[],false,'{"seq":13,"concept":"K4-2-u1-C25","difficulty":2,"kind":"mc","stem":"『국어활동』 9쪽 「더 알아보기」에서 다양한 의견을 생각하고 비교하면 좋다며 떠올려 보라고 한 것은 무엇인가요?","options":[{"t":"글쓴이의 의견과는 다른 새로운 의견과 그 이유","correct":true},{"t":"글쓴이의 의견을 그대로 베낀 문장","mis":"K4-2-u1-X23"},{"t":"두 의견 가운데 더 긴 것","mis":"K4-2-u1-X33"},{"t":"글쓴이의 이름","mis":"K4-2-u1-X30"}],"explanation":["「새로운 의견을 생각해 봐요」라는 제목이에요.","글쓴이의 의견과 다른 새로운 의견과 이유를 떠올릴 수 있어요.","그러면 글을 더 깊이 있게 읽을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#14','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C27',2,'ox','auto','글의 제목은 믿을 수 없으니 글쓴이의 의견을 파악할 때 아예 보지 않는 것이 좋아요.',ARRAY['K4-2-u1-X26']::text[],false,'{"seq":14,"concept":"K4-2-u1-C27","difficulty":2,"kind":"ox","stem":"글의 제목은 믿을 수 없으니 글쓴이의 의견을 파악할 때 아예 보지 않는 것이 좋아요.","answer":"X","reason_options":[{"t":"제목은 글쓴이의 의견을 짐작하게 해 주는 실마리이기 때문에","correct":true},{"t":"제목은 글의 내용과 상관없기 때문에","mis":"K4-2-u1-X26"}],"mis":"K4-2-u1-X26","explanation":["제목을 주의 깊게 살펴보면 의견을 짐작할 수 있어요.","다만 제목만으로 정하지 말고 글을 읽으며 확인해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#15','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C32',2,'mc','auto','『국어활동』 9쪽에서 하윤이와 지민이의 의견을 평가할 때 쓴 두 물음은 무엇인가요?',ARRAY['K4-2-u1-X30','K4-2-u1-X21','K4-2-u1-X22']::text[],false,'{"seq":15,"concept":"K4-2-u1-C32","difficulty":2,"kind":"mc","stem":"『국어활동』 9쪽에서 하윤이와 지민이의 의견을 평가할 때 쓴 두 물음은 무엇인가요?","options":[{"t":"문제 상황에 적절한 의견인가요? · 의견을 뒷받침하는 이유가 적절한가요?","correct":true},{"t":"글이 몇 줄인가요? · 글쓴이가 몇 반인가요?","mis":"K4-2-u1-X30"},{"t":"누가 먼저 썼나요? · 누가 더 친한가요?","mis":"K4-2-u1-X21"},{"t":"내 마음에 드나요? · 재미있나요?","mis":"K4-2-u1-X22"}],"explanation":["『국어활동』 9쪽 (2)번 표의 물음이에요.","두 물음마다 매우 적절함·적절함·보통임으로 평가해요.","글의 길이나 친한 정도는 기준이 아니에요."],"asset":{"type":"passage","lines":["[간추림] 기사 제목 — 우리 학교 도서관, 새로운 변화가 필요해요","[하윤] 도서관에 소파를 놓거나 마루를 설치하면 좋겠습니다.","[하윤] 도서관이 편안한 공간이 되면 학생들이 도서관을 좋아하게 될 것입니다.","[하윤] 편안한 자리에서 좋아하는 자세로 책을 읽으면 독서가 더 즐거워질 것입니다.","[지민] 도서관에 책상과 의자를 많이 두면 좋겠습니다.","[지민] 도서관은 공부하는 곳이기 때문입니다.","[지민] 바른 자세로 앉아서 책을 읽어야 독서를 더욱 잘할 수 있기 때문입니다."],"title":"초등학교 신문 — 『국어활동』 8쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#16','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C39',2,'mc','auto','감상한 작품을 소개할 때 「작품 속 세계와 현실 세계 비교하기」 단계에서 할 일은 무엇인가요?',ARRAY['K4-2-u1-X37','K4-2-u1-X45','K4-2-u1-X10']::text[],false,'{"seq":16,"concept":"K4-2-u1-C39","difficulty":2,"kind":"mc","stem":"감상한 작품을 소개할 때 「작품 속 세계와 현실 세계 비교하기」 단계에서 할 일은 무엇인가요?","options":[{"t":"작품 속 세계와 현실 세계의 비슷한 점과 다른 점을 스스로 정리한다","correct":true},{"t":"줄거리를 처음부터 끝까지 받아쓴다","mis":"K4-2-u1-X37"},{"t":"작품 속 장면을 현실에서 그대로 따라 한다","mis":"K4-2-u1-X45"},{"t":"작품에서 틀린 곳을 찾는다","mis":"K4-2-u1-X10"}],"explanation":["『국어』 74쪽 2번이에요.","비슷한 점과 다른 점을 스스로 정리해요.","정리한 내용을 바탕으로 친구들에게 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#17','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C8',3,'mc','auto','「황금 알을 낳는 거위」에서 가난한 농부, 시장, 넓은 집처럼 현실과 닮은 부분에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X05','K4-2-u1-X06','K4-2-u1-X01']::text[],false,'{"seq":17,"concept":"K4-2-u1-C8","difficulty":3,"kind":"mc","stem":"「황금 알을 낳는 거위」에서 가난한 농부, 시장, 넓은 집처럼 현실과 닮은 부분에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"현실과 닮은 부분도 글쓴이가 욕심의 결과를 보여 주려고 골라 엮은 것이다","correct":true},{"t":"황금 알 말고는 모두 실제로 있었던 일이다","mis":"K4-2-u1-X05"},{"t":"옛이야기는 다 꾸민 것이니 현실과 견줄 필요가 없다","mis":"K4-2-u1-X06"},{"t":"현실과 닮은 부분이 있으니 황금 알도 있을 수 있다","mis":"K4-2-u1-X01"}],"explanation":["작품 전체가 글쓴이가 만든 세계예요.","현실과 닮은 부분도 전하려는 생각을 위해 고른 것이에요.","그래도 현실과 견주어 보면 작품을 더 깊이 이해할 수 있어요."],"asset":{"type":"passage","lines":["[간추림] 옛날 어느 마을에 가난한 농부가 시장에서 거위 한 마리를 샀다.","[간추림] 거위는 아침마다 번쩍이는 황금 알을 한 개씩 낳았다.","[간추림] 농부는 황금 알을 팔아 부자가 되고 넓은 집도 샀지만, 점점 욕심이 생겼다.","[간추림] “거위 뱃속에 황금 알이 가득할 거야!” 농부는 거위의 배를 갈랐다.","[간추림] 뱃속에는 황금 알이 하나도 없었고, 농부는 거위도 잃고 다시 가난해졌다."],"title":"평가 글 「황금 알을 낳는 거위」(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#18','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C18',3,'ox','auto','「언제나 다정 죽집」을 읽고 이야기와 현실의 비슷한 점과 다른 점을 표로 정리했다면, 글쓴이가 전하려는 생각은 따로 생각하지 않아도 돼요.',ARRAY['K4-2-u1-X46']::text[],false,'{"seq":18,"concept":"K4-2-u1-C18","difficulty":3,"kind":"ox","stem":"「언제나 다정 죽집」을 읽고 이야기와 현실의 비슷한 점과 다른 점을 표로 정리했다면, 글쓴이가 전하려는 생각은 따로 생각하지 않아도 돼요.","answer":"X","reason_options":[{"t":"비교한 것을 바탕으로 글쓴이가 꾸며 낸 세계로 무엇을 전하려는지까지 생각해야 깊이 감상할 수 있기 때문에","correct":true},{"t":"비슷한 점과 다른 점을 찾는 것이 감상의 끝이기 때문에","mis":"K4-2-u1-X46"}],"mis":"K4-2-u1-X46","explanation":["『국어』 61쪽은 (1)번 비교 다음에 (2)번 주제 이야기하기가 이어져요.","비교한 결과만이 아니라 주제를 탐색하는 과정이 중요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#19','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C34',3,'mc','auto','전재현의 의견대로 마을에 오는 관광객을 크게 제한했을 때 생길 수 있는 문제는 무엇인가요?',ARRAY['K4-2-u1-X32']::text[],false,'{"seq":19,"concept":"K4-2-u1-C34","difficulty":3,"kind":"mc","stem":"전재현의 의견대로 마을에 오는 관광객을 크게 제한했을 때 생길 수 있는 문제는 무엇인가요?","options":[{"t":"숙소나 가게를 운영하는 주민들이 경제적으로 어려워질 수 있다","correct":true},{"t":"밤에 마을이 더 시끄러워진다","mis":"K4-2-u1-X32"},{"t":"집 앞에 쓰레기가 더 쌓인다","mis":"K4-2-u1-X32"},{"t":"관광객이 더 많이 온다","mis":"K4-2-u1-X32"}],"explanation":["윤시완의 댓글이 실마리예요.","관광객이 줄면 숙소와 식당을 하는 사람들이 어려워져요.","의견대로 했을 때 누가 어떤 어려움을 겪을지 살펴요."],"asset":{"type":"passage","lines":["[전재현의 글] 요즘 우리 한옥 마을이 많은 관광객으로 몸살을 앓고 있습니다.","[전재현의 글] 관광객들이 늦은 시간까지 큰 소리로 떠들고, 집 앞에 쓰레기가 쌓입니다.","[전재현의 글] 주민들이 조용하고 깨끗하게 지내도록 관광객을 제한해 주시면 좋겠습니다.","[윤시완의 댓글] 저는 마을이 관광객들로 더욱 활기찬 것 같아 즐겁습니다.","[윤시완의 댓글] 우리 가족은 관광객을 위한 숙소와 식당을 운영합니다.","[윤시완의 댓글] 관광객을 제한하면 숙소나 가게를 하는 사람들이 경제적으로 어려워집니다.","[김누리의 댓글] 서로 양보해서 저녁 8시까지로 관광 시간을 제한하면 좋겠습니다.","[김누리의 댓글] 주민은 저녁에 쉴 수 있고 숙소나 가게도 운영될 수 있기 때문입니다."],"title":"○○시청 누리집 ‘시민의 소리’ — 『국어』 75쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#20','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C37',3,'mc','auto','새로운 의견 「공간을 나누어 만들자」를 평가하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X34','K4-2-u1-X35','K4-2-u1-X33']::text[],false,'{"seq":20,"concept":"K4-2-u1-C37","difficulty":3,"kind":"mc","stem":"새로운 의견 「공간을 나누어 만들자」를 평가하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"이 의견도 문제 상황에 맞는지, 이유가 타당한지, 다른 문제가 없는지 같은 기준으로 따진다","correct":true},{"t":"내가 낸 의견이니 따질 필요가 없다","mis":"K4-2-u1-X34"},{"t":"두 의견을 섞었으니 저절로 가장 좋다","mis":"K4-2-u1-X35"},{"t":"이유가 하나뿐이면 틀린 의견이다","mis":"K4-2-u1-X33"}],"explanation":["새 의견도 같은 기준으로 평가해요.","섞었다고 저절로 좋아지지 않아요.","이유의 개수가 아니라 이유의 힘을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#21','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C40',3,'mc','auto','전재현이 관광객을 제한해 달라는 의견의 이유로 든 것은 무엇인가요?',ARRAY['K4-2-u1-X19']::text[],false,'{"seq":21,"concept":"K4-2-u1-C40","difficulty":3,"kind":"mc","stem":"전재현이 관광객을 제한해 달라는 의견의 이유로 든 것은 무엇인가요?","options":[{"t":"관광객들이 늦은 시간까지 떠들고, 집 앞에 쓰레기를 버리고 간다","correct":true},{"t":"가족이 숙소와 식당을 운영한다","mis":"K4-2-u1-X19"},{"t":"마을이 관광객들로 활기차서 즐겁다","mis":"K4-2-u1-X19"},{"t":"저녁 8시까지로 관광 시간을 정하면 된다","mis":"K4-2-u1-X19"}],"explanation":["전재현은 마을이 관광객으로 몸살을 앓는다고 했어요.","늦은 시간의 소음과 쓰레기가 이유예요.","나머지는 다른 사람의 말이에요."],"asset":{"type":"passage","lines":["[전재현의 글] 요즘 우리 한옥 마을이 많은 관광객으로 몸살을 앓고 있습니다.","[전재현의 글] 관광객들이 늦은 시간까지 큰 소리로 떠들고, 집 앞에 쓰레기가 쌓입니다.","[전재현의 글] 주민들이 조용하고 깨끗하게 지내도록 관광객을 제한해 주시면 좋겠습니다.","[윤시완의 댓글] 저는 마을이 관광객들로 더욱 활기찬 것 같아 즐겁습니다.","[윤시완의 댓글] 우리 가족은 관광객을 위한 숙소와 식당을 운영합니다.","[윤시완의 댓글] 관광객을 제한하면 숙소나 가게를 하는 사람들이 경제적으로 어려워집니다.","[김누리의 댓글] 서로 양보해서 저녁 8시까지로 관광 시간을 제한하면 좋겠습니다.","[김누리의 댓글] 주민은 저녁에 쉴 수 있고 숙소나 가게도 운영될 수 있기 때문입니다."],"title":"○○시청 누리집 ‘시민의 소리’ — 『국어』 75쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#22','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C24',3,'mc','auto','의견이 다른 친구와 토의할 때 「다양한 의견을 존중한다」는 것의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X43','K4-2-u1-X36','K4-2-u1-X22']::text[],false,'{"seq":22,"concept":"K4-2-u1-C24","difficulty":3,"kind":"mc","stem":"의견이 다른 친구와 토의할 때 「다양한 의견을 존중한다」는 것의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"친구의 의견과 이유를 끝까지 듣고, 나와 달라도 이유를 따져 함께 더 나은 방법을 찾는다","correct":true},{"t":"다툼이 없도록 친구 의견을 무조건 따른다","mis":"K4-2-u1-X43"},{"t":"내 의견과 다르면 틀렸다고 말한다","mis":"K4-2-u1-X36"},{"t":"이유는 묻지 않고 많은 사람 쪽을 따른다","mis":"K4-2-u1-X22"}],"explanation":["평가 자료 2는 서로의 의견과 이유를 비교하고 평가하며 토의해요.","다른 의견을 존중하되 이유는 따져 봐요.","그래야 함께 더 나은 방법을 찾을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#23','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C16',4,'essay','teacher','「비밀의 무게」의 간추린 내용을 읽고, 현실에서 일어나기 어려운 일과 현실에서도 겪을 수 있는 일을 하나씩 찾아 쓰고, 글쓴이가 전하고 싶은 생각을 짐작해 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u1-C16","difficulty":4,"kind":"essay","stem":"「비밀의 무게」의 간추린 내용을 읽고, 현실에서 일어나기 어려운 일과 현실에서도 겪을 수 있는 일을 하나씩 찾아 쓰고, 글쓴이가 전하고 싶은 생각을 짐작해 쓰세요.","answer_guide":{"answer":"예: 일어나기 어려운 일 — 남산 타워가 찬이의 방에 찾아와 침대에 눕는다. 겪을 수 있는 일 — 비밀을 지키느라 말과 행동을 조심하다 보니 마음이 점점 무거워진다. 전하고 싶은 생각 — 겉으로 화려해 보이는 것에도 남모르는 어려움이 있고, 다른 사람의 힘든 마음을 이해해 주는 것이 소중하다.","scoring_points":["현실에서 일어나기 어려운 일을 찾았는가","현실에서도 겪을 수 있는 일을 찾았는가","두 가지를 바탕으로 글쓴이의 생각을 짐작했는가"]},"explanation":["『국어활동』 스스로 읽기 작품이에요.","자신의 경험을 바탕으로 사실과 허구를 비교하며 읽어요.","허구적으로 표현한 부분에 대한 생각도 나누어 보아요."],"asset":{"type":"passage","lines":["[간추림] 찬이는 기분이 좋지 않을 때마다 창밖의 남산 타워를 부러워하며 바라본다.","[간추림] 찬이가 놀러 오라고 말하자 남산 타워가 정말로 찬이 방에 찾아온다.","[간추림] 가까이서 본 남산 타워는 먼지투성이였고, 밤낮없이 서 있어 피곤하다며 침대에 눕는다.","[간추림] 찬이는 비밀을 지키려고 학교와 집에서 말과 행동을 조심하다 마음이 무거워진다.","[간추림] 찬이의 마음을 이해한 남산 타워는 고마워하며 남산으로 돌아간다."],"title":"『국어활동』 스스로 읽기 「비밀의 무게」(심순 글) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#24','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C38',4,'essay','teacher','토의에서 나와 의견이 다른 친구에게 존중하는 말투로 내 의견과 이유를 전하는 말을 쓰세요. 친구 의견의 좋은 점도 한 가지 넣으세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u1-C38","difficulty":4,"kind":"essay","stem":"토의에서 나와 의견이 다른 친구에게 존중하는 말투로 내 의견과 이유를 전하는 말을 쓰세요. 친구 의견의 좋은 점도 한 가지 넣으세요.","answer_guide":{"answer":"예: 민서야, 학급 문고를 없애면 책이 없어질 걱정은 사라진다는 네 생각에는 나도 고개가 끄덕여져. 그런데 나는 책 빌리기 공책을 만드는 것이 더 좋다고 생각해. 왜냐하면 누가 빌렸는지 알 수 있어서 책도 지키고, 우리가 책을 읽을 기회도 그대로 남기 때문이야.","scoring_points":["친구 의견의 좋은 점을 인정했는가","내 의견과 이유를 밝혔는가","존중하는 말투로 썼는가"]},"explanation":["자신의 의견은 글쓴이나 친구의 의견과 다를 수 있어요.","다양한 의견을 서로 존중해야 해요.","존중하면서도 이유는 또렷하게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u1_review_d#25','kor',4,2,'u1','','tb_g4_2_kor_u1_review_d','unit_review','K4-2-u1-C15',4,'essay','teacher','「언제나 다정 죽집」의 부엌 친구들처럼 친구들과 힘을 모아 어려운 일을 해낸 경험을 쓰고, 그 경험을 바탕으로 이야기의 세계와 현실 세계의 비슷한 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u1-C15","difficulty":4,"kind":"essay","stem":"「언제나 다정 죽집」의 부엌 친구들처럼 친구들과 힘을 모아 어려운 일을 해낸 경험을 쓰고, 그 경험을 바탕으로 이야기의 세계와 현실 세계의 비슷한 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 경험 — 학예회 때 반 친구들과 연극을 준비하면서 대사를 서로 봐 주고 소품을 나누어 만들어 무대를 무사히 마쳤다. 비슷한 점 — 부엌 친구들이 저마다 맡은 일을 하며 마음을 모아 고양이빵을 만들었듯, 현실에서도 각자 맡은 일을 열심히 하고 힘을 합치면 어려운 일을 해낼 수 있다.","scoring_points":["힘을 모아 어려운 일을 해낸 경험을 썼는가","경험이 부엌 친구들의 모습과 이어지는가","이야기와 현실의 비슷한 점을 썼는가"]},"explanation":["『국어』 60쪽의 예시 「연극 공연을 위해 친구들과 함께 힘을 합쳐 연습한 적이 있어.」와 같은 경험이에요.","경험을 바탕으로 이야기와 현실을 비교해요.","현실과 닮은 부분이 있어서 이야기에 공감할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
